 v_eot DATE := TO_DATE('22000101','yyyymmdd');
 v_periodo VARCHAR2(50 BYTE);
-- v_ultima_carga integer;
 v_carga integer;
 --ALM 20160223: contador para la inserccion en debug
 v_contador integer; 
 --ALM 20160511: variable que marca si se recargan o no las tablas temporales
 v_recarga_temp integer; 
 --ALM 20170420: variable que marca los pagos cerrados en un periodo. Si es 0 el periodo no esta finalizado.
 v_periodo_finalizado integer;
 --ALM 20171113: variable que marca el numero de pagos posteados en un periodo.
 v_periodo_posteado integer;
 --ALM 20180419: variable que devuelve si se debe detener la ejecucion
 v_stop number(1);
 --ALM 20181029: variable que devuelve si se debe cargar las tablas por defecto o las que se indican en la clasificacion.
 v_tablas_a_cargar varchar2(20 byte);
 --ALM 20220221: Incluimos un nuevo paramero para el control de los periodos con calculos sobre valores cobrados.
 v_FV_EstadoTrx number(1);

-- %%BRG 20250521: Función para conseguir datos relacionados con el periodo actual (únicamente para trabajar con el PERIODSEQ)

function getPeriodRow(i_periodName varchar2, i_calendarName varchar2 := 'Main Monthly Calendar') return cs_period%rowtype as
    v_ret cs_period%rowtype;
  begin
    SELECT per.* into v_ret
    FROM cs_calendar cal
    JOIN cs_period per ON
       cal.calendarseq = per.calendarseq
    WHERE per.removedate = v_eot
        AND cal.removedate = v_eot
        AND per.name = initcap(i_periodName)
        AND cal.name = i_calendarName;
    
    return v_ret;
  exception
    when others THEN
      raise_application_error(-20000, 'Invalid period "'||i_periodName||'" AND calendar "'||i_calendarName||'" combination.', true);
  end;

-- %%BRG 20250521: Procedimiento para el debug (en HANA, CALL EXT.LIB_GLOBAL:WRITE_LOG)

procedure w_debug ( txt IN VARCHAR2, valor IN Number)
AS
    proc_name VARCHAR2(50 CHAR) := $$PLSQL_UNIT ; -- Nombre del procedimiento para DEBUG
    
begin
    INSERT INTO cs_debug(tenantid, datetime,text,VALUE) VALUES (SUBSTR (USER,1,4),SYSDATE, proc_name || ' ' || txt, valor);
    SELECT v_contador + 1 INTO v_contador FROM dual;
    COMMIT;
end;

-- %%BRG 20250521: Procedimiento para detener el proceso

procedure w_stop ( txt IN VARCHAR2)
AS
    
begin
    SELECT GC.GENERICBOOLEAN1 INTO v_stop FROM CS_CLASSIFIER c 
    INNER JOIN CS_GENERICCLASSIFIER gc ON C.CLASSIFIERSEQ = GC.CLASSIFIERSEQ
        AND gc.REMOVEDATE = to_date('22000101','yyyymmdd') AND gc.islast = 1
    INNER JOIN CS_CATEGORY_CLASSIFIERS ccc ON ccc.CLASSIFIERSEQ = c.CLASSIFIERSEQ
        AND CCC.REMOVEDATE = to_date('22000101','yyyymmdd') AND CCC.ISLAST = 1
        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
        AND CCC.MODELSEQ = 0
    INNER JOIN CS_CATEGORYTREE ct ON CCC.CATEGORYTREESEQ = CT.CATEGORYTREESEQ AND 
        ct.REMOVEDATE = to_date('22000101','yyyymmdd') AND ct.ISLAST = 1
    WHERE CT.NAME = 'Permisos' AND
        c.classifierid = 'RECARGA' AND
        c.REMOVEDATE = to_date('22000101','yyyymmdd') AND c.ISLAST = 1;
end;

-- %%BRG 20250521: Procedimiento para actualizar fechas webi

PROCEDURE update_table ( periodo IN VARCHAR2, tabla_informe IN VARCHAR2)
AS
    
BEGIN

    MERGE INTO inyc_fechas_webi tabla
    USING (SELECT periodo as mes, tabla_informe as tabla FROM dual) condicion 
        ON (tabla.periodo = condicion.mes AND tabla.tabla = condicion.tabla)
    WHEN MATCHED THEN 
        UPDATE SET tabla.ultima_actualizacion = FROM_TZ(CAST(sysdate AS TIMESTAMP), to_char(cast(systimestamp as TIMESTAMP WITH TIME ZONE),'TZH:TZM')) AT TIME ZONE 'Europe/Madrid'
    WHEN NOT MATCHED THEN
        INSERT  (periodo, tabla, ultima_actualizacion, descripcion)
        VALUES  (
            condicion.mes,
            condicion.tabla,
            FROM_TZ(CAST(sysdate AS TIMESTAMP), to_char(cast(systimestamp as TIMESTAMP WITH TIME ZONE),'TZH:TZM')) AT TIME ZONE 'Europe/Madrid',
            'Ultima carga de la tabla '|| tabla_informe
        )
    ;

    COMMIT;
END;

-- %%BRG 20250521: Procedimiento principal

PROCEDURE MyProcedure(mes varchar2,informe varchar2, i_calendarName varchar2 := 'Main Monthly Calendar') IS
    v_periodRow cs_period%rowtype;
    
    filas number; --Para el DEBUG de los INSERT

BEGIN
    
    --Iniciamos el contador del Debug
    v_contador := 0;
    
    w_debug(' Procedure starting...', v_contador);
    
    
    --Revisamos si se debe detener el proceso
    w_stop('Revisar si detenemos el proceso');
    IF v_stop = 0 THEN
        w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
        
        RETURN;
    END IF;

    -- Sacamos el PERIODSEQ del periodo que le hemos pasado ('mes')
    v_periodRow := getPeriodRow(mes,i_calendarName);
    
    --ALM 20170420: Cargamos la variable que indica si un periodo esta finalizado.
    --              Esto nos asegura que no se recarguen las tablas de cierre de un periodo ya finalizado.
    --              Solo se recargaran las de Balances
    --ALM 20171113: Nueva variable para saber en que situacion se encuentra el periodo de recarga y asi ver que tablas debemos de cargar.
    --              Si v_periodo_posteado es igual 0, el periodo aun no se ha cerrado, se cargan las tablas de cierre.
    --              Si v_periodo_posteado es mayor que 0, se han realizado el numero de post que indica la varible, El periodo ya se ha cerrado, con dos posibilidades nuevas
    --                  - Si v_periodo_finalizado es igual a 0, no se han calculado balances. El perido no se ha finalizado. Se cargan las tablas de complementaria (LC)
    --                  - Si v_periodo_finalizado es mayor que 0, se han calculado balances. El perido se ha finalizado. Se cargan las tablas de balances (BAL)
    --ALM 20181030: Comprobamos una nueva clasificacion por si queremos modificar las tablas a cargar.
    SELECT GC.GENERICATTRIBUTE1 INTO v_tablas_a_cargar
    FROM CS_CLASSIFIER c 
    INNER JOIN CS_GENERICCLASSIFIER gc ON C.CLASSIFIERSEQ = GC.CLASSIFIERSEQ AND gc.REMOVEDATE = to_date('22000101','yyyymmdd')  AND gc.islast = 1
    INNER JOIN CS_CATEGORY_CLASSIFIERS ccc ON ccc.CLASSIFIERSEQ = c.CLASSIFIERSEQ AND CCC.REMOVEDATE = to_date('22000101','yyyymmdd') AND CCC.ISLAST = 1
    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
        AND CCC.MODELSEQ = 0
    INNER JOIN CS_CATEGORYTREE ct ON CCC.CATEGORYTREESEQ = CT.CATEGORYTREESEQ AND ct.REMOVEDATE = to_date('22000101','yyyymmdd') AND ct.ISLAST = 1
    WHERE CT.NAME = 'Permisos' AND c.classifierid = 'RECARGA' AND c.REMOVEDATE = to_date('22000101','yyyymmdd') AND c.ISLAST = 1;
      
    IF v_tablas_a_cargar = 'AUTO' THEN
    
        w_debug('Se recargan las tablas de informes por defecto dependiendo de si el periodo esta posteado o finalizado: '|| v_tablas_a_cargar, v_contador);
    
        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
        --SELECT COUNT(DISTINCT PAY.POSTPIPELINERUNSEQ) INTO v_periodo_posteado FROM TCMP.CS_PAYMENT PAY WHERE PAY.POSTPIPELINERUNSEQ IS NOT NULL AND PAY.PERIODSEQ = v_periodRow.PERIODSEQ;
        SELECT COUNT(DISTINCT PAY.POSTPIPELINERUNSEQ) INTO v_periodo_posteado
        FROM TCMP.CS_PAYMENT PAY
        INNER JOIN TCMP.CS_PLRUN PL ON PAY.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
        WHERE PAY.POSTPIPELINERUNSEQ IS NOT NULL AND PAY.PERIODSEQ = v_periodRow.PERIODSEQ;
        
        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
        --SELECT COUNT(1) INTO v_periodo_finalizado FROM TCMP.CS_BALANCE BAL WHERE BAL.PERIODSEQ = v_periodRow.PERIODSEQ;
        SELECT COUNT(1) INTO v_periodo_finalizado
        FROM TCMP.CS_BALANCE BAL
        INNER JOIN TCMP.CS_PLRUN PL ON BAL.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
        WHERE BAL.PERIODSEQ = v_periodRow.PERIODSEQ;
        
        --PARA CARGAR LAS TABLAS DE CIERRE BASTA CON PONER LA VARIABLE v_periodo_posteado = 0 
        --v_periodo_posteado := 0;
        --PARA CARGAR LAS TABLAS DE LIQUIDACION COMPLEMENTARIA HAY QUE PONER LA VARIABLE v_periodo_posteado = 1 Y LA VARIABLE v_periodo_finalizado = 0
        --v_periodo_posteado := 2;
        --v_periodo_finalizado := 0;
        --PARA CARGAR LAS TABLAS DE BALANCE HAY QUE PONER LA VARIABLE v_periodo_posteado = 1 Y LA VARIABLE v_periodo_finalizado = 1
        --v_periodo_posteado := 1;
        --v_periodo_finalizado := 1;
    
    ELSE
        
        w_debug('Se recargan las tablas de informes dependiendo de los clasificadores POST y FINALIZE: '|| v_tablas_a_cargar, v_contador);
    
        SELECT GC.GENERICBOOLEAN1 INTO v_periodo_posteado
        FROM CS_CLASSIFIER c 
        INNER JOIN CS_GENERICCLASSIFIER gc ON C.CLASSIFIERSEQ = GC.CLASSIFIERSEQ AND gc.REMOVEDATE = to_date('22000101','yyyymmdd') AND gc.islast = 1
        INNER JOIN CS_CATEGORY_CLASSIFIERS ccc ON  ccc.CLASSIFIERSEQ = c.CLASSIFIERSEQ AND CCC.REMOVEDATE = to_date('22000101','yyyymmdd') AND CCC.ISLAST = 1
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            AND CCC.MODELSEQ = 0
        INNER JOIN CS_CATEGORYTREE ct ON CCC.CATEGORYTREESEQ = CT.CATEGORYTREESEQ AND ct.REMOVEDATE = to_date('22000101','yyyymmdd') AND ct.ISLAST = 1
        WHERE CT.NAME = 'Permisos' AND c.classifierid = 'POST' AND  
            c.REMOVEDATE = to_date('22000101','yyyymmdd') AND c.ISLAST = 1;
        
        SELECT GC.GENERICBOOLEAN1 INTO v_periodo_finalizado
        FROM CS_CLASSIFIER c 
        INNER JOIN CS_GENERICCLASSIFIER gc ON C.CLASSIFIERSEQ = GC.CLASSIFIERSEQ AND gc.REMOVEDATE = to_date('22000101','yyyymmdd') AND gc.islast = 1
        INNER JOIN CS_CATEGORY_CLASSIFIERS ccc ON ccc.CLASSIFIERSEQ = c.CLASSIFIERSEQ AND CCC.REMOVEDATE = to_date('22000101','yyyymmdd') AND CCC.ISLAST = 1
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            AND CCC.MODELSEQ = 0
        INNER JOIN CS_CATEGORYTREE ct ON CCC.CATEGORYTREESEQ = CT.CATEGORYTREESEQ AND ct.REMOVEDATE = to_date('22000101','yyyymmdd') AND ct.ISLAST = 1
        WHERE CT.NAME ='Permisos' AND c.classifierid = 'FINALIZE' AND c.REMOVEDATE = to_date('22000101','yyyymmdd') AND c.ISLAST = 1;
    
    END IF;        
    
    w_debug('Carga variable v_periodo_posteado: '|| v_periodo_posteado, v_contador);
    w_debug('Carga variable v_periodo_finalizado: '|| v_periodo_finalizado, v_contador);
        
    IF v_periodo_finalizado = 1 AND v_periodo_posteado = 0 THEN
        w_debug('PERIODO FINALIZADO SIN PAGOS POSTEADOS. POSIBLE ERROR EN LOS DATOS. REVISAR!!!!!!!', v_contador);
        
        --RAISE_APPLICATION_ERROR(-20000, 'Finalizacion Forzada.');
        RETURN;
    END IF;
    
    
    --ALM 20210924; Proyecto Licencias Payee. Consultamos el parametro para saber si estamos en paralelo o ya en Produccion.
    --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
    --SELECT VALOR INTO v_Licencias FROM INYCEXT.INYC_PARAMETROS WHERE NOMBRE = 'LICENCIAS_STATUS';
    SELECT MAX(VALUE) INTO v_FV_EstadoTrx 
    FROM TCMP.CS_FIXEDVALUE
    WHERE NAME = 'FV-CONF-Estado-Transaccion'
        AND REMOVEDATE = v_eot
        AND MODELSEQ = 0
        AND EFFECTIVESTARTDATE <= v_periodRow.STARTDATE
        AND EFFECTIVEENDDATE > v_periodRow.STARTDATE;
    
    
    --ALM 20160511: Variable que indica si se recargan las tablas temporales, DEBE DE ESTAR A 1 
    v_recarga_temp := 1;
    IF v_recarga_temp <> 1 THEN
        w_debug('NO SE RECARGAN LAS TABLAS TEMPORALES, MODIFICAR v_recarga_temp a 1', v_contador);
    END IF;
    
    
    -- Generamos una variable con el periodo (necesario para PKG.CUSTOM_REPORT aqui ya tenemos mes)
    SELECT NAME INTO v_periodo FROM CS_PERIOD WHERE PERIODSEQ = v_periodRow.PERIODSEQ AND REMOVEDATE = v_eot;
    
    w_debug('Carga variable v_periodo: '|| v_periodo, v_contador);
    
    
--    --ALM 20160210: Generamos dos variable para controlor si es necesario recargar las tablas temporales
--    SELECT VALOR INTO v_ultima_carga FROM INYCEXT.INYC_PARAMETROS WHERE NOMBRE = 'CARGA_TABLAS_TEMP';
    --ALM 20160510: Nos quedamos con la ultima ejecucion exitosa para actualizar la tabla de parametros
    SELECT MAX(PIPELINERUNSEQ) INTO v_carga FROM TCMP.CS_PLRUN WHERE COMMAND = 'PipelineRun' AND STATUS = 'Successful'
        AND SUBSTR(DESCRIPTION,INSTR(DESCRIPTION,'stage',1,1)+6,INSTR(DESCRIPTION,'useDeferredReset',1,1)-INSTR(DESCRIPTION,'stage',1,1)-7)
            in ('CompensateAndPay','Compensate','Summarize','Reward')
        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
        AND MODELSEQ = 0; 
            
    
    --ALM 20180112: Lanzamos las estad�sticas de las tablas de configuraci�n para optimizar el sistema.
    w_debug('Inicio Actualizacion de Indices de las Tablas de Configuracion.', v_contador);

    --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_CONF_INFORMES COMPUTE STATISTICS FOR ALL INDEXES';
    DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_CONF_INFORMES');
    --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_CONF_INF_REGLAS COMPUTE STATISTICS FOR ALL INDEXES';
    DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_CONF_INF_REGLAS');
    --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_CONF_INF_AGENTES COMPUTE STATISTICS FOR ALL INDEXES';
    DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_CONF_INF_AGENTES');
    
    w_debug('Fin Actualizacion de Indices de las Tablas de Configuracion.', v_contador);
    
    
    -------------------------------------------------------------------------------------------------------------------------------------
    -------------------------------------------------------------------------------------------------------------------------------------
    -- %%DTB 20250521 Recarga tablas temporales
    --ESTAS TABLAS SE RECARGAN AUNQUE NO SE HAYA EJECUTADO EL PIPELINE
    --ALM 20160222: Truncado, carga y actualizacion de Indices de la tabla temporal de USUARIOS    
    w_debug('Inicio Truncado de la tabla USUARIOS.', v_contador);

    EXECUTE IMMEDIATE 'TRUNCATE TABLE INYCEXT.INYC_USUARIOS_TEMP';
        
    w_debug('Fin Truncado de la tabla USUARIOS.', v_contador);
    
    
    w_debug('Inicio Carga de la tabla USUARIOS.', v_contador);

    INSERT INTO INYCEXT.INYC_USUARIOS_TEMP (
        SELECT DISTINCT PAD.BOUSERID AS USUARIO,
            CASE WHEN PAP.USERID IS NULL THEN PAD.BOUSERID ELSE CAST('PortalAdmin_INYC' AS NVARCHAR2(260)) END AS ANCESTOR
        FROM TCMP.CSA_PADIMENSION PAD
        INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD.PERIODSEQ = PD.PERIODSEQ
            AND PD.TENANTID = 'INYC'
        LEFT OUTER JOIN TCMP.CSA_PAPLUGIN PAP ON PAD.USERID = PAP.USERID
            AND PAP.STARTDATE <= PD.ENDDATE AND PAP.ENDDATE >= PD.STARTDATE
            AND PAP.TENANTID = 'INYC'
        WHERE PAD.PERIODSEQ = v_periodRow.PERIODSEQ
    );
    filas := sql%rowcount;
    COMMIT;

    w_debug('Fin Carga de la tabla USUARIOS: '|| to_char(filas) || ' filas.', v_contador);
            
            
    w_debug('Inicio Actualizacion de Indices de la tabla INYC_USUARIOS_TEMP.', v_contador);

    --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_USUARIOS_TEMP COMPUTE STATISTICS FOR ALL INDEXES';
    DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_USUARIOS_TEMP');
    
    w_debug('Fin Actualizacion de Indices de la tabla INYC_USUARIOS_TEMP.', v_contador);
    
    
    --Revisamos si se debe detener el proceso
    w_stop('Revisar si detenemos el proceso');
    IF v_stop = 0 THEN
        w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
        
        RETURN;
    END IF;
    

    -------------------------------------------------------------------------------------------------------------------------------------
    --%%BRG 20250522: Tabla temporal INYC_TABLA_IRPF
    --ALM 20151028: Cargamos tabla auxiliar IRPF
    w_debug('Inicio Truncado de la tabla de IRPF.', v_contador);
    
    EXECUTE IMMEDIATE 'TRUNCATE TABLE INYCEXT.INYC_TABLA_IRPF';
    
    w_debug('Fin Truncado de la tabla de IRPF.', v_contador);
    
    
    w_debug('Inicio Carga de la tabla de IRPF.', v_contador);
    
    INSERT INTO INYCEXT.INYC_TABLA_IRPF (
        SELECT C.CLASSIFIERID,SUBSTR(C.NAME,1,1),GC.GENERICNUMBER1
        FROM CS_GENERICCLASSIFIERTYPE GCT
        INNER JOIN CS_CLASSIFIER C ON GCT.GENERICCLASSIFIERTYPESEQ = C.SELECTORID
            AND C.TENANTID = 'INYC' 
            AND C.REMOVEDATE = v_eot
        INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON C.EFFECTIVESTARTDATE < PD.ENDDATE AND C.EFFECTIVEENDDATE >= PD.ENDDATE
            AND PD.TENANTID = 'INYC'
        INNER JOIN CS_GENERICCLASSIFIER GC ON C.CLASSIFIERSEQ = GC.CLASSIFIERSEQ
            AND GC.EFFECTIVESTARTDATE < PD.ENDDATE AND GC.EFFECTIVEENDDATE >= PD.ENDDATE
            AND GC.TENANTID = 'INYC'
            AND GC.REMOVEDATE = v_eot
        INNER JOIN CS_CATEGORY_CLASSIFIERS CC ON C.CLASSIFIERSEQ = CC.CLASSIFIERSEQ 
            AND CC.EFFECTIVESTARTDATE < PD.ENDDATE AND CC.EFFECTIVEENDDATE >= PD.ENDDATE
            AND CC.TENANTID = 'INYC'
            AND CC.REMOVEDATE = v_eot
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            AND MODELSEQ = 0
        INNER JOIN CS_CATEGORYTREE CT ON CC.CATEGORYTREESEQ = CT.CATEGORYTREESEQ
            AND CT.EFFECTIVESTARTDATE < PD.ENDDATE AND CT.EFFECTIVEENDDATE >= PD.ENDDATE
            AND CT.TENANTID = 'INYC'
            AND CT.REMOVEDATE = v_eot
            AND CT.NAME = 'Tipo IRPF'    
        WHERE GCT.TENANTID = 'INYC'
            AND GCT.NAME = 'Tipo IRPF'
            AND PD.PERIODSEQ = v_periodRow.PERIODSEQ
    );
    filas := sql%rowcount;
    COMMIT;

    w_debug('Fin Carga de la tabla IRPF: '|| to_char(filas) || ' filas.', v_contador);
            
            
    w_debug('Inicio Actualizacion de Indices de la tabla INYC_TABLA_IRPF.', v_contador);

    --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_TABLA_IRPF COMPUTE STATISTICS FOR ALL INDEXES';
    DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_TABLA_IRPF');

    w_debug('Fin Actualizacion de Indices de la tabla INYC_TABLA_IRPF.', v_contador);
    
    
    --Revisamos si se debe detener el proceso
    w_stop('Revisar si detenemos el proceso');
    IF v_stop = 0 THEN
        w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
        
        RETURN;
    END IF;
    
    
    -------------------------------------------------------------------------------------------------------------------------------------
    --ALM 20160122: Cargamos tabla auxiliar PERCEPCIONES
    w_debug('Inicio Truncado de la tabla de PERCEPCIONES.', v_contador);
    
    EXECUTE IMMEDIATE 'TRUNCATE TABLE INYCEXT.INYC_TABLA_PERCEPCIONES';
    
    w_debug('Fin Truncado de la tabla de PERCEPCIONES.', v_contador);
    
    
    w_debug('Inicio Carga de la tabla de PERCEPCIONES.', v_contador);
    
    INSERT INTO INYCEXT.INYC_TABLA_PERCEPCIONES (
        SELECT DISTINCT GC.GENERICATTRIBUTE4 AS DEPOSITO,GC.GENERICATTRIBUTE1 AS DESCRIPCION, --LLS 20220124: incluido el distinct
            GC.GENERICATTRIBUTE2 AS EARNINGCODE,GC.GENERICATTRIBUTE3 AS EARNINGGROUP
        FROM CS_GENERICCLASSIFIERTYPE GCT
        INNER JOIN CS_CLASSIFIER C ON GCT.GENERICCLASSIFIERTYPESEQ = C.SELECTORID
            AND C.TENANTID = 'INYC' 
            AND C.REMOVEDATE = v_eot
        INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON C.EFFECTIVESTARTDATE < PD.ENDDATE AND C.EFFECTIVEENDDATE >= PD.ENDDATE
            AND PD.TENANTID = 'INYC'
        INNER JOIN CS_GENERICCLASSIFIER GC ON C.CLASSIFIERSEQ = GC.CLASSIFIERSEQ
            AND GC.EFFECTIVESTARTDATE < PD.ENDDATE AND GC.EFFECTIVEENDDATE >= PD.ENDDATE
            AND GC.TENANTID = 'INYC'
            AND GC.REMOVEDATE = v_eot
        INNER JOIN CS_CATEGORY_CLASSIFIERS CC ON C.CLASSIFIERSEQ = CC.CLASSIFIERSEQ 
            AND CC.EFFECTIVESTARTDATE < PD.ENDDATE AND CC.EFFECTIVEENDDATE >= PD.ENDDATE
            AND CC.TENANTID = 'INYC'
            AND CC.REMOVEDATE = v_eot
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            AND MODELSEQ = 0
        INNER JOIN CS_CATEGORYTREE CT ON CC.CATEGORYTREESEQ = CT.CATEGORYTREESEQ
            AND CT.EFFECTIVESTARTDATE < PD.ENDDATE AND CT.EFFECTIVEENDDATE >= PD.ENDDATE
            AND CT.TENANTID = 'INYC'
            AND CT.REMOVEDATE = v_eot
            AND CT.NAME = 'Percepciones'    
        WHERE GCT.TENANTID = 'INYC'
            AND GCT.NAME LIKE 'Percepci%n'
            AND PD.PERIODSEQ = v_periodRow.PERIODSEQ
    );
    filas := sql%rowcount;
    COMMIT;

    w_debug('Fin Carga de la tabla PERCEPCIONES: '|| to_char(filas) || ' filas.', v_contador);
            
            
    w_debug('Inicio Actualizacion de Indices de la tabla INYC_TABLA_PERCEPCIONES.', v_contador);

    --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_TABLA_PERCEPCIONES COMPUTE STATISTICS FOR ALL INDEXES';
    DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_TABLA_PERCEPCIONES');

    w_debug('Fin Actualizacion de Indices de la tabla INYC_TABLA_PERCEPCIONES.', v_contador);
    
    
    --Revisamos si se debe detener el proceso
    w_stop('Revisar si detenemos el proceso');
    IF v_stop = 0 THEN
        w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
        
        RETURN;
    END IF;


    -------------------------------------------------------------------------------------------------------------------------------------
    --ALM 20220330: Solo hacemos esta modificacion si se ejecuta un periodo antes de la LC y los balances.
    --LLS 20220127: Borrado de INYCEXT.INYC_CARTERA_LP_DET todo aquello que no sea derechos economicos.
    IF v_periodo_posteado = 0 THEN
    
        w_debug('Inicio modificacion INYCEXT.INYC_CARTERA_LP_DET si ya no es derechos economicos.', v_contador);
        
        --MCR 20220329: En el caso de que a un agente DDEE le cambien de tipologia, se borraba de la tabla. Cambiamos el estado para que no se tenga en cuenta pero no se borren los datos. 
        --ATV 20240710: Anyadimos el tipo 6 (que ahora es DDEE) para que no ponga el estado X.
        --DELETE INYCEXT.INYC_CARTERA_LP_DET
        UPDATE INYCEXT.INYC_CARTERA_LP_DET
        SET ESTADO = 'X'
        WHERE COMPENSATIONDATE = (    SELECT STARTDATE
                            FROM CSA_PERIODDIMENSION 
                            WHERE TENANTID = 'INYC'
                            AND PERIODSEQ = v_periodRow.PERIODSEQ )
            AND POSITIONNAME NOT IN (    SELECT P.NAME
                                        FROM TCMP.CSA_PERIODDIMENSION PD
                                        INNER JOIN TCMP.CS_POSITION P ON P.EFFECTIVESTARTDATE <= PD.STARTDATE
                                            AND P.EFFECTIVEENDDATE > PD.STARTDATE
                                            AND P.REMOVEDATE = v_eot
                                            AND P.TENANTID = 'INYC'
                                            AND P.GENERICNUMBER2 IN(6,12) 
                                        WHERE PD.TENANTID = 'INYC'
                                            AND PD.PERIODSEQ = v_periodRow.PERIODSEQ
                                    )
            AND ESTADO = 'C'
            --ALM 20220331: Control manual para no tener en cuenta agentes concretos:
            AND (COMPENSATIONDATE <> TO_DATE('20220301','YYYYMMDD') OR COD_AGENTE <> '0316003359') --Pedido por David para 2022-03
        ;
        
        filas := sql%rowcount;
        COMMIT;

        w_debug('Fin modificacion INYCEXT.INYC_CARTERA_LP_DET si ya no es derechos economicos: '|| to_char(filas) || ' filas.', v_contador);
        
    END IF;
    
    
    --Revisamos si se debe detener el proceso
    w_stop('Revisar si detenemos el proceso');
    IF v_stop = 0 THEN
        w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
        
        RETURN;
    END IF;
    
    
    -------------------------------------------------------------------------------------------------------------------------------------
    -------------------------------------------------------------------------------------------------------------------------------------
    --ALM 20160511: COMPROBAMOS LA VARIABLE DE RECARGA DE TABLAS TEMPORALES
    IF v_recarga_temp = 1 THEN 
    --ALM 20160217: SIEMPRE RECARGAREMOS LAS TABLAS PARA CREAR_TABLAS
    --    --ESTAS TABLAS SOLO SE RECARGARAN SI SE HA EJECUTADO EL PIPELINE
    --    IF v_ultima_carga <> v_carga THEN
    --        --SI SE HA LANZADO EL PIPELINE DESDE LA ULTIMA EJECUCION DEL PAQUETE SE RECARGAN LAS TABLAS
    --        --Y SE ACTUALIZA LA TABLA DE PARAMETROS
        --ALM 20160510: Actualizamos la tabla de parametros con el ultimo valor cargado en las tablas temporales
        UPDATE INYCEXT.INYC_PARAMETROS SET VALOR = v_carga WHERE NOMBRE = 'CARGA_TABLAS_TEMP';
    --        
    --        COMMIT;

        --ALM 20160211: Truncado, carga y actualizacion de Indices de la tabla temporal de TXN 
        w_debug('Inicio Truncado de la tabla INYC_TXN_MES_TEMP.', v_contador);

        EXECUTE IMMEDIATE 'TRUNCATE TABLE INYCEXT.INYC_TXN_MES_TEMP';
        
        w_debug('Fin Truncado de la tabla INYC_TXN_MES_TEMP.', v_contador);
            
        w_debug('Inicio Carga de la tabla INYC_TXN_MES_TEMP.', v_contador);

        INSERT INTO INYCEXT.INYC_TXN_MES_TEMP (
            SELECT ST.TENANTID, ST.SALESTRANSACTIONSEQ, ST.SALESORDERSEQ, ST.LINENUMBER, ST.SUBLINENUMBER, ST.EVENTTYPESEQ, ST.PIPELINERUNSEQ, ST.ORIGINTYPEID,
                ST.COMPENSATIONDATE, ST.BILLTOADDRESSSEQ, ST.SHIPTOADDRESSSEQ, ST.OTHERTOADDRESSSEQ, ST.ISRUNNABLE, ST.BUSINESSUNITMAP, ST.ACCOUNTINGDATE,
                ST.PRODUCTID, ST.PRODUCTNAME, ST.PRODUCTDESCRIPTION, ST.NUMBEROFUNITS, ST.UNITVALUE, ST.UNITTYPEFORUNITVALUE, ST.PREADJUSTEDVALUE,
                ST.UNITTYPEFORPREADJUSTEDVALUE, ST.VALUE, ST.UNITTYPEFORVALUE, ST.NATIVECURRENCY, ST.NATIVECURRENCYAMOUNT, ST.DISCOUNTPERCENT, ST.DISCOUNTTYPE,
                ST.PAYMENTTERMS, ST.PONUMBER, ST.CHANNEL, ST.ALTERNATEORDERNUMBER, ST.DATASOURCE, ST.REASONSEQ, ST.COMMENTS, ST.GENERICATTRIBUTE1,
                ST.GENERICATTRIBUTE2, ST.GENERICATTRIBUTE3, ST.GENERICATTRIBUTE4, ST.GENERICATTRIBUTE5, ST.GENERICATTRIBUTE6, ST.GENERICATTRIBUTE7,
                ST.GENERICATTRIBUTE8, ST.GENERICATTRIBUTE9, ST.GENERICATTRIBUTE10, ST.GENERICATTRIBUTE11, ST.GENERICATTRIBUTE12, ST.GENERICATTRIBUTE13,
                ST.GENERICATTRIBUTE14, ST.GENERICATTRIBUTE15, ST.GENERICATTRIBUTE16, ST.GENERICATTRIBUTE17, ST.GENERICATTRIBUTE18, ST.GENERICATTRIBUTE19,
                ST.GENERICATTRIBUTE20, ST.GENERICATTRIBUTE21, ST.GENERICATTRIBUTE22, ST.GENERICATTRIBUTE23, ST.GENERICATTRIBUTE24, ST.GENERICATTRIBUTE25,
                ST.GENERICATTRIBUTE26, ST.GENERICATTRIBUTE27, ST.GENERICATTRIBUTE28, ST.GENERICATTRIBUTE29, ST.GENERICATTRIBUTE30, ST.GENERICATTRIBUTE31,
                ST.GENERICATTRIBUTE32, ST.GENERICNUMBER1, ST.UNITTYPEFORGENERICNUMBER1, ST.GENERICNUMBER2, ST.UNITTYPEFORGENERICNUMBER2, ST.GENERICNUMBER3,
                ST.UNITTYPEFORGENERICNUMBER3, ST.GENERICNUMBER4, ST.UNITTYPEFORGENERICNUMBER4, ST.GENERICNUMBER5, ST.UNITTYPEFORGENERICNUMBER5, ST.GENERICNUMBER6,
                ST.UNITTYPEFORGENERICNUMBER6, ST.GENERICDATE1, ST.GENERICDATE2, ST.GENERICDATE3, ST.GENERICDATE4, ST.GENERICDATE5, ST.GENERICDATE6,
                ST.GENERICBOOLEAN1, ST.GENERICBOOLEAN2, ST.GENERICBOOLEAN3, ST.GENERICBOOLEAN4, ST.GENERICBOOLEAN5, ST.GENERICBOOLEAN6, ST.PROCESSINGUNITSEQ,
                ST.MODIFICATIONDATE, ST.UNITTYPEFORLINENUMBER, ST.UNITTYPEFORSUBLINENUMBER, ST.UNITTYPEFORNUMBEROFUNITS, ST.UNITTYPEFORDISCOUNTPERCENT,
                ST.UNITTYPEFORNATIVECURRENCYAMT, ST.MODELSEQ,
                CASE WHEN ET.EVENTTYPEID IN ('66','81') AND ST.GENERICATTRIBUTE3 IN ('3','4','5','6','7','8') THEN 'Recuperacion' 
                    --WHEN ET.EVENTTYPEID LIKE 'AS%' THEN 'Tramitacion'
                    --ALM 20180921: Cambiamos la tipologia de las transacciones generadas por Javier para la Venta Simultanea 1+1
                    --              Son transacciones tipo 71 y llevan en el campo Tipo de Campania (GA21) el codigo 'VS11' 
                    WHEN ET.EVENTTYPEID = '71' AND ST.GENERICATTRIBUTE21 = 'VS11' THEN 'Bonif Venta Simultanea'
                    --ATV 20241231 Anyadimos modificacion para polizas sin firmar
                    WHEN ST.GENERICATTRIBUTE6 IN ('S','N') THEN ET.DESCRIPTION || ' - No firmadas Cond. Part'
                    ELSE ET.DESCRIPTION END AS EVENTO,
                PROD.GENERICATTRIBUTE5 AS PRODUCTO, PROD.GENERICBOOLEAN1 AS GARANTIA,
                TA.GENERICDATE1 AS FEC_VTO_REC, TA.GENERICNUMBER2 AS KM, TA.GENERICBOOLEAN2 AS RECIBO
            FROM TCMP.CS_SALESTRANSACTION ST
            INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                AND TA.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND TA.PROCESSINGUNITSEQ = 38280596832649217
            INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON ST.COMPENSATIONDATE >= PD.STARTDATE AND ST.COMPENSATIONDATE < PD.ENDDATE
                AND PD.TENANTID = 'INYC'
            LEFT OUTER JOIN TCMP.CS_EVENTTYPE ET ON ST.EVENTTYPESEQ = ET.DATATYPESEQ
                AND ET.REMOVEDATE = v_eot 
                AND ET.TENANTID = 'INYC'
            LEFT OUTER JOIN TCMP.CS_CLASSIFIER CL ON ST.PRODUCTID = CL.CLASSIFIERID 
                AND CL.REMOVEDATE = v_eot  
                AND CL.EFFECTIVESTARTDATE <= ST.COMPENSATIONDATE AND CL.EFFECTIVEENDDATE > ST.COMPENSATIONDATE
                AND CL.TENANTID = 'INYC'
            LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                AND PROD.REMOVEDATE = v_eot  
                AND PROD.EFFECTIVESTARTDATE <= ST.COMPENSATIONDATE AND PROD.EFFECTIVEENDDATE > ST.COMPENSATIONDATE
                AND PROD.TENANTID = 'INYC'
            WHERE ST.TENANTID = 'INYC' AND PD.PERIODSEQ = v_periodRow.PERIODSEQ
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                AND ST.MODELSEQ = 0
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND ST.PROCESSINGUNITSEQ = 38280596832649217
        );
        filas := sql%rowcount;
        COMMIT;

        w_debug('Fin Carga de la tabla INYC_TXN_MES_TEMP: '|| to_char(filas) || ' filas.', v_contador);
            
            
        w_debug('Inicio Actualizacion de Indices de la tabla INYC_TXN_MES_TEMP.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_TXN_MES_TEMP COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_TXN_MES_TEMP');

        w_debug('Fin Actualizacion de Indices de la tabla INYC_TXN_MES_TEMP.', v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;


        -------------------------------------------------------------------------------------------------------------------------------------
        --ALM 20160211: Truncado, carga y actualizacion de Indices de la tabla temporal de CREDITOS    
        w_debug('Inicio Truncado de la tabla INYC_CREDITOS_MES_TEMP.', v_contador);

        EXECUTE IMMEDIATE 'TRUNCATE TABLE INYCEXT.INYC_CREDITOS_MES_TEMP';
            
        w_debug('Fin Truncado de la tabla INYC_CREDITOS_MES_TEMP.', v_contador);

            
        w_debug('Inicio Carga de la tabla INYC_CREDITOS_MES_TEMP.', v_contador);

        INSERT INTO INYCEXT.INYC_CREDITOS_MES_TEMP (
            SELECT C.TENANTID, C.CREDITSEQ, C.PAYEESEQ, C.POSITIONSEQ, C.SALESORDERSEQ, C.SALESTRANSACTIONSEQ, C.PERIODSEQ, C.CREDITTYPESEQ, C.NAME, C.PIPELINERUNSEQ,
                C.ORIGINTYPEID, C.COMPENSATIONDATE, C.PIPELINERUNDATE, C.BUSINESSUNITMAP, C.PREADJUSTEDVALUE, C.UNITTYPEFORPREADJUSTEDVALUE, C.VALUE,
                C.UNITTYPEFORVALUE, C.RELEASEDATE, C.RULESEQ, C.ISHELD, C.ISROLLABLE, C.ROLLDATE, C.REASONSEQ, C.COMMENTS, C.GENERICATTRIBUTE1, C.GENERICATTRIBUTE2,
                C.GENERICATTRIBUTE3, C.GENERICATTRIBUTE4, C.GENERICATTRIBUTE5, C.GENERICATTRIBUTE6, C.GENERICATTRIBUTE7, C.GENERICATTRIBUTE8, C.GENERICATTRIBUTE9,
                C.GENERICATTRIBUTE10, C.GENERICATTRIBUTE11, C.GENERICATTRIBUTE12, C.GENERICATTRIBUTE13, C.GENERICATTRIBUTE14, C.GENERICATTRIBUTE15,
                C.GENERICATTRIBUTE16, C.GENERICNUMBER1, C.UNITTYPEFORGENERICNUMBER1, C.GENERICNUMBER2, C.UNITTYPEFORGENERICNUMBER2, C.GENERICNUMBER3,
                C.UNITTYPEFORGENERICNUMBER3, C.GENERICNUMBER4, C.UNITTYPEFORGENERICNUMBER4, C.GENERICNUMBER5, C.UNITTYPEFORGENERICNUMBER5, C.GENERICNUMBER6,
