        --ALM 20160211: Truncado, carga y actualizacion de Indices de la tabla temporal de AGENTES PRINCIPALES    
        w_debug('Inicio Truncado de la tabla INYC_AGENTES_PRIN_MES_TEMP.', v_contador);

        EXECUTE IMMEDIATE 'TRUNCATE TABLE INYCEXT.INYC_AGENTES_PRIN_MES_TEMP';
            
        w_debug('Fin Truncado de la tabla INYC_AGENTES_PRIN_MES_TEMP.', v_contador);

            
        w_debug('Inicio Carga de la tabla INYC_AGENTES_PRIN_MES_TEMP.', v_contador);

        INSERT INTO INYCEXT.INYC_AGENTES_PRIN_MES_TEMP (
            SELECT DISTINCT 
                --ALM 20161201: Anadimos los campos de la tabla de PERIODOS que se utilizan en los diferentes informes
                PD.YEAR,PD.QUARTER,
                PD.NAME AS PERIODO,
                PD.STARTDATE,
                PD.PERIODSEQ,
                CASE WHEN P.RULEELEMENTOWNERSEQ IS NULL THEN PAD_INS.POSITIONSEQ ELSE P.RULEELEMENTOWNERSEQ END AS POSITIONSEQ_PRIN,
                PAD_INS.POSITIONSEQ,
                PAD_INS.PARTICIPANTSEQ,
                PAD_INS.BOUSERID,
                --ALM 20160404: MODIFICACIoN PARA EL CAMBIO AL CoDIGO uNICO
                --PAD_INS.POSITIONGENERICATTRIBUTE3 AS POS_CALLIDUS,
                --PAD_INS.POSITIONNAME AS POSITIONNAME,
                PAD_INS.POSITIONNAME AS POS_CALLIDUS,
                PAD_INS.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME,
                PAD_INS.FIRSTNAME,
                PAD_INS.LASTNAME,
                PAD_INS.SUFFIX,
                PAD_INS.TAXID,
                --ALM 20170512: Anadimos todos los campos existentes del Participant y la Position
                PAD_INS.HIREDATE,
                PAD_INS.TERMINATIONDATE,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE1 AS NIF,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE2 AS TIPO_DOCUMENTO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE3 AS TIPO_PERSONA,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE4 AS COD_DGS,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE5 AS CIA_EMPLEADO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE6 AS TIPO_MEDIADOR_OCASO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE7 AS MUNICIPIO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE8 AS TIPO_VIA,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE9 AS DOMICILIO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE10 AS NUMERO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE11 AS RESTO_DOMICILIO,   
                PAD_INS.PARTICIPANTGENERICATTRIBUTE12 AS SEXO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE13 AS ESTADO_CIVIL,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE14 AS TELEFONO_FIJO,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE15 AS TELEFONO_MOVIL,
                PAD_INS.PARTICIPANTGENERICATTRIBUTE16 AS IBAN,
                PAD_INS.PARTICIPANTGENERICNUMBER1 AS CP,
                PAD_INS.PARTICIPANTGENERICNUMBER2 AS COD_PROVINCIA,
                PAD_INS.PARTICIPANTGENERICNUMBER3 AS COD_MUNICIPIO,
                PAD_INS.PARTICIPANTGENERICNUMBER4 AS ID_EMPLEADO,
                PAD_INS.PARTICIPANTGENERICNUMBER5 AS IRPF_EMPLEADO,
                PAD_INS.PARTICIPANTGENERICNUMBER6 AS FAX,
                PAD_INS.PARTICIPANTGENERICDATE1 AS FEC_NACIMIENTO,
                PAD_INS.PARTICIPANTGENERICDATE2 AS FEC_REG_DGS,
                PAD_INS.PARTICIPANTGENERICDATE3 AS FEC_ENVIO_DGS,
                PAD_INS.PARTICIPANTGENERICDATE4 AS FEC_FIN_CIASE,
                PAD_INS.PARTICIPANTGENERICDATE5 AS FEC_EFECTO_SUPERRAPEL,
                PAD_INS.PARTICIPANTGENERICDATE6 AS FEC_REGULA_SUPERRAPEL,
                PAD_INS.PARTICIPANTGENERICBOOLEAN1 AS AUTOLIQUIDA,
                PAD_INS.PARTICIPANTGENERICBOOLEAN2 AS CORREDOR,
                PAD_INS.PARTICIPANTGENERICBOOLEAN3 AS PROPIEDAD,
                PAD_INS.PARTICIPANTGENERICBOOLEAN4 AS SUPERRAPEL,
                PAD_INS.PARTICIPANTGENERICBOOLEAN5 AS COMIS_ANUAL_RRPP,
                PAD_INS.PARTICIPANTGENERICBOOLEAN6 AS PAGO_POR_IBAN,
                --ALM 20160315: MODIFICACIoN PARA EL CAMBIO AL CoDIGO uNICO
                --CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONNAME ELSE P.NAME END AS POS_PRIN,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE1 ELSE P.GENERICATTRIBUTE1 END AS TIPO_PRIN_AGENTE,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE2 ELSE P.GENERICATTRIBUTE2 END AS TIPO_AGENTE,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE3 ELSE P.GENERICATTRIBUTE3 END AS POS_PRIN,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE5 ELSE P.GENERICATTRIBUTE5 END AS CUADRO_INSP_OCASO,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE6 ELSE P.GENERICATTRIBUTE6 END AS CUADRO_RRGG_OCASO,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE7 ELSE P.GENERICATTRIBUTE7 END AS CUADRO_RRTT_OCASO,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE8 ELSE P.GENERICATTRIBUTE8 END AS CIA_POS,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE9 ELSE P.GENERICATTRIBUTE9 END AS PROMOCION,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE10 ELSE P.GENERICATTRIBUTE10 END AS CUADRO_INSP_ETERNA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE11 ELSE P.GENERICATTRIBUTE11 END AS CUADRO_RRGG_ETERNA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE12 ELSE P.GENERICATTRIBUTE12 END AS CUADRO_RRTT_ETERNA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE13 ELSE P.GENERICATTRIBUTE13 END AS ANIO_CAPTACION,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE14 ELSE P.GENERICATTRIBUTE14 END AS INSP_CAPTACION,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE15 ELSE P.GENERICATTRIBUTE15 END AS NUM_MESES_PREPLAN,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICATTRIBUTE16 ELSE P.GENERICATTRIBUTE16 END AS ESCALADO,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICNUMBER1 ELSE P.GENERICNUMBER1 END AS ID_TIPO_PRIN_AGENTE,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICNUMBER2 ELSE P.GENERICNUMBER2 END AS ID_TIPO_AGENTE,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICNUMBER3 ELSE P.GENERICNUMBER3 END AS ID_CLASE_OFICINA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICNUMBER4 ELSE P.GENERICNUMBER4 END AS ID_TIPO_OFICINA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICNUMBER5 ELSE P.GENERICNUMBER5 END AS PORC_COMIS_CARTERA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICNUMBER6 ELSE P.GENERICNUMBER6 END AS IMP_COMIS_CARTERA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICDATE1 ELSE P.GENERICDATE1 END AS FEC_ALTA_POS,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICDATE2 ELSE P.GENERICDATE2 END AS FEC_BAJA_POS,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICDATE3 ELSE P.GENERICDATE3 END AS FEC_INI_CONS_PC,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICDATE4 ELSE P.GENERICDATE4 END AS FEC_FIN_CONS_PC,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICDATE5 ELSE P.GENERICDATE5 END AS FEC_INI_ASIS,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICDATE6 ELSE P.GENERICDATE6 END AS FEC_LIM_COMIS,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICBOOLEAN1 ELSE P.GENERICBOOLEAN1 END AS REDUCCION,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICBOOLEAN2 ELSE P.GENERICBOOLEAN2 END AS PRODUCTOR_OCASO,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICBOOLEAN3 ELSE P.GENERICBOOLEAN3 END AS CONSOLIDA,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICBOOLEAN4 ELSE P.GENERICBOOLEAN4 END AS INI_AGENTE_ASIS,
                CASE WHEN P.NAME IS NULL THEN PAD_INS.POSITIONGENERICBOOLEAN5 ELSE P.GENERICBOOLEAN5 END AS PRODUCTOR_ETERNA,
                --ALM 20180613: Anadimos campos para poder unir por Manager y incluir sus campos en la tabla INYC_JERARQUIA
                CASE WHEN P.NAME IS NULL THEN PAD_INS.MANAGERSEQ ELSE P.MANAGERSEQ END AS MANAGERSEQ_PRIN,
                PAD_INS.MANAGERSEQ AS MANAGERSEQ
            FROM INYCEXT.INYC_AGENTES_MES_TEMP PAD_INS
            INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD_INS.PERIODSEQ = PD.PERIODSEQ
                AND PD.TENANTID = 'INYC'
            --ALM 20190109: Modificamos la union con el tipo de jerarquia porque al subir la nueva de Captacion se estan produciendo errores.
            --LEFT OUTER JOIN TCMP.CS_POSITIONRELATION PR ON PAD_INS.POSITIONSEQ = PR.CHILDPOSITIONSEQ 
            --    AND PR.REMOVEDATE = v_eot  
            --    AND PR.EFFECTIVESTARTDATE < PD.ENDDATE AND PR.EFFECTIVEENDDATE >= PD.ENDDATE
            --    AND PR.TENANTID = 'INYC'
            --LEFT OUTER JOIN TCMP.CS_POSITIONRELATIONTYPE PRT ON PR.POSITIONRELATIONTYPESEQ=PRT.DATATYPESEQ 
            --    AND PRT.REMOVEDATE = v_eot 
            --    AND PRT.NAME='Contract Rollup'
            --    AND PRT.TENANTID = 'INYC'
            LEFT OUTER JOIN (SELECT PR.PARENTPOSITIONSEQ,PR.CHILDPOSITIONSEQ,PR.EFFECTIVESTARTDATE,PR.EFFECTIVEENDDATE 
                FROM TCMP.CS_POSITIONRELATION PR
                INNER JOIN TCMP.CS_POSITIONRELATIONTYPE PRT ON PR.POSITIONRELATIONTYPESEQ=PRT.DATATYPESEQ 
                    AND PRT.REMOVEDATE = to_date('22000101','yyyymmdd') 
                    AND PRT.NAME = 'Contract Rollup'
                    AND PRT.TENANTID = 'INYC'
                WHERE PR.REMOVEDATE = to_date('22000101','yyyymmdd')
                    AND PR.TENANTID = 'INYC'
            ) PR ON PAD_INS.POSITIONSEQ = PR.CHILDPOSITIONSEQ 
                AND PR.EFFECTIVESTARTDATE < PD.ENDDATE AND PR.EFFECTIVEENDDATE >= PD.ENDDATE
            LEFT OUTER JOIN TCMP.CS_POSITION P ON PR.PARENTPOSITIONSEQ = P.RULEELEMENTOWNERSEQ
                AND P.REMOVEDATE = v_eot
                AND P.EFFECTIVESTARTDATE <= PD.STARTDATE AND P.EFFECTIVEENDDATE > PD.STARTDATE 
                AND P.TENANTID = 'INYC'
            WHERE PD.PERIODSEQ = v_periodRow.PERIODSEQ
                --ALM 20160907: Nos quedamos solo con las posiciones principales.
                --              NO PORQUE PERDEMOS LOS CREDITOS DE LAS POSICIONES SECUANDARIAS
                --AND (CASE WHEN P.RULEELEMENTOWNERSEQ IS NULL THEN PAD_INS.POSITIONSEQ ELSE P.RULEELEMENTOWNERSEQ END) = PAD_INS.POSITIONSEQ
        );
        filas := sql%rowcount;
        COMMIT;

        w_debug('Fin Carga de la tabla INYC_AGENTES_PRIN_MES_TEMP: '|| to_char(filas) || ' filas.', v_contador);
            
            
        w_debug('Inicio Actualizacion de Indices de la tabla INYC_AGENTES_PRIN_MES_TEMP.', v_contador);
            
        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_AGENTES_PRIN_MES_TEMP COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_AGENTES_PRIN_MES_TEMP');

        w_debug('Fin Actualizacion de Indices de la tabla INYC_AGENTES_PRIN_MES_TEMP.', v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;


        -------------------------------------------------------------------------------------------------------------------------------------
        --ALM 20170510: Preparamos nuevas tablas individulaes para los informes agrupados de Alfonso
        --Tabla de jerarquias: contendra todas las tipologias de agente, sera como la INYCEXT.INYC_AGENTES_PRIN_MES_TEMP, pero con todos los meses cargados
        --La recargamos siempre que se recaguen las tablas temporales.
        w_debug('Inicio Borrado INYC_JERARQUIA.', v_contador);

        DELETE INYCEXT.INYC_JERARQUIA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
        filas := sql%rowcount;
        COMMIT;
                
        w_debug('Fin Borrado INYC_JERARQUIA: '|| to_char(filas) || ' filas borradas.', v_contador);

                
        w_debug('Inicio Carga INYC_JERARQUIA.', v_contador);

        INSERT INTO INYCEXT.INYC_JERARQUIA 
            SELECT
                CASE 
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) 
                        THEN PAD_REG.POSITIONNAME
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) 
                        THEN PAD_SUC.POSITIONNAME
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) 
                        THEN PAD_OF.POSITIONNAME
                    ELSE PAD_PTO_VENTA.POSITIONNAME 
                    END AS COD_REGIONAL,
                CASE 
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) 
                        THEN PAD_REG.LASTNAME
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) 
                        THEN PAD_SUC.LASTNAME
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) 
                        THEN PAD_OF.LASTNAME
                    ELSE PAD_PTO_VENTA.LASTNAME
                    END AS REGIONAL,
                CASE 
                    WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                        ELSE PAD_PTO_VENTA.POSITIONNAME END 
                END AS COD_SUCURSAL,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                        ELSE PAD_PTO_VENTA.LASTNAME END 
                END AS SUCURSAL,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                    ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                    ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                PAD_INS.YEAR, PAD_INS.QUARTER, PAD_INS.PERIODO,PAD_INS.STARTDATE,
                PAD_INS.PERIODSEQ, PAD_INS.POSITIONSEQ_PRIN, PAD_INS.POSITIONSEQ, PAD_INS.PARTICIPANTSEQ, PAD_INS.BOUSERID,
                PAD_INS.POS_PRIN, PAD_INS.POS_CALLIDUS, PAD_INS.POSITIONNAME, PAD_INS.NIF,
                RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                PAD_INS.TIPO_PERSONA, PAD_INS.TAXID, PAD_INS.MUNICIPIO, PAD_INS.DOMICILIO,   
                PAD_INS.CP, PAD_INS.ID_EMPLEADO AS ID_EMPLEADO, PAD_INS.IRPF_EMPLEADO,
                PAD_INS.CIA_EMPLEADO,
                PAD_INS.ID_TIPO_AGENTE, PAD_INS.TIPO_AGENTE, PAD_INS.CUADRO_INSP_OCASO, PAD_INS.CUADRO_INSP_ETERNA,
                PAD_INS.CUADRO_RRGG_OCASO, PAD_INS.CUADRO_RRTT_OCASO, PAD_INS.CUADRO_RRGG_ETERNA, PAD_INS.CUADRO_RRTT_ETERNA,
                PAD_INS.PROMOCION, PAD_INS.SUPERRAPEL, PAD_INS.ESCALADO, PAD_INS.FEC_BAJA_POS, PAD_INS.FEC_ALTA_POS,
                --ALM 20180613: Anadimos campos del Manager para el nuevo informe 1.12.1 Produccion Agentes por Meses
                MANAGER.POS_PRIN AS MANAGER_POS_PRIN, MANAGER.POS_CALLIDUS AS MANAGER_POS_CALLIDUS, MANAGER.POSITIONNAME AS MANAGER_POSITIONNAME, MANAGER.NIF AS MANAGER_NIF,
                RTRIM(MANAGER.FIRSTNAME) || ' ' || RTRIM(MANAGER.LASTNAME) || ' ' || RTRIM(MANAGER.SUFFIX) AS MANAGER_NOMBRE,
                MANAGER.ID_TIPO_AGENTE AS MANAGER_ID_TIPO_AGENTE, MANAGER.TIPO_AGENTE AS MANAGER_TIPO_AGENTE,
                MANAGER.CUADRO_INSP_OCASO AS MANAGER_CUADRO_INSP_OCASO, MANAGER.CUADRO_INSP_ETERNA AS MANAGER_CUADRO_INSP_ETERNA,
                MANAGER.FEC_BAJA_POS AS MANAGER_FEC_BAJA_POS, MANAGER.FEC_ALTA_POS AS MANAGER_FEC_ALTA_POS,
                --ALM 20180814: Anadimos la Fecha de Alta en la Categoria de los Inspectores
                --ALM 20170512: Nos quedamos con la fecha final de la version anterior al ultimo cambio de cuadro 
                --              o, si es nula, con la fecha inicial de la primera version en la que tiene tipologia de agente con grupo/inspector/responsable  
                --(SELECT MAX(POS_ANT.EFFECTIVEENDDATE) FROM TCMP.CS_POSITION POS_ACT
                (SELECT NVL(MAX(POS_ANT.EFFECTIVEENDDATE), MIN(POS_ACT.EFFECTIVESTARTDATE)) FROM TCMP.CS_POSITION POS_ACT
                    --ALM 20170510: Tenemos que tener en cuenta cualquier cambio de tipologia no solo el paso de agente a inspector
                    LEFT JOIN TCMP.CS_POSITION POS_ANT ON POS_ACT.PAYEESEQ = POS_ANT.PAYEESEQ
                    --ALM 20170519: Tenemos en cuenta todas las versiones anteriores porque puede que venga de una tipologia que no sea inspector
                    AND POS_ACT.EFFECTIVESTARTDATE >= POS_ANT.EFFECTIVEENDDATE
                    --ALM 20170512: Por peticion de Isaac cambiamos de categoria por el cuadro no por la tipologia
                    --AND POS_ACT.GENERICNUMBER2 <> POS_ANT.GENERICNUMBER2
                    --ALM 20170519: Anadimos los casos en los que el cuadro anterior era nulo 
                    --AND POS_ACT.GENERICATTRIBUTE5 <> POS_ANT.GENERICATTRIBUTE5
                    --ATV 20240228 Los cuadros A, D y N se reagrupan en el cuadro P, la modificacion se debe a que no se debe tener en cuenta que ha habido un cambio de categoria y asi puedan acumular
                    --AND (POS_ACT.GENERICATTRIBUTE5 <> POS_ANT.GENERICATTRIBUTE5 OR POS_ANT.GENERICATTRIBUTE5 IS NULL)
                    AND (REPLACE(REPLACE(REPLACE(POS_ACT.GENERICATTRIBUTE5, 'A', 'P'), 'D', 'P'), 'N', 'P') <> REPLACE(REPLACE(REPLACE(POS_ANT.GENERICATTRIBUTE5, 'A', 'P'), 'D', 'P'), 'N', 'P') OR POS_ANT.GENERICATTRIBUTE5 IS NULL)
                    AND POS_ANT.REMOVEDATE = to_date('22000101','yyyymmdd')
                    WHERE POS_ACT.REMOVEDATE = to_date('22000101','yyyymmdd')
                        --ALM 20170320: Se tiene que tener en cuenta la fecha de la version de cuando ha sido TTL SIN PLAN.
                        --ALM 20170323: Por peticion de Alfonso no tenemos en cuenta bajas intermedias de los agentes
                        --AND (POS.GENERICNUMBER2 < 50 OR POS.TITLESEQ = 5629499534213290)
                        --ALM 20170512: Filtramos las versiones de las posiciones con tipologia de agente con grupo/inspector/responsable
                        AND POS_ACT.GENERICNUMBER2 >= 50
                        AND POS_ACT.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE
                        AND POS_ACT.PAYEESEQ = PAD_INS.PARTICIPANTSEQ
                        --ALM 20170323: Por peticion de Alfonso cogemos fechas por Persona (Participant no por Position)
                        --AND POS.RULEELEMENTOWNERSEQ = PAD_INS.POSITIONSEQ_PRIN
                ) AS FEC_ALTA_CAT_INS
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
            --ALM 20180613: Unimos por el Manager para poder extraer informacion de el para el nuevo informe 1.12.1 Produccion Agentes por Meses
            LEFT OUTER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP MANAGER ON PAD_INS.PERIODSEQ = MANAGER.PERIODSEQ 
                AND PAD_INS.MANAGERSEQ_PRIN = MANAGER.POSITIONSEQ_PRIN
            WHERE PAD_INS.POS_PRIN <> '0000000000'
            ;
                            
        filas := sql%rowcount;            
        COMMIT;           
                    
        w_debug('Fin Carga INYC_JERARQUIA: '|| to_char(filas) || ' filas.', v_contador);
                
                
        w_debug('Inicio Actualizacion Indices INYC_JERARQUIA.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_JERARQUIA COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_JERARQUIA');

        w_debug('Fin Actualizacion Indices INYC_JERARQUIA.', v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
    
    END IF;
    
    -------------------------------------------------------------------------------------------------------------------------------------
    -- %%DTB 20250521 Recarga tablas informes
    ----TABLAS DE INFORMES
    --Carga tabla del Informe: 1.11 Percepciones Agentes
    IF informe = 'PEAG' OR informe LIKE '%,PEAG,%' OR informe LIKE '%,PEAG' OR informe LIKE 'PEAG,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PERC_AGENTES.', v_contador);

        DELETE INYCEXT.INYC_PERC_AGENTES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PERC_AGENTES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PERC_AGENTES. Percepciones.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_AGENTES 
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER, PAD_INS.PERIODO, PAD_INS.STARTDATE, PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                PERC.DESCRIPCION AS PERCEPCION, D.VALUE AS IMP_PERCEPCION,
                (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS MES_PERCEPCION,
                0 AS BALANCE,D.EARNINGCODEID, D.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN, PAD_INS.POSITIONSEQ, PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN, PAD_INS.POS_CALLIDUS, PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                        AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                        AND PD.STARTDATE <= PAD_INS.STARTDATE
                                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                                        AND PD.PERIODTYPESEQ = 2814749767106561)
                AND D.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND D.PROCESSINGUNITSEQ = 38280596832649217
                --AND D.VALUE <> 0
                AND SUBSTR(D.EARNINGGROUPID,7,2) = '01'
                --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
            INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                AND D.EARNINGGROUPID = PERC.EARNINGGROUP
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 112
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_AGENTES. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
        
        w_debug('Inicio Carga INYC_PERC_AGENTES. Percepciones DDEE.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_AGENTES 
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Comision DDEE' as PERCEPCION,
                SUM(CAR_LP.IMPORTE) AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,
                0 AS BALANCE,
                CAR_LP.EARNINGCODEID,CAR_LP.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                --JGE 20230816 Solamente tiene que salir los 01 Ocaso
                AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                AND CAR_LP.IMPORTE <> 0
            GROUP BY
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,CAR_LP.EARNINGCODEID,CAR_LP.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_AGENTES. Percepciones DDEE: '|| to_char(filas) || ' filas.', v_contador);

        w_debug('Inicio Carga INYC_PERC_AGENTES. Balances.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_AGENTES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER, PAD_INS.PERIODO, PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS PERCEPCION,
                B.VALUE AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,                
                1 AS BALANCE,B.EARNINGCODEID,B.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
            INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                AND B.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND B.PROCESSINGUNITSEQ = 38280596832649217
                --AND D.VALUE <> 0
                AND SUBSTR(B.EARNINGGROUPID,7,2) = '01'
                --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S4'
                --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
            --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
            INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                --ALM 20211025: Anadimos condicion para mejorar el rendimiento de la consulta
                AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
            --INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
            INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                AND EC.TENANTID = 'INYC'
                AND EC.REMOVEDATE = v_eot
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_AGENTES. Balances: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_PERC_AGENTES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PERC_AGENTES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PERC_AGENTES');

        w_debug('Fin Actualizacion Indices INYC_PERC_AGENTES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PERC_AGENTES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PERC_AGENTES');
    
        w_debug('Fin actualizacion del parametro INYC_PERC_AGENTES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
    
    --Carga tabla del Informe: 1.12 Produccion Agentes
    IF informe = 'PRAG' OR informe LIKE '%,PRAG,%' OR informe LIKE '%,PRAG' OR informe LIKE 'PRAG,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PROD_AGENTES.', v_contador);

        DELETE INYCEXT.INYC_PROD_AGENTES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PROD_AGENTES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PROD_AGENTES. Creditos Agente.', v_contador);

        INSERT INTO INYCEXT.INYC_PROD_AGENTES
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                C.NAME,C.VALUE,
                --ALM 20170510: Solo tomamos el valor de polizas corregidas para los creditos de Polizas'
                CASE WHEN C.NAME LIKE '%NumeroPolizas-998%' THEN C.GENERICNUMBER4 ELSE 0 END AS C_GN4,
                CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.EVENTO,ST.PRODUCTO,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME,
                --ALM 20180613: Anadimos la tipoligia del agente para el nuevo informe 1.12.1 Produccion Agentes por Meses
                PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                --ALM 20210514: Por peticion de Alfonso, anadimos para los creditos de prima la Prima Neta de Recibo
                CASE WHEN C.NAME LIKE '%Prima-998%' THEN ST.GENERICNUMBER1 ELSE 0 END AS PRIMA_NETA
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                ----ALM 20160928: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas
                --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                --ALM 20170407: Filtramos por los creditos de agente
                AND C.NAME LIKE 'DC-O-GEN-Agente-%'
            INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                AND REG.COD_INFORME = 112.1
                AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 112
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --ALM 20170405: Filtramos por las tipologias de agentes
                AND AG.ID_TIPO_AGENTE < 50
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PROD_AGENTES. Creditos Agente: '|| to_char(filas) || ' filas.', v_contador);

        w_debug('Inicio Carga INYC_PROD_AGENTES. Creditos Agente con Grupo.', v_contador);

        INSERT INTO INYCEXT.INYC_PROD_AGENTES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                C.NAME,C.VALUE,
                --ALM 20170510: Solo tomamos el valor de polizas corregidas para los creditos de Polizas'
                CASE WHEN C.NAME LIKE '%NumeroPolizas-998%' THEN C.GENERICNUMBER4 ELSE 0 END AS C_GN4,
                CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.EVENTO,ST.PRODUCTO,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME,
                --ALM 20180613: Anadimos la tipoligia del agente para el nuevo informe 1.12.1 Produccion Agentes por Meses
                PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                --ALM 20210514: Por peticion de Alfonso, anadimos para los creditos de prima la Prima Neta de Recibo
                CASE WHEN C.NAME LIKE '%Prima-998%' THEN ST.GENERICNUMBER1 ELSE 0 END AS PRIMA_NETA
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                ----ALM 20160928: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas
                --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                --ALM 20170407: Filtramos por los creditos de agente con grupo
                --ALM 20181019: Los creditos de asegurados de produccion propia no llevan la palabra inspector 
                --AND C.NAME LIKE 'DC-O-GEN-Inspector-%'
                AND (C.NAME LIKE 'DC-O-GEN-Inspector-%' OR C.NAME = 'DC-O-GEN-Agente-NumAsegurados')
            INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                --ALM 20170711: Filtramos las transacciones con el campo Excluido Comisiones (GA20) = 1
                --              No son propias del agente con grupo sino de algun agente de su grupo que ya esta de baja
                AND (ST.GENERICATTRIBUTE20 IS NULL OR ST.GENERICATTRIBUTE20 = 0)
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                AND REG.COD_INFORME = 112.1
                AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 112
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --ALM 20170405: Filtramos por las tipologias de agentes con grupo
                AND AG.ID_TIPO_AGENTE >= 50
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PROD_AGENTES. Creditos Agente con Grupo: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_PROD_AGENTES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PROD_AGENTES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PROD_AGENTES');

        w_debug('Fin actualizacion Indices INYC_PROD_AGENTES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PROD_AGENTES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PROD_AGENTES');
    
        w_debug('Fin actualizacion del parametro INYC_PROD_AGENTES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
    
    --Carga tabla del Informe: 1.13 Percepciones Inspectores
    IF informe = 'PEIN' OR informe LIKE '%,PEIN,%' OR informe LIKE '%,PEIN' OR informe LIKE 'PEIN,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PERC_INSPECTORES.', v_contador);

        DELETE INYCEXT.INYC_PERC_INSPECTORES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PERC_INSPECTORES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PERC_INSPECTORES. Percepciones.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_INSPECTORES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                PERC.DESCRIPCION AS PERCEPCION,D.VALUE AS IMP_PERCEPCION,
                (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS MES_PERCEPCION,
                0 AS BALANCE,D.EARNINGCODEID,D.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                    AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                            AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                            AND PD.STARTDATE <= PAD_INS.STARTDATE
                                            --Filtramos por el tipo de periodo para quedarnos solo los meses
                                            AND PD.PERIODTYPESEQ = 2814749767106561)
                    AND D.TENANTID = 'INYC'
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND D.PROCESSINGUNITSEQ = 38280596832649217
                    --AND D.VALUE <> 0
                    AND SUBSTR(D.EARNINGGROUPID,7,2) = '01'
                    --ALM 20170220: Modificacion pedida por David para incluir unicamente Percepciones derivadas del S5,
                    --              debido a indicaciones del departamente de laboral
                    AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S5'
                    --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                    AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
                INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 114
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_INSPECTORES. Percepciones: '|| to_char(filas) || ' filas.', v_contador);

        w_debug('Inicio Carga INYC_PERC_INSPECTORES. Balances.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_INSPECTORES
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot
                    AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS PERCEPCION,
                B.VALUE AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,
                1 AS BALANCE,B.EARNINGCODEID,B.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                    AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot
                        AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                    AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot
                        AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                    AND B.TENANTID = 'INYC'
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND B.PROCESSINGUNITSEQ = 38280596832649217
                    --AND D.VALUE <> 0
                    AND SUBSTR(B.EARNINGGROUPID,7,2) = '01'
                    --ALM 20170220: Modificacion pedida por David para incluir unicamente Percepciones derivadas del S5,
                    --              debido a indicaciones del departamente de laboral
                    AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S5'
                    --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                    AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
                --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
                INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                    AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
                --ATV 20250108 Comentamos la linea por problemas de rendicimiento
                --INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC' AND EC.REMOVEDATE = v_eot
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_INSPECTORES. Balances: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_PERC_INSPECTORES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PERC_INSPECTORES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PERC_INSPECTORES');

        w_debug('Fin Actualizacion Indices INYC_PERC_INSPECTORES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PERC_INSPECTORES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PERC_INSPECTORES');
    
        w_debug('Fin actualizacion del parametro INYC_PERC_INSPECTORES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
    
    --Carga tabla del Informe: 1.14 Produccion Inspectores
    IF informe = 'PRIN' OR informe LIKE '%,PRIN,%' OR informe LIKE '%,PRIN' OR informe LIKE 'PRIN,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PROD_INSPECTORES.', v_contador);

        DELETE INYCEXT.INYC_PROD_INSPECTORES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PROD_INSPECTORES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PROD_INSPECTORES.', v_contador);

        INSERT INTO INYCEXT.INYC_PROD_INSPECTORES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                C.NAME,C.VALUE,
                --ALM 20170607: Solo tomamos el valor de la prima neta para los creditos de Primas
                CASE WHEN C.NAME LIKE '%PrimaCorregida-998%' THEN C.GENERICNUMBER5 ELSE 0 END AS C_GN5,
                CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.EVENTO,ST.PRODUCTO,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME,
                --ALM 20180119: Anadimos las polizas corregidas
                CASE WHEN C.NAME LIKE '%NumeroPolizas-998%' THEN C.GENERICNUMBER4 ELSE 0 END AS POLIZ_CORR,
                --ALM 20210514: Por peticion de Alfonso, anadimos para los creditos de prima la Prima Neta de Recibo
                CASE WHEN C.NAME LIKE '%PrimaCorregida-998%' THEN ST.GENERICNUMBER1 ELSE 0 END AS PRIMA_NETA,
                --ATV 20230428 Anyadimos nuevo campo de agente para sacar nuevo informe por detalle de agente
                C.GENERICATTRIBUTE4 AS C_GA4
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20161004: Filtramos los creditos que tengan el valor y la prima neta a 0, sino no coinciden con las medidas de Prima
                    --ALM 20180212: Filtramos por los creditos que cuentan polizas corregidas
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER5 <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                    --ALM 20161004: Filtramos para no tener en cuenta los creditos directos que pertenecen a inspectores que 
                    --              cuando emitieron la poliza eran agentes
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
            INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 114.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 114
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                            --ALM 20170628: Por peticion de David anadimos los tipos 82
                            AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                        OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PROD_INSPECTORES: '|| to_char(filas) || ' filas.', v_contador);

        
        w_debug('Inicio Actualizacion Indices INYC_PROD_INSPECTORES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PROD_INSPECTORES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PROD_INSPECTORES');

        w_debug('Fin Actualizacion Indices INYC_PROD_INSPECTORES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PROD_INSPECTORES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PROD_INSPECTORES');
    
        w_debug('Fin actualizacion del parametro INYC_PROD_INSPECTORES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;

    --ATV 20231004 Carga tabla del Informe: 1.17 Produccion Inspectores Eterna
    IF informe = 'PRIN_E' OR informe LIKE '%,PRIN_E,%' OR informe LIKE '%,PRIN_E' OR informe LIKE 'PRIN_E,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PROD_E_INSPECTORES.', v_contador);

        DELETE INYCEXT.INYC_PROD_E_INSPECTORES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PROD_E_INSPECTORES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PROD_E_INSPECTORES.', v_contador);

        INSERT INTO INYCEXT.INYC_PROD_E_INSPECTORES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                C.NAME,C.VALUE,
                --ALM 20170607: Solo tomamos el valor de la prima neta para los creditos de Primas
                CASE WHEN C.NAME LIKE '%PrimaCorregida-998%' THEN C.GENERICNUMBER5 ELSE 0 END AS C_GN5,
                CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.EVENTO,ST.PRODUCTO,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME,
                --ALM 20180119: Anadimos las polizas corregidas
                CASE WHEN C.NAME LIKE '%NumeroPolizas-998%' THEN C.GENERICNUMBER4 ELSE 0 END AS POLIZ_CORR,
                --ALM 20210514: Por peticion de Alfonso, anadimos para los creditos de prima la Prima Neta de Recibo
                CASE WHEN C.NAME LIKE '%PrimaCorregida-998%' THEN ST.GENERICNUMBER1 ELSE 0 END AS PRIMA_NETA,
                --ATV 20230428 Anyadimos nuevo campo de agente para sacar nuevo informe por detalle de agente
                C.GENERICATTRIBUTE4 AS C_GA4
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20161004: Filtramos los creditos que tengan el valor y la prima neta a 0, sino no coinciden con las medidas de Prima
                    --ALM 20180212: Filtramos por los creditos que cuentan polizas corregidas
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER5 <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                    --ALM 20161004: Filtramos para no tener en cuenta los creditos directos que pertenecen a inspectores que 
                    --              cuando emitieron la poliza eran agentes
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
            INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 117.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 117
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                            --ALM 20170628: Por peticion de David anadimos los tipos 82
                            AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                        OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PROD_E_INSPECTORES: '|| to_char(filas) || ' filas.', v_contador);

        
        w_debug('Inicio Actualizacion Indices INYC_PROD_E_INSPECTORES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PROD_E_INSPECTORES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PROD_E_INSPECTORES');

        w_debug('Fin Actualizacion Indices INYC_PROD_E_INSPECTORES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PROD_E_INSPECTORES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PROD_E_INSPECTORES');
    
        w_debug('Fin actualizacion del parametro INYC_PROD_E_INSPECTORES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
    
    --Carga tabla del Informe: 1.15 Cartera Agentes
    IF informe = 'CARTERA' OR informe LIKE '%,CARTERA,%' OR informe LIKE '%,CARTERA' OR informe LIKE 'CARTERA,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_CARTERA_AGENTES.', v_contador);

        DELETE INYCEXT.INYC_CARTERA_AGENTES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_CARTERA_AGENTES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_CARTERA_AGENTES. Commissions.', v_contador);

        INSERT INTO INYCEXT.INYC_CARTERA_AGENTES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                C.NAME,C.VALUE,C.GENERICNUMBER4 AS C_GN4,
                CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.EVENTO,ST.PRODUCTO,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                AND C.VALUE <> 0
                AND C.NAME LIKE 'DC-O-CA-%'
            INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 112
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_CARTERA_AGENTES. Commissions: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Carga .INYC_CARTERA_AGENTES. DDEE.', v_contador);
            
        INSERT INTO INYCEXT.INYC_CARTERA_AGENTES
            SELECT
                PAD_INS.YEAR,
                PAD_INS.QUARTER,
                PAD_INS.PERIODO,
                PAD_INS.STARTDATE,
                PAD_INS.PERIODSEQ,
                PAD_INS.NIF,            
                'CARTERA_DDEE' as NAME,
                CAR_LP.IMPORTE as VALUE,
                0 as C_GN4,
                CAR_LP.ORDERID ||CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                CAR_LP.POLIZA,
                CAR_LP.PRODUCTID,
                CAR_LP.ACCOUNTINGDATE,
                CAR_LP.FEC_VTO_REC,  --ST.GENERICDATE2,
                CAR_LP.EVENTO,
                CAR_LP.PRODUCTO,
                PAD_INS.POSITIONSEQ_PRIN,
                PAD_INS.POSITIONSEQ,
                PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,
                PAD_INS.POS_CALLIDUS,
                PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
            --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
            AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
            --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                AND CAR_LP.IMPORTE <> 0
            ;
                                    
        filas := sql%rowcount;            
        COMMIT;           
                
        w_debug('Fin Carga .INYC_CARTERA_AGENTES_DE. DDEE: '|| to_char(filas) || ' filas.', v_contador);
        
        --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
        --END IF;
        
        
        w_debug('Inicio Actualizacion Indices INYC_CARTERA_AGENTES.', v_contador);
        
        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_CARTERA_AGENTES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_CARTERA_AGENTES');
        
        w_debug('Fin actualizacion Indices INYC_CARTERA_AGENTES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_CARTERA_AGENTES',v_contador);
        
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_CARTERA_AGENTES');
        
        w_debug('Fin actualizacion del parametro INYC_CARTERA_AGENTES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
     
    --Carga tabla del Informe: 1.16 Agentes Activos - OMESCU
    IF informe = 'OMESCU' OR informe LIKE '%,OMESCU,%' OR informe LIKE '%,OMESCU' OR informe LIKE 'OMESCU,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_INSP_ACTIVOS.', v_contador);

        DELETE INYCEXT.INYC_INSP_ACTIVOS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_INSP_ACTIVOS: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_INSP_ACTIVOS.', v_contador);

        INSERT INTO INYCEXT.INYC_INSP_ACTIVOS 
            SELECT DISTINCT
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END
                END END AS COD_REGIONAL,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END
                END END AS REGIONAL,   
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                        ELSE PAD_PTO_VENTA.POSITIONNAME END 
                END AS COD_SUCURSAL,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                        ELSE PAD_PTO_VENTA.LASTNAME END 
                END AS SUCURSAL,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                    ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                    ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                PAD_INS.POS_PRIN,
                RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                PAD_INS.NIF,
                PAD_INS.CUADRO_INSP_OCASO AS CUADRO_INSP,
                PAD_INS.ID_TIPO_AGENTE,
                PAD_INS.TIPO_AGENTE,
                SUM(CASE WHEN M.NAME IN ('SM-O-GEN-Inspector-NumeroPolizas-998-TotalMes')
                    THEN M.VALUE ELSE 0 END) AS NUM_POL,
                SUM(CASE WHEN M.NAME IN ('SM-O-GEN-Inspector-Prima-998-TotalMes')
                    THEN M.VALUE ELSE 0 END) AS NUM_PRIMA_NETA,
                SUM(CASE WHEN M.NAME IN ('SM-O-GEN-Inspector-PrimaCorregida-998-TotalMes')
                    THEN M.VALUE ELSE 0 END) AS NUM_PRIMA_CORR,
                --ALM 20170622: Se modifica las medidas para que sea Callidus el que calcule el objetivo que tiene cada inspector
                --CASE WHEN PAD_INS.CUADRO_INSP_OCASO = 'A' THEN 500
                --    WHEN PAD_INS.CUADRO_INSP_OCASO IN ('N','D') THEN 425
                --    ELSE SUM(CASE WHEN M.NAME IN ('SM-O-RPP-Inspector-ObjetivoAnual-NumPolizas-998') THEN M.VALUE ELSE 0 END)
                --END AS OBJ_POL,
                SUM(CASE WHEN M.NAME IN ('SM-O-RPP-Inspector-ObjetivoAnual-NumPolizas-998') 
                    THEN M.VALUE ELSE 0 END) AS OBJ_POL,
                --CASE WHEN PAD_INS.CUADRO_INSP_OCASO = 'A' THEN 128000
                --    WHEN PAD_INS.CUADRO_INSP_OCASO IN ('N','D') THEN 109000
                --    ELSE SUM(CASE WHEN M.NAME IN ('SM-O-RPP-Inspector-ObjetivoUnicoAnual-PrimaCorregida') THEN M.VALUE ELSE 0 END)
                --END AS OBJ_PRIMA,
                SUM(CASE WHEN M.NAME IN ('SM-O-RPP-Inspector-ObjetivoUnicoAnual-PrimaCorregida') 
                    THEN M.VALUE ELSE 0 END) AS OBJ_PRIMA,
                --POS_INS.FEC_ALTA_POS as FEC_ALTA_POS,
                (SELECT MIN(POS.GENERICDATE1) FROM TCMP.CS_POSITION POS 
                    WHERE POS.REMOVEDATE = to_date('22000101','yyyymmdd') 
                        AND POS.GENERICNUMBER2 >= 50 
                        AND POS.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE
                        AND POS.PAYEESEQ = PAD_INS.PARTICIPANTSEQ
                        --ALM 20170323: Por peticion de Alfonso cogemos fechas por Persona (Participant no por Position)
                        --AND POS.RULEELEMENTOWNERSEQ = PAD_INS.POSITIONSEQ_PRIN
                ) AS FEC_ALTA_POS,
                --CASE WHEN POS_AG.FEC_ALTA_CAT IS NULL THEN POS_INS.FEC_ALTA_POS ELSE POS_AG.FEC_ALTA_CAT END AS FEC_ALTA_CAT,
                --ALM 20170512: Nos quedamos con la fecha final de la version anterior al ultimo cambio de cuadro 
                --              o, si es nula, con la fecha inicial de la primera version en la que tiene tipologia de agente con grupo/inspector/responsable  
                --(SELECT MAX(POS_ANT.EFFECTIVEENDDATE) FROM TCMP.CS_POSITION POS_ACT
                (SELECT NVL(MAX(POS_ANT.EFFECTIVEENDDATE),MIN(POS_ACT.EFFECTIVESTARTDATE)) FROM TCMP.CS_POSITION POS_ACT
                    --ALM 20170510: Tenemos que tener en cuenta cualquier cambio de tipologia no solo el paso de agente a inspector
                    LEFT JOIN TCMP.CS_POSITION POS_ANT ON POS_ACT.PAYEESEQ = POS_ANT.PAYEESEQ
                    --ALM 20170519: Tenemos en cuenta todas las versiones anteriores porque puede que venga de una tipologia que no sea inspector
                    AND POS_ACT.EFFECTIVESTARTDATE >= POS_ANT.EFFECTIVEENDDATE
                    --ALM 20170512: Por peticion de Isaac cambiamos de categoria por el cuadro no por la tipologia
                    --AND POS_ACT.GENERICNUMBER2 <> POS_ANT.GENERICNUMBER2
                    --ALM 20170519: Anadimos los casos en los que el cuadro anterior era nulo 
                    --AND POS_ACT.GENERICATTRIBUTE5 <> POS_ANT.GENERICATTRIBUTE5
                    --ATV 20240313 Los cuadros A, D y N se reagrupan en el cuadro P, la modificacion se debe a que no se debe tener en cuenta que ha habido un cambio de categoria y asi puedan acumular
                    --AND (POS_ACT.GENERICATTRIBUTE5 <> POS_ANT.GENERICATTRIBUTE5 OR POS_ANT.GENERICATTRIBUTE5 IS NULL)
                    AND (REPLACE(REPLACE(REPLACE(POS_ACT.GENERICATTRIBUTE5, 'A', 'P'), 'D', 'P'), 'N', 'P') <> REPLACE(REPLACE(REPLACE(POS_ANT.GENERICATTRIBUTE5, 'A', 'P'), 'D', 'P'), 'N', 'P') OR POS_ANT.GENERICATTRIBUTE5 IS NULL)
                    AND POS_ANT.REMOVEDATE = to_date('22000101','yyyymmdd')
                    WHERE POS_ACT.REMOVEDATE = to_date('22000101','yyyymmdd')
                        --ALM 20170320: Se tiene que tener en cuenta la fecha de la version de cuando ha sido TTL SIN PLAN.
                        --ALM 20170323: Por peticion de Alfonso no tenemos en cuenta bajas intermedias de los agentes
                        --AND (POS.GENERICNUMBER2 < 50 OR POS.TITLESEQ = 5629499534213290)
                        --ALM 20170512: Filtramos las versiones de las posiciones con tipologia de agente con grupo/inspector/responsable
                        AND POS_ACT.GENERICNUMBER2 >= 50
                        AND POS_ACT.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE
                        AND POS_ACT.PAYEESEQ = PAD_INS.PARTICIPANTSEQ
                        --ALM 20170323: Por peticion de Alfonso cogemos fechas por Persona (Participant no por Position)
                        --AND POS.RULEELEMENTOWNERSEQ = PAD_INS.POSITIONSEQ_PRIN
                ) AS FEC_ALTA_CAT,
                PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                --ALM 20180130: Anadimos las polizas corregidas por peticion de Alfonso.
                SUM(CASE WHEN M.NAME IN ('SM-O-GEN-Inspector-NumeroPolizasCorregidas-998-TotalMes')
                    THEN M.VALUE ELSE 0 END) AS NUM_POL_CORR
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            --LEFT JOIN (SELECT POS.GENERICATTRIBUTE3,MAX(POS.GENERICDATE1) AS FEC_ALTA_POS FROM TCMP.CS_POSITION POS 
            --        WHERE POS.REMOVEDATE = to_date('22000101','yyyymmdd') AND POS.GENERICNUMBER2 >= 50
            --        GROUP BY POS.GENERICATTRIBUTE3
            --) POS_INS ON PAD_INS.POS_PRIN = POS_INS.GENERICATTRIBUTE3   
            --LEFT JOIN (SELECT POS.GENERICATTRIBUTE3,MAX(POS.EFFECTIVEENDDATE) AS FEC_ALTA_CAT FROM TCMP.CS_POSITION POS 
            --        WHERE POS.REMOVEDATE = to_date('22000101','yyyymmdd') AND POS.GENERICNUMBER2 < 50
            --        GROUP BY POS.GENERICATTRIBUTE3
            --) POS_AG ON PAD_INS.POS_PRIN = POS_AG.GENERICATTRIBUTE3   
            INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                AND REG.COD_INFORME = 116.1
                AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 116
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
            --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
            GROUP BY
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END
                END END,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END
                END END,   
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                        ELSE PAD_PTO_VENTA.POSITIONNAME END 
                END,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                        ELSE PAD_PTO_VENTA.LASTNAME END 
                END,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                    ELSE PAD_PTO_VENTA.POSITIONNAME END,
                CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                    ELSE PAD_PTO_VENTA.LASTNAME END,
                PAD_INS.POS_PRIN,
                RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                PAD_INS.NIF,
                PAD_INS.CUADRO_INSP_OCASO,
                PAD_INS.ID_TIPO_AGENTE,
                PAD_INS.TIPO_AGENTE,
                --POS_INS.FEC_ALTA_POS,
                --POS_AG.FEC_ALTA_CAT,
                PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.STARTDATE
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_INSP_ACTIVOS: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_INSP_ACTIVOS.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_INSP_ACTIVOS COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_INSP_ACTIVOS');

        w_debug('Fin Actualizacion Indices INYC_INSP_ACTIVOS.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_INSP_ACTIVOS',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_INSP_ACTIVOS');
    
        w_debug('Fin actualizacion del parametro INYC_INSP_ACTIVOS',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
    
    --Carga tabla del Informe: 3.3 Percepciones Agentes Eterna
    IF informe = 'PEAG_E' OR informe LIKE '%,PEAG_E,%' OR informe LIKE '%,PEAG_E' OR informe LIKE 'PEAG_E,%' OR informe = 'ALL' THEN
        --ATV 20230712: Cargamos una tabla nueva para el informe de percepciones de eterna.
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PERC_E_AGENTES.', v_contador);

        DELETE INYCEXT.INYC_PERC_E_AGENTES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PERC_E_AGENTES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PERC_E_AGENTES. Percepciones.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_E_AGENTES 
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER, PAD_INS.PERIODO, PAD_INS.STARTDATE, PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                PERC.DESCRIPCION AS PERCEPCION, D.VALUE AS IMP_PERCEPCION,
                (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS MES_PERCEPCION,
                0 AS BALANCE,D.EARNINGCODEID, D.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN, PAD_INS.POSITIONSEQ, PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN, PAD_INS.POS_CALLIDUS, PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                        AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                        AND PD.STARTDATE <= PAD_INS.STARTDATE
                                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                                        AND PD.PERIODTYPESEQ = 2814749767106561)
                AND D.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND D.PROCESSINGUNITSEQ = 38280596832649217
                --AND D.VALUE <> 0
                AND SUBSTR(D.EARNINGGROUPID,7,2) = '03'
                --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
            INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                AND D.EARNINGGROUPID = PERC.EARNINGGROUP
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 3.3
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_E_AGENTES. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
        
        w_debug('Inicio Carga INYC_PERC_E_AGENTES. Percepciones DDEE.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_E_AGENTES 
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Comision DDEE' as PERCEPCION,
                SUM(CAR_LP.IMPORTE) AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,
                0 AS BALANCE,
                CAR_LP.EARNINGCODEID,CAR_LP.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                --JGE 20230804 excluimos ocaso
                AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                AND CAR_LP.IMPORTE <> 0
            GROUP BY 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,CAR_LP.EARNINGCODEID,CAR_LP.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_E_AGENTES. Percepciones DDEE: '|| to_char(filas) || ' filas.', v_contador);

        w_debug('Inicio Carga INYC_PERC_E_AGENTES. Balances.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_E_AGENTES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER, PAD_INS.PERIODO, PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS PERCEPCION,
                B.VALUE AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,                
                1 AS BALANCE,B.EARNINGCODEID,B.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
            INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                AND B.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND B.PROCESSINGUNITSEQ = 38280596832649217
                --AND D.VALUE <> 0
                AND SUBSTR(B.EARNINGGROUPID,7,2) = '03'
                --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S4'
                --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
            --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
            INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                --ALM 20211025: Anadimos condicion para mejorar el rendimiento de la consulta
                AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
            --INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
            INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                AND EC.TENANTID = 'INYC'
                AND EC.REMOVEDATE = v_eot
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_E_AGENTES. Balances: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_PERC_E_AGENTES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PERC_E_AGENTES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PERC_E_AGENTES');

        w_debug('Fin Actualizacion Indices INYC_PERC_E_AGENTES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PERC_E_AGENTES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PERC_E_AGENTES');
    
        w_debug('Fin actualizacion del parametro INYC_PERC_E_AGENTES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;

    --Carga tabla del Informe: 3.4 Percepciones Inspectores Eterna
    IF informe = 'PEIN_E' OR informe LIKE '%,PEIN_E,%' OR informe LIKE '%,PEIN_E' OR informe LIKE 'PEIN_E,%' OR informe = 'ALL' THEN
        --ATV 20230927: Cargamos una tabla nueva para el informe de percepciones inspectores de eterna.
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PERC_E_INSPECTORES.', v_contador);

        DELETE INYCEXT.INYC_PERC_E_INSPECTORES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PERC_E_INSPECTORES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PERC_E_INSPECTORES. Percepciones.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_E_INSPECTORES 
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER, PAD_INS.PERIODO, PAD_INS.STARTDATE, PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                PERC.DESCRIPCION AS PERCEPCION, D.VALUE AS IMP_PERCEPCION,
                (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS MES_PERCEPCION,
                0 AS BALANCE,D.EARNINGCODEID, D.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN, PAD_INS.POSITIONSEQ, PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN, PAD_INS.POS_CALLIDUS, PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                        AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                        AND PD.STARTDATE <= PAD_INS.STARTDATE
                                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                                        AND PD.PERIODTYPESEQ = 2814749767106561)
                AND D.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND D.PROCESSINGUNITSEQ = 38280596832649217
                --AND D.VALUE <> 0
                AND SUBSTR(D.EARNINGGROUPID,7,2) = '03'
                --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S5
                AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S5'
                --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
            INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                AND D.EARNINGGROUPID = PERC.EARNINGGROUP
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 3.4
                AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_E_INSPECTORES. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
        
        w_debug('Inicio Carga INYC_PERC_E_INSPECTORES. Percepciones DDEE.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_E_INSPECTORES 
            SELECT
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Comision DDEE' as PERCEPCION,
                SUM(CAR_LP.IMPORTE) AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,
                0 AS BALANCE,
                CAR_LP.EARNINGCODEID,CAR_LP.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                --JGE 20230804 excluimos ocaso
                AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S5'
                AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                AND CAR_LP.IMPORTE <> 0
            GROUP BY 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,CAR_LP.EARNINGCODEID,CAR_LP.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_E_INSPECTORES. Percepciones DDEE: '|| to_char(filas) || ' filas.', v_contador);

        w_debug('Inicio Carga INYC_PERC_E_INSPECTORES. Balances.', v_contador);

        INSERT INTO INYCEXT.INYC_PERC_E_INSPECTORES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER, PAD_INS.PERIODO, PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS PERCEPCION,
                B.VALUE AS IMP_PERCEPCION,
                EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS MES_PERCEPCION,                
                1 AS BALANCE,B.EARNINGCODEID,B.EARNINGGROUPID,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
            INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                AND B.TENANTID = 'INYC'
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND B.PROCESSINGUNITSEQ = 38280596832649217
                --AND D.VALUE <> 0
                AND SUBSTR(B.EARNINGGROUPID,7,2) = '03'
                --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S5'
                --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
            INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
            --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
            INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                --ALM 20211025: Anadimos condicion para mejorar el rendimiento de la consulta
                AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
            --INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
            INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                AND EC.TENANTID = 'INYC'
                AND EC.REMOVEDATE = v_eot
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PERC_E_INSPECTORES. Balances: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_PERC_E_INSPECTORES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PERC_E_INSPECTORES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PERC_E_INSPECTORES');

        w_debug('Fin Actualizacion Indices INYC_PERC_E_INSPECTORES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PERC_E_INSPECTORES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PERC_E_INSPECTORES');
    
        w_debug('Fin actualizacion del parametro INYC_PERC_E_INSPECTORES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;

    --Carga tabla del Informe: 3.2 Produccion Agentes
    IF informe = 'PRAG_E' OR informe LIKE '%,PRAG_E,%' OR informe LIKE '%,PRAG_E' OR informe LIKE 'PRAG_E,%' OR informe = 'ALL' THEN
        
        --ALM 20170420: No tenemos en cuenta si el periodo esta cerrado para este informe porque no se entrega a agentes.
        --              Por lo tanto lo recargamos siempre con la ultima informacion.    
        w_debug('Inicio Borrado INYC_PROD_E_AGENTES.', v_contador);

        DELETE INYCEXT.INYC_PROD_E_AGENTES WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
        
        filas := sql%rowcount;            
        COMMIT;
        
        w_debug('Fin Borrado INYC_PROD_E_AGENTES: '|| to_char(filas) || ' filas borradas.', v_contador);

        
        w_debug('Inicio Carga INYC_PROD_E_AGENTES.', v_contador);

        INSERT INTO INYCEXT.INYC_PROD_E_AGENTES 
            SELECT 
                PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,
                PAD_INS.NIF,
                --ALM 20180226: Sumamos el valor de los creditos para no tener en cuenta las polizas no propias
                M.NAME,--M.VALUE
               --MGC 20190415 A�adimos un nuevo CASE para que en caso de ser primas, tome el valor del GN5, y para el resto de casos (que no sean p�lizas corregidas, ni primas), tome el valor del cr�dito
                SUM(CASE WHEN M.NAME LIKE '%Corregidas%' THEN C.GENERICNUMBER4 ELSE (CASE WHEN M.NAME LIKE '%Prima%' THEN C.GENERICNUMBER5 ELSE C.VALUE END) END) AS VALUE,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                AND PAD_INS.PERIODSEQ = M.PERIODSEQ 
                AND M.TENANTID = 'INYC'
                --AND M.VALUE <> 0
            --ALM 20180226: Sumamos el valor de los creditos para no tener en cuenta las polizas no propias
            INNER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                AND PMCT.TENANTID = 'INYC'
            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                --ALM 20180919: Los creditos de asegurados tienen el GN4 vacio
                --AND C.GENERICBOOLEAN4 = 1
                AND (C.GENERICBOOLEAN4 = 1 OR C.NAME = 'DC-E-GEN-Agente-NumAsegurados')
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                AND REG.COD_INFORME = 302.1
                AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
            GROUP BY PAD_INS.YEAR,PAD_INS.QUARTER,PAD_INS.PERIODO,PAD_INS.STARTDATE,PAD_INS.PERIODSEQ,PAD_INS.NIF,M.NAME,
                PAD_INS.POSITIONSEQ_PRIN,PAD_INS.POSITIONSEQ,PAD_INS.PARTICIPANTSEQ,
                PAD_INS.POS_PRIN,PAD_INS.POS_CALLIDUS,PAD_INS.POSITIONNAME
            ;
                    
        filas := sql%rowcount;            
        COMMIT;           
            
        w_debug('Fin Carga INYC_PROD_E_AGENTES: '|| to_char(filas) || ' filas.', v_contador);
        
        
        w_debug('Inicio Actualizacion Indices INYC_PROD_E_AGENTES.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PROD_E_AGENTES COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PROD_E_AGENTES');

        w_debug('Fin actualizacion Indices INYC_PROD_E_AGENTES.', v_contador);
        
        
        w_debug('Inicio actualizacion del parametro INYC_PROD_E_AGENTES',v_contador);
    
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_PROD_E_AGENTES');
    
        w_debug('Fin actualizacion del parametro INYC_PROD_E_AGENTES',v_contador);
        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;
        
    END IF;
    -------------------------------------------------------------------------------------------------------------------------------------
    --TABLAS DE INFORMES SOBRE CaLCULOS PROPIOS
    --ALM 20151027: Tabla para el Detalle de Polizas y Productos del S4 de OCASO
    IF informe = 'S4' OR informe LIKE '%,S4,%' OR informe LIKE '%,S4' OR informe LIKE 'S4,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_S4_POLIZAS.', v_contador);

            DELETE INYCEXT.INYC_S4_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S4_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S4_POLIZAS. Creditos (Nueva Produccion)', v_contador);
            
            INSERT INTO INYCEXT.INYC_S4_POLIZAS 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    ST.CHANNEL AS COMPANIA,
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                    --ALM 20170719: Para los nuevos creditos del Corte Ingles (SECI) no contamos polizas
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                    --CASE WHEN C.NAME <> 'DC-O-COM-NuevaProduccion-SECI' AND ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CASE WHEN C.NAME <> 'DC-O-COM-NuevaProduccion-SECI' AND ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                    CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                        ELSE 4
                    END AS NIVEL_PTO_VENTA,
                    PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                    PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        ELSE 3
                    END AS NIVEL_OFICINA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        ELSE 2
                    END AS NIVEL_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    1 AS NIVEL_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    C.GENERICNUMBER1 AS ASEGURADOS,
                    --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                    ST.GENERICATTRIBUTE7 AS COD_RECIBO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    AND C.NAME LIKE 'DC-O-COM-NuevaProduccion%'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                --ALM 20161221: Al tener TXN de mas de 3 meses no podemos unir con este tipo de tablas directamente porque hacen que el proceso se eternice.
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 100.2 
                --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                    --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                    --AND ST.PRODUCTID like '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA    
                ;
                    
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Carga INYC_S4_POLIZAS. Creditos (Nueva Produccion): '|| to_char(filas) || ' filas.', v_contador);

            w_debug('Inicio Carga INYC_S4_POLIZAS. Creditos (Asistencias)', v_contador);
            
            INSERT INTO INYCEXT.INYC_S4_POLIZAS 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    ST.CHANNEL AS COMPANIA,
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                    --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                    CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                        ELSE 4
                    END AS NIVEL_PTO_VENTA,
                    PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                    PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        ELSE 3
                    END AS NIVEL_OFICINA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        ELSE 2
                    END AS NIVEL_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    1 AS NIVEL_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    C.GENERICNUMBER1 AS ASEGURADOS,
                    --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                    ST.GENERICATTRIBUTE7 AS COD_RECIBO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    --ALM 20230316: Los nuevos creditos de asistencia llevan el numerico correspondiente al final, pero sigue existiendo el generico y no hya que cogerlo.
                    --AND C.NAME = 'DC-O-COM-ServiciosAsistencia-Importe'
                    AND C.NAME LIKE 'DC-O-COM-ServiciosAsistencia-Importe%'
                    AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                    --ALM 20170329: Filtramos para quedarnos con creditos de Ocaso igual que hacemos en Eterna
                    AND C.GENERICATTRIBUTE9 = '01'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 100.2
                --ALM 20160907: Para las Asistencias filtramos para agentes segun su PLAN
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.PARTICIPANTSEQ = PAD_AG.PARTICIPANTSEQ 
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = PAD_AG.POSITIONSEQ
                    AND PAD_AG.PLANNAME LIKE 'Plan_O_%'
                --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                    --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                    --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                    --AND ST.PRODUCTID LIKE '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA    
                ;
                    
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Carga INYC_S4_POLIZAS. Creditos (Asistencias): '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_S4_POLIZAS. Creditos (Resto Creditos)', v_contador);
            
            INSERT INTO INYCEXT.INYC_S4_POLIZAS 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    ST.CHANNEL AS COMPANIA,
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                    --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                    CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                        ELSE 4
                    END AS NIVEL_PTO_VENTA,
                    PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                    PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        ELSE 3
                    END AS NIVEL_OFICINA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        ELSE 2
                    END AS NIVEL_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    1 AS NIVEL_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    --ALM 20220530: Los creditos de las Gestiones traen en el GN1 el objetivo por lo que ponemos este valor a 0.
                    --C.GENERICNUMBER1 AS ASEGURADOS
                    (CASE WHEN C.NAME = 'DC-O-COM-GestionExplotacion' THEN 0 ELSE C.GENERICNUMBER1 END) AS ASEGURADOS,
                    --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                    ST.GENERICATTRIBUTE7 AS COD_RECIBO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    --ALM 20230316: Los nuevos creditos de asistencia llevan el numerico correspondiente al final, pero sigue existiendo el generico y no hya que cogerlo.
                    --AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                    AND C.NAME NOT LIKE 'DC-O-COM-ServiciosAsistencia-Importe%'
                    AND C.NAME NOT LIKE 'DC-O-COM-NuevaProduccion%'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 100.2 
                --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                    --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                    --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                    --AND ST.PRODUCTID like '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA      
                ;              
                    
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Carga INYC_S4_POLIZAS. Creditos (Resto Creditos): '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_S4_POLIZAS. Pagos Comerciales 1** y 2**.', v_contador);
                    
            INSERT INTO INYCEXT.INYC_S4_POLIZAS               
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                    --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                    SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                    '999999900000000' AS POLIZA,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                    D.DEPOSITDATE AS FEC_CARGO,
                    0 AS PRIMA_COMISIONABLE,
                    --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                    --              depende del concepto de pago.
                    --(SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                    CASE WHEN SUBSTR(D.EARNINGCODEID,1,3) = '101' THEN 'Comision Produccion' 
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '102' THEN 'Comision Cartera'
                        --ALM 20180420: Anadimos los pagos comerciales de concepto 107 a las recuperaciones por peticion de Miguel Angel Arrabe
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('107') THEN 'Recuperacion'
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '109' THEN 'Domiciliacion'
                        --ALM 20170330: Anadimos los pagos comerciales de concepto 150 a las tramitaciones por peticion de Javier
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('150','153') THEN 'Tramitacion'
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '201' THEN 'Regularizacion'
                        ELSE 'Division Comercial'
                    END AS EVENTO,
                    PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                    '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                        ELSE 4
                    END AS NIVEL_PTO_VENTA,
                    PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                    PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        ELSE 3
                    END AS NIVEL_OFICINA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        ELSE 2
                    END AS NIVEL_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    1 AS NIVEL_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    0 AS ASEGURADOS,
                    --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                    '' AS COD_RECIBO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND D.TENANTID = 'INYC'
                    --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S4% (ej: 04-S4-03)
                    AND D.EARNINGGROUPID LIKE '%S4%'
                    --ALM 20160907: Solo nos quedamos con los conceptos de pago 100 y 200, el resto no deben aparecer en el detalle del S4
                    --              Correo de Afonso el 06/09/2016
                    AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                --ALM 20180822: Nos quedamos con las 15 primeras letras del nombre del deposito para tener en cuenta los depositos antiguos de Abril y Mayo
                --              de 2016 que pueden venir con diferentes nombre (D-O-Pagos-Fijos-x)    
                --INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME, = REG.REGLA
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON SUBSTR(D.NAME,1,15) = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 100.2 
                --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                --INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                --ALM 20160822: Como existen pagos comerciales antiguos en los que el producto venia informado en el GA1 del deposito cambiamos la join
                --              Necesario para Pagos Comerciales de Abril y Mayo 2016
                INNER JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END
                    AND CL.REMOVEDATE = v_eot  
                    AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND CL.TENANTID = 'INYC'
                LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                    AND PROD.REMOVEDATE = v_eot  
                    AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND PROD.TENANTID = 'INYC'
                --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                    --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                    --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                    --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '01';    
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S4_POLIZAS. Pagos Comerciales 1** y 2**: '|| to_char(filas) || ' filas.', v_contador);
            
            --LLS 20220124: Caso espec�fico del dep�sito D-O-GestionExplotacion-PagoInicial (regla D-O-COM-GestionExplotacion-PagoInicial) de Enero 2022
            
            w_debug('Inicio Carga INYC_S4_POLIZAS. Pago Inicial Gestion Explotacion.', v_contador);
                    
            INSERT INTO INYCEXT.INYC_S4_POLIZAS               
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                    SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                    '999999900000000' AS POLIZA,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                    D.DEPOSITDATE AS FEC_CARGO,
                    0 AS PRIMA_COMISIONABLE,
                    'Gestiones referencias explotacion' AS EVENTO,
                    PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                    '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                        ELSE 4
                    END AS NIVEL_PTO_VENTA,
                    PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                    PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        ELSE 3
                    END AS NIVEL_OFICINA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        ELSE 2
                    END AS NIVEL_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    1 AS NIVEL_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    PAD_INS.SUPERRAPEL,
                    0 AS ASEGURADOS,
                    --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                    '' AS COD_RECIBO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND D.TENANTID = 'INYC'
                    AND D.EARNINGGROUPID LIKE '%S4%'
                    AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                    AND D.NAME = 'D-O-GestionExplotacion-PagoInicial'
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 100.2 
                LEFT JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END
                    AND CL.REMOVEDATE = v_eot  
                    AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND CL.TENANTID = 'INYC'
                LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                    AND PROD.REMOVEDATE = v_eot  
                    AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND PROD.TENANTID = 'INYC'
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Carga INYC_S4_POLIZAS. Pago Inicial Gestion Explotacion: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_S4_POLIZAS. AGENTES DERECHOS ECONOMICOS.', v_contador);
                
            INSERT INTO INYCEXT.INYC_S4_POLIZAS        
                 SELECT 
                    PAD_INS.PARTICIPANTSEQ, 
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.POSITIONNAME,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR (CAR_LP.ORDERID,1,2) AS COMPANIA, --order id 2 primeros digitos
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    'CARTERA_LP' AS NAME, --C.NAME,
                    CAR_LP.IMPORTE AS VALUE, --C.VALUE,
                    0 AS POLIZ_CORR,
                    0 AS POLIZ_NP,
                    CAR_LP.ORDERID || CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    CAR_LP.POLIZA, --ST.GENERICATTRIBUTE1 AS POLIZA,
                    CAR_LP.PRODUCTID,
                    CAR_LP.ACCOUNTINGDATE AS FEC_CARGO,
                    CAR_LP.VALUE AS PRIMA_COMISIONABLE,
                    CAR_LP.EVENTO,--ST.EVENTO,
                    CAR_LP.PRODUCTO,--ST.PRODUCTO,
                    CAR_LP.FEC_VTO_REC,--ST.FEC_VTO_REC,
                    CAR_LP.PRIMA_NETA,--ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_INS.TIPO_AGENTE,
                    CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                        ELSE 4
                    END AS NIVEL_PTO_VENTA,
                    PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                    PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                        ELSE 3
                    END AS NIVEL_OFICINA,
                    CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                        ELSE 2
                    END AS NIVEL_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    1 AS NIVEL_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    PAD_INS.SUPERRAPEL,
                    0 AS ASEGURADOS,
                    --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                    '' AS COD_RECIBO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                    --LLS 20220125: Filtro para tener solo Ocaso
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                    --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                    --ATV 20250205 Anyadimos el estado N
                    --AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                    AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO IN ('C', 'N')))
                    --ALM 20220603: No incluimos registros sin importe de comision.
                    AND CAR_LP.IMPORTE <> 0
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                --dejamos estos left join para tener los datos de las oficinas
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                WHERE Y.POSITIONSEQ IS NULL
                 ;
                                            
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Carga INYC_S4_POLIZAS. AGENTES DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
            
            --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
            --END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_S4_POLIZAS.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S4_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S4_POLIZAS');

            w_debug('Fin Actualizacion Indices INYC_S4_POLIZAS.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_S4',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S4');
                   
            w_debug('Fin actualizacion del parametro INYC_S4',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
                w_debug('Inicio Borrado INYC_LC_S4_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_LC_S4_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S4_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S4_POLIZAS. Creditos (Nueva Produccion)', v_contador);
                
                INSERT INTO INYCEXT.INYC_LC_S4_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        ST.CHANNEL AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170719: Para los nuevos creditos del Corte Ingles (SECI) no contamos polizas
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN C.NAME <> 'DC-O-COM-NuevaProduccion-SECI' AND ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN C.NAME <> 'DC-O-COM-NuevaProduccion-SECI' AND ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        ST.GENERICATTRIBUTE7 AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        AND C.NAME LIKE 'DC-O-COM-NuevaProduccion%'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    --ALM 20161221: Al tener TXN de mas de 3 meses no podemos unir con este tipo de tablas directamente porque hacen que el proceso se eternice.
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA    
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Carga INYC_LC_S4_POLIZAS. Creditos (Nueva Produccion): '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_LC_S4_POLIZAS. Creditos (Asistencias)', v_contador);
                
                INSERT INTO INYCEXT.INYC_LC_S4_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        ST.CHANNEL AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        ST.GENERICATTRIBUTE7 AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        --ALM 20230316: Los nuevos creditos de asistencia llevan el numerico correspondiente al final, pero sigue existiendo el generico y no hya que cogerlo.
                        --AND C.NAME = 'DC-O-COM-ServiciosAsistencia-Importe'
                        AND C.NAME LIKE 'DC-O-COM-ServiciosAsistencia-Importe%'
                        AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                        --ALM 20170329: Filtramos para quedarnos con creditos de Ocaso igual que hacemos en Eterna
                        AND C.GENERICATTRIBUTE9 = '01'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2
                    --ALM 20160907: Para las Asistencias filtramos para agentes segun su PLAN
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.PARTICIPANTSEQ = PAD_AG.PARTICIPANTSEQ 
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = PAD_AG.POSITIONSEQ
                        AND PAD_AG.PLANNAME LIKE 'Plan_O_%'
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID LIKE '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA    
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Carga INYC_LC_S4_POLIZAS. Creditos (Asistencias): '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_S4_POLIZAS. Creditos (Resto Creditos)', v_contador);
                
                INSERT INTO INYCEXT.INYC_LC_S4_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        ST.CHANNEL AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        --ALM 20220530: Los creditos de las Gestiones traen en el GN1 el objetivo por lo que ponemos este valor a 0.
                        --C.GENERICNUMBER1 AS ASEGURADOS
                        (CASE WHEN C.NAME = 'DC-O-COM-GestionExplotacion' THEN 0 ELSE C.GENERICNUMBER1 END) AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        ST.GENERICATTRIBUTE7 AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        --ALM 20230316: Los nuevos creditos de asistencia llevan el numerico correspondiente al final, pero sigue existiendo el generico y no hya que cogerlo.
                        --AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                        AND C.NAME NOT LIKE 'DC-O-COM-ServiciosAsistencia-Importe%'
                        AND C.NAME NOT LIKE 'DC-O-COM-NuevaProduccion%'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA      
                    ;              
                        
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Carga INYC_LC_S4_POLIZAS. Creditos (Resto Creditos): '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_S4_POLIZAS. Pagos Comerciales 1** y 2**.', v_contador);
                        
                INSERT INTO INYCEXT.INYC_LC_S4_POLIZAS               
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,
                        0 AS PRIMA_COMISIONABLE,
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --(SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,3) = '101' THEN 'Comision Produccion' 
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '102' THEN 'Comision Cartera'
                            --ALM 20180420: Anadimos los pagos comerciales de concepto 107 a las recuperaciones por peticion de Miguel Angel Arrabe
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('107') THEN 'Recuperacion'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '109' THEN 'Domiciliacion'
                            --ALM 20170330: Anadimos los pagos comerciales de concepto 150 a las tramitaciones por peticion de Javier
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('150','153') THEN 'Tramitacion'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '201' THEN 'Regularizacion'
                            ELSE 'Division Comercial'
                        END AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        '' AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S4% (ej: 04-S4-03)
                        AND D.EARNINGGROUPID LIKE '%S4%'
                        --ALM 20160907: Solo nos quedamos con los conceptos de pago 100 y 200, el resto no deben aparecer en el detalle del S4
                        --              Correo de Afonso el 06/09/2016
                        AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20180822: Nos quedamos con las 15 primeras letras del nombre del deposito para tener en cuenta los depositos antiguos de Abril y Mayo
                    --              de 2016 que pueden venir con diferentes nombre (D-O-Pagos-Fijos-x)    
                    --INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME, = REG.REGLA
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON SUBSTR(D.NAME,1,15) = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                    --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                    --INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                    --ALM 20160822: Como existen pagos comerciales antiguos en los que el producto venia informado en el GA1 del deposito cambiamos la join
                    --              Necesario para Pagos Comerciales de Abril y Mayo 2016
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '01';    
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                
                w_debug('Fin Carga INYC_LC_S4_POLIZAS. Pagos Comerciales 1** y 2**: '|| to_char(filas) || ' filas.', v_contador);
        
                --LLS 20220124: Caso espec�fico del dep�sito D-O-GestionExplotacion-PagoInicial (regla D-O-COM-GestionExplotacion-PagoInicial) de Enero 2022

                w_debug('Inicio Carga INYC_LC_S4_POLIZAS. Pago Inicial Gestion Explotacion.', v_contador);
                        
                INSERT INTO INYCEXT.INYC_LC_S4_POLIZAS               
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,
                        0 AS PRIMA_COMISIONABLE,
                        'Gestiones referencias explotacion' AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        '' AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        AND D.EARNINGGROUPID LIKE '%S4%'
                        AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                        AND D.NAME = 'D-O-GestionExplotacion-PagoInicial'
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    LEFT JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                
                w_debug('Fin Carga INYC_LC_S4_POLIZAS. Pago Inicial Gestion Explotacion: '|| to_char(filas) || ' filas.', v_contador);        
         
                w_debug('Inicio Carga INYC_LC_S4_POLIZAS. AGENTES DERECHOS ECONOMICOS.', v_contador);
                    
                INSERT INTO INYCEXT.INYC_LC_S4_POLIZAS        
                     SELECT 
                        PAD_INS.PARTICIPANTSEQ, 
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.POSITIONNAME,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR (CAR_LP.ORDERID,1,2) AS COMPANIA, /*order id 2 primeros digitos*/
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        'CARTERA_LP' AS NAME, --C.NAME,
                        CAR_LP.IMPORTE AS VALUE, --C.VALUE,
                        0 as POLIZ_CORR,
                        0 as POLIZ_NP,
                        CAR_LP.ORDERID ||CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        CAR_LP.POLIZA, --ST.GENERICATTRIBUTE1 AS POLIZA,
                        CAR_LP.PRODUCTID,
                        CAR_LP.ACCOUNTINGDATE AS FEC_CARGO,
                        CAR_LP.VALUE AS PRIMA_COMISIONABLE,
                        CAR_LP.EVENTO,--ST.EVENTO,
                        CAR_LP.PRODUCTO,--ST.PRODUCTO,
                        CAR_LP.FEC_VTO_REC,--ST.FEC_VTO_REC,
                        CAR_LP.PRIMA_NETA,--ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        '' AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        --LLS 20220125: Filtro para tener solo Ocaso
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        --ATV 20250205 Anyadimos el estado N
                        --AND CAR_LP.ESTADO = 'C'
                        AND CAR_LP.ESTADO IN ('C', 'N')
                        --ALM 20220603: No incluimos registros sin importe de comision.
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    /** dejamos estos left join para tener los datos de las oficinas **/
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                     ;
                                                
                filas := sql%rowcount;            
                COMMIT;
                    
                w_debug('Fin Carga INYC_LC_S4_POLIZAS. AGENTES DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S4_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S4_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S4_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_LC_S4_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_S4',v_contador);
                
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S4');
                       
                w_debug('Fin actualizacion del parametro INYC_LC_S4',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
                w_debug('Inicio Borrado INYC_BAL_S4_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_BAL_S4_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_S4_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_S4_POLIZAS. Creditos (Nueva Produccion)', v_contador);
                
                INSERT INTO INYCEXT.INYC_BAL_S4_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        ST.CHANNEL AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170719: Para los nuevos creditos del Corte Ingles (SECI) no contamos polizas
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN C.NAME <> 'DC-O-COM-NuevaProduccion-SECI' AND ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN C.NAME <> 'DC-O-COM-NuevaProduccion-SECI' AND ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        ST.GENERICATTRIBUTE7 AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        AND C.NAME LIKE 'DC-O-COM-NuevaProduccion%'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    --ALM 20161221: Al tener TXN de mas de 3 meses no podemos unir con este tipo de tablas directamente porque hacen que el proceso se eternice.
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA    
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Carga INYC_BAL_S4_POLIZAS. Creditos (Nueva Produccion): '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_BAL_S4_POLIZAS. Creditos (Asistencias)', v_contador);
                
                INSERT INTO INYCEXT.INYC_BAL_S4_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        ST.CHANNEL AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        ST.GENERICATTRIBUTE7 AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        --ALM 20230316: Los nuevos creditos de asistencia llevan el numerico correspondiente al final, pero sigue existiendo el generico y no haya que cogerlo.
                        --AND C.NAME = 'DC-O-COM-ServiciosAsistencia-Importe'
                        AND C.NAME LIKE 'DC-O-COM-ServiciosAsistencia-Importe%'
                        AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                        --ALM 20170329: Filtramos para quedarnos con creditos de Ocaso igual que hacemos en Eterna
                        AND C.GENERICATTRIBUTE9 = '01'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2
                    --ALM 20160907: Para las Asistencias filtramos para agentes segun su PLAN
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.PARTICIPANTSEQ = PAD_AG.PARTICIPANTSEQ 
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = PAD_AG.POSITIONSEQ
                        AND PAD_AG.PLANNAME LIKE 'Plan_O_%'
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID LIKE '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA    
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Carga INYC_BAL_S4_POLIZAS. Creditos (Asistencias): '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_BAL_S4_POLIZAS. Creditos (Resto Creditos)', v_contador);
                
                INSERT INTO INYCEXT.INYC_BAL_S4_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        ST.CHANNEL AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        --ALM 20220530: Los creditos de las Gestiones traen en el GN1 el objetivo por lo que ponemos este valor a 0.
                        --C.GENERICNUMBER1 AS ASEGURADOS
                        (CASE WHEN C.NAME = 'DC-O-COM-GestionExplotacion' THEN 0 ELSE C.GENERICNUMBER1 END) AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        ST.GENERICATTRIBUTE7 AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        --ALM 20230316: Los nuevos creditos de asistencia llevan el numerico correspondiente al final, pero sigue existiendo el generico y no haya que cogerlo.
                        --AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                        AND C.NAME NOT LIKE 'DC-O-COM-ServiciosAsistencia-Importe%'
                        AND C.NAME NOT LIKE 'DC-O-COM-NuevaProduccion%'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '01%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA      
                    ;              
                        
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Carga INYC_BAL_S4_POLIZAS. Creditos (Resto Creditos): '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_BAL_S4_POLIZAS. Pagos Comerciales 1** y 2**.', v_contador);
                        
                INSERT INTO INYCEXT.INYC_BAL_S4_POLIZAS               
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,
                        0 AS PRIMA_COMISIONABLE,
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --(SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,3) = '101' THEN 'Comision Produccion' 
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '102' THEN 'Comision Cartera'
                            --ALM 20180420: Anadimos los pagos comerciales de concepto 107 a las recuperaciones por peticion de Miguel Angel Arrabe
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('107') THEN 'Recuperacion'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '109' THEN 'Domiciliacion'
                            --ALM 20170330: Anadimos los pagos comerciales de concepto 150 a las tramitaciones por peticion de Javier
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('150','153') THEN 'Tramitacion'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '201' THEN 'Regularizacion'
                            ELSE 'Division Comercial'
                        END AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        '' AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S4% (ej: 04-S4-03)
                        AND D.EARNINGGROUPID LIKE '%S4%'
                        --ALM 20160907: Solo nos quedamos con los conceptos de pago 100 y 200, el resto no deben aparecer en el detalle del S4
                        --              Correo de Afonso el 06/09/2016
                        AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20180822: Nos quedamos con las 15 primeras letras del nombre del deposito para tener en cuenta los depositos antiguos de Abril y Mayo
                    --              de 2016 que pueden venir con diferentes nombre (D-O-Pagos-Fijos-x)    
                    --INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME, = REG.REGLA
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON SUBSTR(D.NAME,1,15) = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                    --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                    --INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                    --ALM 20160822: Como existen pagos comerciales antiguos en los que el producto venia informado en el GA1 del deposito cambiamos la join
                    --              Necesario para Pagos Comerciales de Abril y Mayo 2016
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ;
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '01';    
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S4_POLIZAS. Pagos Comerciales 1** y 2**: '|| to_char(filas) || ' filas.', v_contador);
        
                --LLS 20220124: Caso espec�fico del dep�sito D-O-GestionExplotacion-PagoInicial (regla D-O-COM-GestionExplotacion-PagoInicial) de Enero 2022

                w_debug('Inicio Carga INYC_BAL_S4_POLIZAS. Pago Inicial Gestion Explotacion.', v_contador);
                        
                INSERT INTO INYCEXT.INYC_BAL_S4_POLIZAS               
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,
                        0 AS PRIMA_COMISIONABLE,
                        'Gestiones referencias explotacion' AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        '' AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        AND D.EARNINGGROUPID LIKE '%S4%'
                        AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                        AND D.NAME = 'D-O-GestionExplotacion-PagoInicial'
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 100.2 
                    LEFT JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ    
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S4_POLIZAS. Pago Inicial Gestion Explotacion: '|| to_char(filas) || ' filas.', v_contador);
 
                w_debug('Inicio Carga INYC_BAL_S4_POLIZAS. AGENTES DERECHOS ECONOMICOS.', v_contador);
                    
                INSERT INTO INYCEXT.INYC_BAL_S4_POLIZAS        
                     SELECT 
                        PAD_INS.PARTICIPANTSEQ, 
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.POSITIONNAME,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR (CAR_LP.ORDERID,1,2) AS COMPANIA, /*order id 2 primeros digitos*/
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        'CARTERA_LP' AS NAME, --C.NAME,
                        CAR_LP.IMPORTE AS VALUE, --C.VALUE,
                        0 AS POLIZ_CORR,
                        0 AS POLIZ_NP,
                        CAR_LP.ORDERID ||CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        CAR_LP.POLIZA, --ST.GENERICATTRIBUTE1 AS POLIZA,
                        CAR_LP.PRODUCTID,
                        CAR_LP.ACCOUNTINGDATE AS FEC_CARGO,
                        CAR_LP.VALUE AS PRIMA_COMISIONABLE,
                        CAR_LP.EVENTO,--ST.EVENTO,
                        CAR_LP.PRODUCTO,--ST.PRODUCTO,
                        CAR_LP.FEC_VTO_REC,--ST.FEC_VTO_REC,
                        CAR_LP.PRIMA_NETA,--ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS,
                        --ATV 20221124: Anyadimos campo a incluir para el informe s4 Corredores
                        '' AS COD_RECIBO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        --LLS 20220125: Filtro para tener solo Ocaso
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        --ATV 20250205 Anyadimos el estado N
                        --AND CAR_LP.ESTADO = 'C'
                        AND CAR_LP.ESTADO IN ('C', 'N')
                        --ALM 20220603: No incluimos registros sin importe de comision.
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    /** dejamos estos left join para tener los datos de las oficinas **/
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                     ;
                                                
                filas := sql%rowcount;            
                COMMIT;
                    
                w_debug('Fin Carga INYC_BAL_S4_POLIZAS. AGENTES DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_S4_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_S4_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_S4_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_BAL_S4_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_S4',v_contador);
                
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_S4');
                       
                w_debug('Fin actualizacion del parametro INYC_BAL_S4',v_contador);
        
            END IF;
            
        END IF;        
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;    
    
    --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5
    
    --ALM 20151027: Tabla para la FACTURA del S4 y S5 de OCASO
    --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
    
    IF informe = 'FAC_S4' OR informe LIKE '%,FAC_S4,%' OR informe LIKE '%,FAC_S4' OR informe LIKE 'FAC_S4,%' 
        
        OR informe = 'FAC_S5' OR informe LIKE '%,FAC_S5,%' OR informe LIKE '%,FAC_S5' OR informe LIKE 'FAC_S5,%'
                
        OR informe = 'ALL'
        
    THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN

            --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Inicio borrado y carga de INYC_S4_FACTURA 
            
            w_debug('Inicio Borrado INYC_S4_FACTURA.', v_contador);

            DELETE INYCEXT.INYC_S4_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S4_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S4_FACTURA.', v_contador);
            
            INSERT INTO INYCEXT.INYC_S4_FACTURA 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END AS IRPF,   
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                    EC.DESCRIPTION AS COMISION,
                    SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                    SUM(PAY.VALUE) AS IMPORTE,
                    NULL AS SECUENCIAL,
                    --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                    PAD_INS.NUMERO,
                    PAD_INS.RESTO_DOMICILIO
                --ALM 20160216: Nos quedamos solo con los agentes que tienen recibos de Comisiones
                --              NO ESTAN INCLUIDOS LOS POSIBLES AGENTES QUE SOLO TENGAN PAGOS ESPECIALES
                --FROM (SELECT DISTINCT X.* FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                --    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP Y ON X.PARTICIPANTSEQ = Y.PAYEESEQ 
                --        AND X.PERIODSEQ = Y.PERIODSEQ
                --        AND X.POSITIONSEQ = Y.POSITIONSEQ
                --        AND Y.VALUE <> 0
                --    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS Z ON Y.NAME = Z.REGLA
                --        AND Z.F_INICIO <= X.STARTDATE AND  Z.F_FIN > X.STARTDATE
                --        AND Z.COD_INFORME = 100.2
                --) PAD_INS
                --ALM 20160908: Incluimos agentes que solo tengan pagos comerciales
                --              Para filtrar hacemos un inner a los pagos
                --              NO SALDRaN AGENTES CON COMISONES QUE SE ANULEN ENTRE Si
                --FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                --ALM 20160909: Unimos la tabla de agentes por la posicion principal con los pagos haciendo un distinct para que no salgan lineas duplicadas
                --              debidas al resto de posiciones que aparecen en la tabla arbol.
                --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                FROM (SELECT DISTINCT  
                        X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                        X.CUADRO_RRGG_OCASO,X.CUADRO_RRTT_OCASO,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID,X.NUMERO,X.RESTO_DOMICILIO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND X.PERIODSEQ = Y.PERIODSEQ 
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                ) PAD_INS
                --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                    THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME
                --ALM 20160908: Solo cogemos agentes con pagos
                --              Unimos por la Position Principal porque los pagos solo llegaran a las Posiciones Principales
                INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ_PRIN = PAY.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                    AND PAY.TENANTID = 'INYC'
                    --ALM 20160216: Aplicamos los filtros de Compania y Tipo de Informe dentro de la tabla de Pagos
                    --              para que les salga Factura a los agentes sin Pagos, pero si con recibos de Comisiones
                    AND SUBSTR(PAY.EARNINGGROUPID,7,2) = '01'
                    AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S4'
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot 
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)    
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,PAD_INS.POS_PRIN,PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(PAY.EARNINGGROUPID,7,2),
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907: Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END,   
                    PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2),
                    --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S4_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Carga INYC_S4_FACTURA. AGENTES DERECHOS ECONOMICOS.', v_contador);
                
            INSERT INTO INYCEXT.INYC_S4_FACTURA
                    
                SELECT
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.MUNICIPIO,
                    PAD_INS.DOMICILIO,
                    PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(CAR_LP.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                         WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0
                    END AS IRPF,
                    --LLS 20220127: codigo de oficina correcto
                    --CAR_LP.POSITIONNAME AS COD_OFICINA,
                    --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                    --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                    --SUBSTR(CAR_LP.COD_AGENTE, 1, 4) AS COD_OFICINA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,
                    PAD_OF.LASTNAME AS OFICINA,
                    EC.DESCRIPTION AS COMISION,
                    SUBSTR(CAR_LP.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                    sum(CAR_LP.importe) as importe, --SUM(PAY.VALUE) AS IMPORTE
                    NULL AS SECUENCIAL,
                    --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                    PAD_INS.NUMERO,
                    PAD_INS.RESTO_DOMICILIO
                FROM (SELECT DISTINCT
                       x.startdate, x.pos_callidus, /* variables a�adidas, daba error al no encontrarlas */
                       X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                        X.CUADRO_RRGG_OCASO,X.CUADRO_RRTT_OCASO,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID,X.NUMERO,X.RESTO_DOMICILIO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND X.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    WHERE Y.POSITIONSEQ IS NULL
                ) PAD_INS
                INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                    --LLS 20220125: Filtro para tener solo Ocaso
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                    --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                    --ATV 20250205 Anyadimos el estado N
                    --ATV 20250313 Quitamos el estado N
                    AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                    --AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO IN ('C', 'N')))
                    --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                    AND CAR_LP.IMPORTE <> 0
                --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                    THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(CAR_LP.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                GROUP BY
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                    PAD_INS.MUNICIPIO,
                    PAD_INS.DOMICILIO,
                    PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(CAR_LP.EARNINGGROUPID,7,2),
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                         WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0
                    END,
                    --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                    --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                    --SUBSTR(CAR_LP.COD_AGENTE, 1, 4),
                    PAD_OF.POSITIONNAME,
                    PAD_OF.LASTNAME,
                    EC.DESCRIPTION,
                    SUBSTR(CAR_LP.EARNINGGROUPID,4,2),
                    --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                --ATV 20250321 Modificamos para evitar facturas a 0
                HAVING SUM(CAR_LP.importe) <> 0
            ;
                
            filas := sql%rowcount;
            COMMIT;
                
            w_debug('Fin Carga INYC_S4_FACTURA. AGENTES DERECHOS ECONOMICOS:'|| to_char(filas) || ' filas.', v_contador);
                
            --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
            --END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_S4_FACTURA.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S4_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S4_FACTURA');

            w_debug('Fin Actualizacion Indices INYC_S4_FACTURA.', v_contador);

            --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Fin borrado y carga de INYC_S4_FACTURA 
            
            --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Inicio borrado y carga de INYC_S5_FACTURA             

            w_debug('Inicio Borrado INYC_S5_FACTURA.', v_contador);

            DELETE INYCEXT.INYC_S5_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S5_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S5_FACTURA.', v_contador);

            INSERT INTO INYCEXT.INYC_S5_FACTURA 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_OCASO,
                    SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                    --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                    --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                    THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END AS IRPF,   
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                    EC.DESCRIPTION AS COMISION,
                    SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                    SUM(PAY.VALUE) AS IMPORTE,
                    NULL AS SECUENCIAL,
                    --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                    PAD_INS.NUMERO,
                    PAD_INS.RESTO_DOMICILIO
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                    THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME   
                INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ = PAY.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                    AND PAY.TENANTID = 'INYC'
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --ALM 20170427: Quitamos el filtrado por tipologias de agente, para que se devuelva siempre que haya pagos
                --              Los balances no aparecen sino a agentes con cambios de tipologia
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --    AND AG.COD_INFORME = 101
                WHERE SUBSTR(PAY.EARNINGGROUPID,7,2) = '01'
                    AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S5'
                    --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_OCASO,
                    SUBSTR(PAY.EARNINGGROUPID,7,2),
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                    --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                    --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                    THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END,   
                    PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2)
                ;
                
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S5_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_S5_FACTURA.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S5_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S5_FACTURA');

            w_debug('Fin Actualizacion Indices INYC_S5_FACTURA.', v_contador);
            
            --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Fin borrado y carga de INYC_S5_FACTURA             
                        
            --LLS 20211215: Petici�n PAC 2022, campo SECUENCIAL INYC_S4_FACTURA
            
            w_debug('Inicio Update campo SECUENCIAL INYC_S4_FACTURA.', v_contador);
            
            UPDATE INYCEXT.INYC_S4_FACTURA F
            SET SECUENCIAL = 1 +
                ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S4_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S4_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S5_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S5_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                    ) Y )
                WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
            
            COMMIT;
            
            w_debug('Fin Update campo SECUENCIAL INYC_S4_FACTURA.', v_contador);                                                                                                                                                                                                                                               
            --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
            --w_debug('Inicio actualizacion del parametro INYC_S4',v_contador);
            w_debug('Inicio actualizacion del parametro INYC_S4_FAC',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI    
            update_table(mes,'INYC_S4_FAC');
            
            --w_debug('Fin actualizacion del parametro INYC_S4',v_contador);
            w_debug('Fin actualizacion del parametro INYC_S4_FAC',v_contador);

            --LLS 20211215: Petici�n PAC 2022, campo SECUENCIAL INYC_S5_FACTURA
            
            w_debug('Inicio Update campo SECUENCIAL INYC_S5_FACTURA.', v_contador);
            
            UPDATE INYCEXT.INYC_S5_FACTURA F
            SET SECUENCIAL = 1 +
                ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S4_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S4_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S5_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S5_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                    ) Y )
                WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
            
            COMMIT;
            
            w_debug('Fin Update campo SECUENCIAL INYC_S5_FACTURA.', v_contador);
            
            --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
            --w_debug('Inicio actualizacion del parametro INYC_S5',v_contador);
            w_debug('Inicio actualizacion del parametro INYC_S5_FAC',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S5_FAC');
            
            --w_debug('Fin actualizacion del parametro INYC_S5',v_contador);
            w_debug('Fin actualizacion del parametro INYC_S5_FAC',v_contador);
                        
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria            
            IF v_periodo_finalizado = 0 THEN
            
                --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Inicio borrado y carga de INYC_LC_S4_FACTURA                         
            
                w_debug('Inicio Borrado INYC_LC_S4_FACTURA.', v_contador);

                DELETE INYCEXT.INYC_LC_S4_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S4_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S4_FACTURA.', v_contador);
                
                INSERT INTO INYCEXT.INYC_LC_S4_FACTURA 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                            AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                        THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                            -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                            --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                            --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0 
                        END AS IRPF,   
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                        EC.DESCRIPTION AS COMISION,
                        SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                        SUM(PAY.VALUE) AS IMPORTE,
                        NULL AS SECUENCIAL,
                        --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                    --ALM 20160216: Nos quedamos solo con los agentes que tienen recibos de Comisiones
                    --              NO ESTAN INCLUIDOS LOS POSIBLES AGENTES QUE SOLO TENGAN PAGOS ESPECIALES
                    --FROM (SELECT DISTINCT X.* FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                    --    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP Y ON X.PARTICIPANTSEQ = Y.PAYEESEQ 
                    --        AND X.PERIODSEQ = Y.PERIODSEQ
                    --        AND X.POSITIONSEQ = Y.POSITIONSEQ
                    --        AND Y.VALUE <> 0
                    --    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS Z ON Y.NAME = Z.REGLA
                    --        AND Z.F_INICIO <= X.STARTDATE AND  Z.F_FIN > X.STARTDATE
                    --        AND Z.COD_INFORME = 100.2
                    --) PAD_INS
                    --ALM 20160908: Incluimos agentes que solo tengan pagos comerciales
                    --              Para filtrar hacemos un inner a los pagos
                    --              NO SALDRaN AGENTES CON COMISONES QUE SE ANULEN ENTRE Si
                    --FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    --ALM 20160909: Unimos la tabla de agentes por la posicion principal con los pagos haciendo un distinct para que no salgan lineas duplicadas
                    --              debidas al resto de posiciones que aparecen en la tabla arbol.
                    --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                    FROM (SELECT DISTINCT  
                            X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                            X.CUADRO_RRGG_OCASO,X.CUADRO_RRTT_OCASO,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID,X.NUMERO,X.RESTO_DOMICILIO
                        FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                        INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                            AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                            AND X.PERIODSEQ = Y.PERIODSEQ 
                            AND Y.TENANTID = 'INYC'
                            AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                            AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                            --ALM 20171201: Filtramos para pagos sin postear, asi no cogemos los pagos del cierre
                            AND (Y.POSTPIPELINERUNSEQ IS NULL
                                --ALM 20190122: Anadimos un control para quedarnos con el ultimo Post en caso de que haya mas de uno
                                OR (v_periodo_posteado > 1
                                    AND Y.POSTPIPELINERUNSEQ = (SELECT MAX(PY.POSTPIPELINERUNSEQ) FROM INYCEXT.INYC_PAGOS_MES_TEMP PY)))
                    ) PAD_INS
                    --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                    --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                    INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                        THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME 
                    --ALM 20160908: Solo cogemos agentes con pagos
                    --              Unimos por la Position Principal porque los pagos solo llegaran a las Posiciones Principales
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ_PRIN = PAY.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                        AND PAY.TENANTID = 'INYC'
                        --ALM 20160216: Aplicamos los filtros de Compania y Tipo de Informe dentro de la tabla de Pagos
                        --              para que les salga Factura a los agentes sin Pagos, pero si con recibos de Comisiones
                        AND SUBSTR(PAY.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S4'
                        --ALM 20171201: Filtramos para pagos sin postear, asi no cogemos los pagos del cierre
                        AND (PAY.POSTPIPELINERUNSEQ IS NULL
                            --ALM 20190122: Anadimos un control para quedarnos con el ultimo Post en caso de que haya mas de uno
                            OR (v_periodo_posteado > 1
                                AND PAY.POSTPIPELINERUNSEQ = (SELECT MAX(PY.POSTPIPELINERUNSEQ) FROM INYCEXT.INYC_PAGOS_MES_TEMP PY)))
                    INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                        AND EC.TENANTID = 'INYC'
                        AND EC.REMOVEDATE = v_eot 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)    
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                        PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,PAD_INS.POS_PRIN,PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(PAY.EARNINGGROUPID,7,2),
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                            AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                        THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                            -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                            --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                            --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0 
                        END,   
                        PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2),
                        --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S4_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Carga INYC_LC_S4_FACTURA. AGENTES DERECHOS ECONOMICOS.', v_contador);
                    
                INSERT INTO INYCEXT.INYC_LC_S4_FACTURA
                        
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.MUNICIPIO,
                        PAD_INS.DOMICILIO,
                        PAD_INS.CP,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(CAR_LP.EARNINGGROUPID,7,2) AS COMPANIA,
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                            AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                        THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                             WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0
                        END AS IRPF,
                        --LLS 20220127: codigo de oficina correcto
                        --CAR_LP.POSITIONNAME AS COD_OFICINA,
                        --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                        --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                        --SUBSTR(CAR_LP.COD_AGENTE, 1, 4) AS COD_OFICINA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,
                        PAD_OF.LASTNAME AS OFICINA,
                        EC.DESCRIPTION AS COMISION,
                        SUBSTR(CAR_LP.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                        sum(CAR_LP.importe) as importe,--SUM(PAY.VALUE) AS IMPORTE
                        NULL AS SECUENCIAL,
                        --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                        --ATV 20250509 Anyadimos los campos numero y resto_domicilio a la factura.
                    FROM (SELECT DISTINCT
                           x.startdate, x.pos_callidus, /* variables a�adidas, daba error al no encontrarlas */
                           X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                            X.CUADRO_RRGG_OCASO,X.CUADRO_RRTT_OCASO,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID,X.NUMERO,X.RESTO_DOMICILIO
                        FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X
                        --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                        LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                            AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                            AND X.PERIODSEQ = Y.PERIODSEQ
                            AND Y.TENANTID = 'INYC'
                            AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                            AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                        WHERE Y.POSITIONSEQ IS NULL
                    ) PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                        --LLS 20220125: Filtro para tener solo Ocaso
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        --ATV 20250205 Anyadimos el estado N
                        --ATV 20250313 Quitamos el estado N
                        AND CAR_LP.ESTADO = 'C'
                        --AND CAR_LP.ESTADO IN ('C', 'N')
                        --ALM 20220425: Filtramos para datos no posteados asi evitamos coger los ya pagados en el cierre.
                        AND CAR_LP.SEQ_POST IS NULL
                        --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                        AND CAR_LP.IMPORTE <> 0
                    --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                    --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                    INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                        THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME
                    INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(CAR_LP.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                        AND EC.TENANTID = 'INYC'
                        AND EC.REMOVEDATE = v_eot
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    GROUP BY
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                        PAD_INS.MUNICIPIO,
                        PAD_INS.DOMICILIO,
                        PAD_INS.CP,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        SUBSTR(CAR_LP.EARNINGGROUPID,7,2),
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                            AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                        THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                             WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0
                        END,
                        --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                        --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                        --SUBSTR(CAR_LP.COD_AGENTE, 1, 4),
                        PAD_OF.POSITIONNAME,
                        PAD_OF.LASTNAME,
                        EC.DESCRIPTION,
                        SUBSTR(CAR_LP.EARNINGGROUPID,4,2),
                        --ATV 20250509 Anyadimos los campos numero y rersto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                    --ATV 20250321 Modificamos para evitar facturas a 0
                    HAVING SUM(CAR_LP.importe) <> 0
                ;
                    
                filas := sql%rowcount;
                COMMIT;
                    
                w_debug('Fin Carga INYC_LC_S4_FACTURA. AGENTES DERECHOS ECONOMICOS:'|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S4_FACTURA.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S4_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S4_FACTURA');

                w_debug('Fin Actualizacion Indices INYC_LC_S4_FACTURA.', v_contador);
                
                --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Fin borrado y carga de INYC_LC_S4_FACTURA                         
            
                --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Inicio borrado y carga de INYC_LC_S5_FACTURA                                     

                w_debug('Inicio Borrado INYC_LC_S5_FACTURA.', v_contador);

                DELETE INYCEXT.INYC_LC_S5_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S5_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S5_FACTURA.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S5_FACTURA 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                        --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                        --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                        THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                            -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                            --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                            --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0 
                        END AS IRPF,   
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                        EC.DESCRIPTION AS COMISION,
                        SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                        SUM(PAY.VALUE) AS IMPORTE,
                        NULL AS SECUENCIAL,
                        --ATV 20250509 Anyadimos los campos numero y rersto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                    --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                    INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                        THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME   
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ = PAY.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                        AND PAY.TENANTID = 'INYC'
                        --ALM 20171201: Filtramos para pagos sin postear, asi no cogemos los pagos del cierre
                        AND (PAY.POSTPIPELINERUNSEQ IS NULL
                            --ALM 20190122: Anadimos un control para quedarnos con el ultimo Post en caso de que haya mas de uno
                            OR (v_periodo_posteado > 1
                                AND PAY.POSTPIPELINERUNSEQ = (SELECT MAX(PY.POSTPIPELINERUNSEQ) FROM INYCEXT.INYC_PAGOS_MES_TEMP PY)))
                    INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                        AND EC.TENANTID = 'INYC'
                        AND EC.REMOVEDATE = v_eot
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --ALM 20170427: Quitamos el filtrado por tipologias de agente, para que se devuelva siempre que haya pagos
                    --              Los balances no aparecen sino a agentes con cambios de tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --    AND AG.COD_INFORME = 101
                    WHERE SUBSTR(PAY.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S5'
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                        PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        SUBSTR(PAY.EARNINGGROUPID,7,2),
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                        --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                        --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                        THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                            -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                            --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                            --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0 
                        END,   
                        PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2),
                        --ATV 20250509 Anyadimos los campos numero y rersto_domicilio a la factura.
                        PAD_INS.NUMERO,
                        PAD_INS.RESTO_DOMICILIO
                    ;
                    
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S5_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S5_FACTURA.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S5_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S5_FACTURA');

                w_debug('Fin Actualizacion Indices INYC_LC_S5_FACTURA.', v_contador);
                
                --LLS 20220103: Lanzamiento conjunto de FAC_S4 y FAC_S5. Fin borrado y carga de INYC_LC_S5_FACTURA                                                 
            
                --LLS 20211215: Petici�n PAC 2022, campo SECUENCIAL INYC_LC_S4_FACTURA
                
                w_debug('Inicio Update campo SECUENCIAL INYC_LC_S4_FACTURA.', v_contador);
                
                UPDATE INYCEXT.INYC_LC_S4_FACTURA F
                SET SECUENCIAL = 1 +
                    ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                    FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_S4_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_LC_S4_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_S5_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_LC_S5_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                        ) Y )
                    WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
                
                COMMIT;
                
                w_debug('Fin Update campo SECUENCIAL INYC_LC_S4_FACTURA.', v_contador);            
                
                --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
                --w_debug('Inicio actualizacion del parametro INYC_LC_S4',v_contador);
                w_debug('Inicio actualizacion del parametro INYC_LC_S4_FAC',v_contador);
                
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI    
                update_table(mes,'INYC_LC_S4_FAC');
                
                --w_debug('Fin actualizacion del parametro INYC_LC_S4',v_contador);
                w_debug('Fin actualizacion del parametro INYC_LC_S4_FAC',v_contador);
                
                --LLS 20211215: Petici�n PAC 2022, campo SECUENCIAL INYC_LC_S5_FACTURA
                
                w_debug('Inicio Update campo SECUENCIAL INYC_LC_S5_FACTURA.', v_contador);
                
                UPDATE INYCEXT.INYC_LC_S5_FACTURA F
                SET SECUENCIAL = 1 +
                    ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                    FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_S4_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_LC_S4_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_S5_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_LC_S5_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                        ) Y )
                    WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
                
                COMMIT;
                
                w_debug('Fin Update campo SECUENCIAL INYC_LC_S5_FACTURA.', v_contador);
                
                --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
                --w_debug('Inicio actualizacion del parametro INYC_LC_S5',v_contador);
                w_debug('Inicio actualizacion del parametro INYC_LC_S5_FAC',v_contador);
                
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S5_FAC');
                
                --w_debug('Fin actualizacion del parametro INYC_LC_S5',v_contador);
                w_debug('Fin actualizacion del parametro INYC_LC_S5_FAC',v_contador);

                
            END IF;
            
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
            
    -------------------------------------------------------------------------------------------------------------------------------------  
    --ALM 20151027: Tabla para el Detalle de Polizas y Productos del S4 de ETERNA
    IF informe = 'S4_E' OR informe LIKE '%,S4_E,%' OR informe LIKE '%,S4_E' OR informe LIKE 'S4_E,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_S4_E_POLIZAS.', v_contador);

            DELETE INYCEXT.INYC_S4_E_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S4_E_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S4_E_POLIZAS. Creditos (sin Asistencias)', v_contador);

            INSERT INTO INYCEXT.INYC_S4_E_POLIZAS 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                    ST.CHANNEL AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                    --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                    CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    C.GENERICNUMBER1 AS ASEGURADOS
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20160616: Pedido por Celeste
                    --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 102.2 
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                    --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                    --AND ST.PRODUCTID like '03%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA  
                ;
                    
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S4_E_POLIZAS. Creditos (sin Asistencias): '|| to_char(filas) || ' filas.', v_contador);

            w_debug('Inicio Carga INYC_S4_E_POLIZAS. Creditos (Asistencias)', v_contador);

            INSERT INTO INYCEXT.INYC_S4_E_POLIZAS 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                    ST.CHANNEL AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                    --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                    CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    C.GENERICNUMBER1 AS ASEGURADOS
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20160616: Pedido por Celeste
                    --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    AND C.NAME = 'DC-O-COM-ServiciosAsistencia-Importe'
                    --ALM 20161027: Filtramos para quedarnos con creditos de Eterna
                    AND C.GENERICATTRIBUTE9 = '03'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 102.2
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                    --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                    --AND ST.PRODUCTID like '03%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA
                ;
                    
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S4_E_POLIZAS. Creditos (Asistencias): '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_S4_E_POLIZAS. Pagos Comerciales 1** y 2**', v_contador);
                        
            INSERT INTO INYCEXT.INYC_S4_E_POLIZAS               
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                    SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                    --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                    SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                    '999999900000000' AS POLIZA,
                    SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                    D.DEPOSITDATE AS FEC_CARGO,
                    0 AS PRIMA_COMISIONABLE, 
                    --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                    --              depende del concepto de pago.
                    --(SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                    CASE WHEN SUBSTR(D.EARNINGCODEID,1,3) = '101' THEN 'Comision Produccion' 
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '102' THEN 'Comision Cartera'
                        --ATV 20240228 Anyadimos concepto 107 a peticion de Celeste
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '107' THEN 'CA 13 Comision'
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '109' THEN 'Domiciliacion'
                        --ALM 20170330: Anadimos los pagos comerciales de concepto 150 a las tramitaciones por peticion de Javier
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('150','153') THEN 'Tramitacion'
                        WHEN SUBSTR(D.EARNINGCODEID,1,3) = '201' THEN 'Regularizacion'
                        ELSE 'Division Comercial'
                    END AS EVENTO,
                    PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                    '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    PAD_INS.SUPERRAPEL,
                    0 AS ASEGURADOS
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND D.TENANTID = 'INYC'
                    --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S4% (ej: 04-S4-03)
                    AND D.EARNINGGROUPID LIKE '%S4%'
                    --ALM 20160907: Solo nos quedamos con los conceptos de pago 100 y 200, el resto no deben aparecer en el detalle del S4
                    --              Correo de Afonso el 06/09/2016
                    AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 102.2 
                --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID 
                    AND CL.REMOVEDATE = v_eot  
                    AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND CL.TENANTID = 'INYC'
                LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                    AND PROD.REMOVEDATE = v_eot  
                    AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND PROD.TENANTID = 'INYC'
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                    --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                    --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '03'
                ;

            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S4_E_POLIZAS. Pagos Comerciales 1** y 2**: '|| to_char(filas) || ' filas.', v_contador);
  
            w_debug('Inicio Carga INYC_S4_E_POLIZAS. DERECHOS ECONOMICOS', v_contador);
 
            INSERT INTO INYCEXT.INYC_S4_E_POLIZAS 
                SELECT               
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.POSITIONNAME,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_ETERNA,
                    PAD_INS.CUADRO_RRTT_ETERNA,
                    SUBSTR(CAR_LP.ORDERID,1,2)AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,
                    PAD_OF.LASTNAME AS OFICINA,
                    'CARTERA_LP' AS NAME, --C.NAME,
                    CAR_LP.IMPORTE AS VALUE, --C.VALUE,
                    0 AS POLIZ_CORR, 
                    0 AS POLIZ_NP,
                    CAR_LP.ORDERID ||CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    CAR_LP.POLIZA,
                    CAR_LP.PRODUCTID,
                    CAR_LP.ACCOUNTINGDATE AS FEC_CARGO,
                    CAR_LP.VALUE AS PRIMA_COMISIONABLE, 
                    CAR_LP.EVENTO,--ST.EVENTO,
                    CAR_LP.PRODUCTO,--ST.PRODUCTO,
                    CAR_LP.FEC_VTO_REC,--ST.FEC_VTO_REC,
                    CAR_LP.PRIMA_NETA,--ST.GENERICNUMBER1 AS PRIMA_NETA,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_INS.TIPO_AGENTE,
                    PAD_INS.SUPERRAPEL,
                    0 AS ASEGURADOS             
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                    --LLS 20220125: Filtro para tener solo Eterna
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                    --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                    AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                    --ALM 20220603: No incluimos registros sin importe de comision.
                    AND CAR_LP.IMPORTE <> 0
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                    AND Y.TENANTID = 'INYC'
                    AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                    AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'                                        
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                WHERE Y.POSITIONSEQ IS NULL    
                ;  
                    
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_S4_E_POLIZAS. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
            
            --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
            --END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_S4_E_POLIZAS.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S4_E_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S4_E_POLIZAS');

            w_debug('Fin Actualizacion Indices INYC_S4_E_POLIZAS.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_S4_E',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S4_E');
        
            w_debug('Fin actualizacion del parametro INYC_S4_E',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_S4_E_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_LC_S4_E_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S4_E_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S4_E_POLIZAS. Creditos (sin Asistencias)', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S4_E_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20160616: Pedido por Celeste
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 102.2 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '03%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA  
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S4_E_POLIZAS. Creditos (sin Asistencias): '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_LC_S4_E_POLIZAS. Creditos (Asistencias)', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S4_E_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20160616: Pedido por Celeste
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        AND C.NAME = 'DC-O-COM-ServiciosAsistencia-Importe'
                        --ALM 20161027: Filtramos para quedarnos con creditos de Eterna
                        AND C.GENERICATTRIBUTE9 = '03'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 102.2
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '03%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S4_E_POLIZAS. Creditos (Asistencias): '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_S4_E_POLIZAS. Pagos Comerciales 1** y 2**', v_contador);
                            
                INSERT INTO INYCEXT.INYC_LC_S4_E_POLIZAS               
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,
                        0 AS PRIMA_COMISIONABLE, 
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --(SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,3) = '101' THEN 'Comision Produccion' 
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '102' THEN 'Comision Cartera'
                            --ATV 20240228 Anyadimos concepto 107 a peticion de Celeste
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '107' THEN 'CA 13 Comision'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '109' THEN 'Domiciliacion'
                            --ALM 20170330: Anadimos los pagos comerciales de concepto 150 a las tramitaciones por peticion de Javier
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('150','153') THEN 'Tramitacion'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '201' THEN 'Regularizacion'
                            ELSE 'Division Comercial'
                        END AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S4% (ej: 04-S4-03)
                        AND D.EARNINGGROUPID LIKE '%S4%'
                        --ALM 20160907: Solo nos quedamos con los conceptos de pago 100 y 200, el resto no deben aparecer en el detalle del S4
                        --              Correo de Afonso el 06/09/2016
                        AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 102.2 
                    --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                    --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID 
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '03'
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S4_E_POLIZAS. Pagos Comerciales 1** y 2**: '|| to_char(filas) || ' filas.', v_contador);
            
                w_debug('Inicio Carga INYC_LC_S4_E_POLIZAS. DERECHOS ECONOMICOS', v_contador);
     
                INSERT INTO INYCEXT.INYC_LC_S4_E_POLIZAS 
                    SELECT               
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.POSITIONNAME,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,
                        PAD_INS.CUADRO_RRTT_ETERNA,
                        SUBSTR(CAR_LP.ORDERID,1,2)AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,
                        PAD_OF.LASTNAME AS OFICINA,
                        'CARTERA_LP' AS NAME, --C.NAME,
                        CAR_LP.IMPORTE AS VALUE, --C.VALUE,
                        0 AS POLIZ_CORR, 
                        0 AS POLIZ_NP,
                        CAR_LP.ORDERID || CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        CAR_LP.POLIZA,
                        CAR_LP.PRODUCTID,
                        CAR_LP.ACCOUNTINGDATE AS FEC_CARGO,
                        CAR_LP.VALUE AS PRIMA_COMISIONABLE, 
                        CAR_LP.EVENTO,--ST.EVENTO,
                        CAR_LP.PRODUCTO,--ST.PRODUCTO,
                        CAR_LP.FEC_VTO_REC,--ST.FEC_VTO_REC,
                        CAR_LP.PRIMA_NETA,--ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS             
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        --LLS 20220125: Filtro para tener solo Eterna
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        AND CAR_LP.ESTADO = 'C'
                        --ALM 20220603: No incluimos registros sin importe de comision.
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                    ;  
                        
                filas := sql%rowcount;            
                COMMIT;           
                        
                w_debug('Fin Carga INYC_LC_S4_E_POLIZAS. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S4_E_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S4_E_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S4_E_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_LC_S4_E_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_S4_E',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S4_E');
            
                w_debug('Fin actualizacion del parametro INYC_LC_S4_E',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
                
                w_debug('Inicio Borrado INYC_BAL_S4_E_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_BAL_S4_E_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_S4_E_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_S4_E_POLIZAS. Creditos (sin Asistencias)', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_S4_E_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20160616: Pedido por Celeste
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        AND C.NAME <> 'DC-O-COM-ServiciosAsistencia-Importe'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 102.2 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '03%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA  
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S4_E_POLIZAS. Creditos (sin Asistencias): '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_BAL_S4_E_POLIZAS. Creditos (Asistencias)', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_S4_E_POLIZAS 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        C.NAME,C.VALUE,C.GENERICNUMBER4 AS POLIZ_CORR,
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --ALM 20160819: Para las TXN de Asistencias (Tipo de Evento => AS50,AS90,AS91,AS10) la Prima Comisionable es 0 y en la txn viene un 1. 
                        CASE WHEN ST.EVENTTYPESEQ in (16607023625929186,16607023625929187,16607023625929188,16607023625929189,16607023625932997) THEN 0 ELSE ST.VALUE END AS PRIMA_COMISIONABLE, 
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        C.GENERICNUMBER1 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20160616: Pedido por Celeste
                        --ALM 20161222: Modificamos el filtro de los creditos para que muestre aquellos que tengan valor o n� de polizas corregidas distinto de 0 
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                        AND C.NAME = 'DC-O-COM-ServiciosAsistencia-Importe'
                        --ALM 20161027: Filtramos para quedarnos con creditos de Eterna
                        AND C.GENERICATTRIBUTE9 = '03'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 102.2
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160907: No podemos filtrar la compania por el producto de la TXN, debemos utilizar el PLAN como hace Callidus
                        --              Separamos la carga en dos partes. Sin Asistencia y Solo Asistencias
                        --AND ST.PRODUCTID like '03%' --Para las asistencias que utilizan el mismo CREDITO en OCASO y ETERNA
                    ;
                        
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S4_E_POLIZAS. Creditos (Asistencias): '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_BAL_S4_E_POLIZAS. Pagos Comerciales 1** y 2**', v_contador);
                            
                INSERT INTO INYCEXT.INYC_BAL_S4_E_POLIZAS               
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        SUBSTR(D.EARNINGGROUPID,7,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        D.NAME,D.VALUE,0 AS POLIZ_CORR,0 AS POLIZ_NP,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,
                        0 AS PRIMA_COMISIONABLE, 
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --(SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,3) = '101' THEN 'Comision Produccion' 
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '102' THEN 'Comision Cartera'
                            --ATV 20240228 Anyadimos concepto 107 a peticion de Celeste
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '107' THEN 'CA 13 Comision'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '109' THEN 'Domiciliacion'
                            --ALM 20170330: Anadimos los pagos comerciales de concepto 150 a las tramitaciones por peticion de Javier
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) in ('150','153') THEN 'Tramitacion'
                            WHEN SUBSTR(D.EARNINGCODEID,1,3) = '201' THEN 'Regularizacion'
                            ELSE 'Division Comercial'
                        END AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,0 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S4% (ej: 04-S4-03)
                        AND D.EARNINGGROUPID LIKE '%S4%'
                        --ALM 20160907: Solo nos quedamos con los conceptos de pago 100 y 200, el resto no deben aparecer en el detalle del S4
                        --              Correo de Afonso el 06/09/2016
                        AND SUBSTR(D.EARNINGCODEID,1,1) in ('1','2')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 102.2 
                    --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                    --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID 
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '03'
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S4_E_POLIZAS. Pagos Comerciales 1** y 2**: '|| to_char(filas) || ' filas.', v_contador);
            
            
                w_debug('Inicio Carga INYC_BAL_S4_E_POLIZAS. DERECHOS ECONOMICOS', v_contador);
     
                INSERT INTO INYCEXT.INYC_BAL_S4_E_POLIZAS 
                    SELECT               
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.POSITIONNAME,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_RRGG_ETERNA,
                        PAD_INS.CUADRO_RRTT_ETERNA,
                        SUBSTR(CAR_LP.ORDERID,1,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,
                        PAD_OF.LASTNAME AS OFICINA,
                        'CARTERA_LP' AS NAME, --C.NAME,
                        CAR_LP.IMPORTE AS VALUE, --C.VALUE,
                        0 AS POLIZ_CORR, 
                        0 AS POLIZ_NP,
                        CAR_LP.ORDERID || CAST(CAR_LP.SUBLINENUMBER AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        CAR_LP.POLIZA,
                        CAR_LP.PRODUCTID,
                        CAR_LP.ACCOUNTINGDATE AS FEC_CARGO,
                        CAR_LP.VALUE AS PRIMA_COMISIONABLE, 
                        CAR_LP.EVENTO,--ST.EVENTO,
                        CAR_LP.PRODUCTO,--ST.PRODUCTO,
                        CAR_LP.FEC_VTO_REC,--ST.FEC_VTO_REC,
                        CAR_LP.PRIMA_NETA,--ST.GENERICNUMBER1 AS PRIMA_NETA,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.SUPERRAPEL,
                        0 AS ASEGURADOS             
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        --LLS 20220125: Filtro para tener solo Eterna
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        AND CAR_LP.ESTADO = 'C'
                        --ALM 20220603: No incluimos registros sin importe de comision.
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                    ;  
                        
                filas := sql%rowcount;            
                COMMIT;           
                        
                w_debug('Fin Carga INYC_BAL_S4_E_POLIZAS. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_S4_E_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_S4_E_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_S4_E_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_BAL_S4_E_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_S4_E',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_S4_E');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_S4_E',v_contador);
            
            END IF;
        
        END IF;

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;  
    
    --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E
    
    --ALM 20151027: Tabla para la FACTURA del S4 y S5 de ETERNA
    --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
    --IF informe = 'S4_E' OR informe like '%,S4_E,%' OR informe like '%,S4_E' OR informe like 'S4_E,%' OR informe = 'ALL'
    --    --ALM 20191128 Anadimos nuevos bloques para lanzar la factura sola
    --    OR informe = 'FAC_S4_E' OR informe like '%,FAC_S4_E,%' OR informe like '%,FAC_S4_E' OR informe like 'FAC_S4_E,%'
    IF informe = 'FAC_S4_E' OR informe LIKE '%,FAC_S4_E,%' OR informe LIKE '%,FAC_S4_E' OR informe LIKE 'FAC_S4_E,%'
        
        --IF informe = 'S5_E' OR informe like '%,S5_E,%' OR informe like '%,S5_E' OR informe like 'S5_E,%' OR informe = 'ALL'
        --    --ALM 20191128 Anadimos nuevos bloques para lanzar la factura sola
        --    OR informe = 'FAC_S5_E' OR informe like '%,FAC_S5_E,%' OR informe like '%,FAC_S5_E' OR informe like 'FAC_S5_E,%'
        OR informe = 'FAC_S5_E' OR informe LIKE '%,FAC_S5_E,%' OR informe LIKE '%,FAC_S5_E' OR informe LIKE 'FAC_S5_E,%'
        
        OR informe = 'ALL'
    
    THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN

            --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Inicio borrado y carga de INYC_S4_E_FACTURA 
        
            w_debug('Inicio Borrado INYC_S4_E_FACTURA.', v_contador);

            DELETE INYCEXT.INYC_S4_E_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S4_E_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S4_E_FACTURA.', v_contador);

            INSERT INTO INYCEXT.INYC_S4_E_FACTURA 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                    SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END AS IRPF,   
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                    EC.DESCRIPTION AS COMISION,
                    SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                    SUM(PAY.VALUE) AS IMPORTE,
                    NULL AS SECUENCIAL
                --ALM 20160216: Nos quedamos solo con los agentes que tienen recibos de Comisiones
                --              NO ESTAN INCLUIDOS LOS POSIBLES AGENTES QUE SOLO TENGAN PAGOS ESPECIALES
                --FROM (SELECT DISTINCT X.* FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                --    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP Y ON X.PARTICIPANTSEQ = Y.PAYEESEQ 
                --        AND X.PERIODSEQ = Y.PERIODSEQ
                --        AND X.POSITIONSEQ = Y.POSITIONSEQ
                --        AND Y.VALUE <> 0
                --    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS Z ON Y.NAME = Z.REGLA
                --        AND Z.F_INICIO <= X.STARTDATE AND  Z.F_FIN > X.STARTDATE
                --        AND Z.COD_INFORME = 102.2
                --) PAD_INS
                --ALM 20160908: Incluimos agentes que solo tengan pagos comerciales
                --              Para filtrar hacemos un inner a los pagos
                --              NO SALDRaN AGENTES CON COMISONES QUE SE ANULEN ENTRE Si
                --FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                --ALM 20160909: Unimos la tabla de agentes por la posicion principal con los pagos haciendo un distinct para que no salgan lineas duplicadas
                --              debidas al resto de posiciones que aparecen en la tabla arbol.
                FROM (SELECT DISTINCT  
                        X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                        X.CUADRO_RRGG_ETERNA,X.CUADRO_RRTT_ETERNA,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND X.PERIODSEQ = Y.PERIODSEQ 
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                ) PAD_INS
                --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                    THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME
                --ALM 20160908: Solo cogemos agentes con pagos
                --              Unimos por la Position Principal porque los pagos solo llegaran a las Posiciones Principales
                INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ_PRIN = PAY.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                    AND PAY.TENANTID = 'INYC'
                    --ALM 20160216: Aplicamos los filtros de Compania y Tipo de Informe dentro de la tabla de Pagos
                    --              para que les salga Factura a los agentes sin Pagos, pero si con recibos de Comisiones
                    AND SUBSTR(PAY.EARNINGGROUPID,7,2) = '03'
                    AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S4'
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,PAD_INS.POS_PRIN,PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                    SUBSTR(PAY.EARNINGGROUPID,7,2),
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END,   
                    PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2)
                ;
        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S4_E_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_S4_E_FACTURA. AGENTES DERECHOS ECONOMICOS.', v_contador);
                
            INSERT INTO INYCEXT.INYC_S4_E_FACTURA
                    
                SELECT
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.MUNICIPIO,
                    PAD_INS.DOMICILIO,
                    PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(CAR_LP.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0
                    END AS IRPF,
                    --LLS 20220127: codigo de oficina correcto
                    --CAR_LP.POSITIONNAME AS COD_OFICINA,
                    --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                    --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                    --SUBSTR(CAR_LP.COD_AGENTE, 1, 4) AS COD_OFICINA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,
                    PAD_OF.LASTNAME AS OFICINA,
                    EC.DESCRIPTION AS COMISION,
                    SUBSTR(CAR_LP.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                    sum(CAR_LP.importe) as importe,--SUM(PAY.VALUE) AS IMPORTE
                    NULL AS SECUENCIAL
                FROM (SELECT DISTINCT
                        x.startdate, x.pos_callidus, /* variables a�adidas, daba error al no encontrarlas */
                        X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                        X.CUADRO_RRGG_OCASO,X.CUADRO_RRTT_OCASO,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND X.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    WHERE Y.POSITIONSEQ IS NULL
                ) PAD_INS
                INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                    --LLS 20220125: Filtro para tener solo Eterna
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                    --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                    AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                    --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                    AND CAR_LP.IMPORTE <> 0
                --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                    THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(CAR_LP.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                GROUP BY
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                    PAD_INS.MUNICIPIO,
                    PAD_INS.DOMICILIO,
                    PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    SUBSTR(CAR_LP.EARNINGGROUPID,7,2),
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                        AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                    THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0
                    END,
                    --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                    --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                    --SUBSTR(CAR_LP.COD_AGENTE, 1, 4),
                    PAD_OF.POSITIONNAME,
                    PAD_OF.LASTNAME,
                    EC.DESCRIPTION,
                    SUBSTR(CAR_LP.EARNINGGROUPID,4,2)
                --ATV 20250321 Modificamos para evitar facturas a 0
                HAVING SUM(CAR_LP.importe) <> 0
            ;
                
            filas := sql%rowcount;
            COMMIT;
                
            w_debug('Fin Carga INYC_S4_E_FACTURA. AGENTES DERECHOS ECONOMICOS:'|| to_char(filas) || ' filas.', v_contador);
                
            --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
            --END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_S4_E_FACTURA.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S4_E_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S4_E_FACTURA');

            w_debug('Fin Actualizacion Indices INYC_S4_E_FACTURA.', v_contador);
            
            --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Fin borrado y carga de INYC_S4_E_FACTURA 
            
            --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Inicio borrado y carga de INYC_S5_E_FACTURA 
            
            w_debug('Inicio Borrado INYC_S5_E_FACTURA.', v_contador);

            DELETE INYCEXT.INYC_S5_E_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S5_E_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S5_E_FACTURA.', v_contador);

            INSERT INTO INYCEXT.INYC_S5_E_FACTURA 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_ETERNA,
                    SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                    --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                    --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                    THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END AS IRPF,   
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                    EC.DESCRIPTION AS COMISION,
                    SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                    SUM(PAY.VALUE) AS IMPORTE,
                    NULL AS SECUENCIAL
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                    THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME   
                INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ = PAY.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                    AND PAY.TENANTID = 'INYC'
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                --ALM 20170427: Quitamos el filtrado por tipologias de agente, para que se devuelva siempre que haya pagos
                --              Los balances no aparecen sino a agnetes con cambios de tipologia
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --    AND AG.COD_INFORME = 103
                WHERE SUBSTR(PAY.EARNINGGROUPID,7,2) = '03'
                    AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S5'
                    --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                    PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                    PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_ETERNA,SUBSTR(PAY.EARNINGGROUPID,7,2),
                    CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                            THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                    --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                    --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                    --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                    THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                        -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                        --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                        --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                        WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                            THEN IRPF.GENERICNUMBER1
                        ELSE 0 
                    END,   
                    PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2)
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S5_E_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_S5_E_FACTURA.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S5_E_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S5_E_FACTURA');

            w_debug('Fin Actualizacion Indices INYC_S5_E_FACTURA.', v_contador);            

            --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Fin borrado y carga de INYC_S5_E_FACTURA
                        
            --LLS 20211215: Petici�n PAC 2022, campo SECUENCIAL
            
            w_debug('Inicio Update campo SECUENCIAL INYC_S4_E_FACTURA.', v_contador);
            
            UPDATE INYCEXT.INYC_S4_E_FACTURA F
            SET SECUENCIAL = 1 +
                ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S4_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S4_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S5_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S5_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                    ) Y )
                WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
            
            COMMIT;
            
            w_debug('Fin Update campo SECUENCIAL INYC_S4_E_FACTURA.', v_contador);
            
            --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
            --w_debug('Inicio actualizacion del parametro INYC_S4_E',v_contador);
            w_debug('Inicio actualizacion del parametro INYC_S4_E_FAC',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S4_E_FAC');
            
            --w_debug('Fin actualizacion del parametro INYC_S4_E',v_contador);
            w_debug('Fin actualizacion del parametro INYC_S4_E_FAC',v_contador);

            w_debug('Inicio Update campo SECUENCIAL INYC_S5_E_FACTURA.', v_contador);
            
            UPDATE INYCEXT.INYC_S5_E_FACTURA F
            SET SECUENCIAL = 1 +
                ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S4_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S4_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_S5_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                        
                        UNION
                        
                        SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                        FROM INYCEXT.INYC_LC_S5_E_FACTURA X
                        WHERE X.POS_PRIN = F.POS_PRIN
                        --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                        --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                        AND X.PERIODSEQ IN (
                            SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                            WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND Y.REMOVEDATE = v_eot
                            AND Y.PERIODTYPESEQ = 2814749767106561)
                    ) Y )
                WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
            
            COMMIT;
            
            w_debug('Fin Update campo SECUENCIAL INYC_S5_E_FACTURA.', v_contador);
            
            --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
            --w_debug('Inicio actualizacion del parametro INYC_S5_E',v_contador);
            w_debug('Inicio actualizacion del parametro INYC_S5_E_FAC',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S5_E_FAC');
            
            --w_debug('Fin actualizacion del parametro INYC_S5_E',v_contador);
            w_debug('Fin actualizacion del parametro INYC_S5_E_FAC',v_contador);
            
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Inicio borrado y carga de INYC_LC_S4_E_FACTURA
                
                w_debug('Inicio Borrado INYC_LC_S4_E_FACTURA.', v_contador);

                DELETE INYCEXT.INYC_LC_S4_E_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S4_E_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S4_E_FACTURA.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S4_E_FACTURA 
                        SELECT
                            PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                            PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                            PAD_INS.BOUSERID,PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                            PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                            PAD_INS.POS_PRIN,
                            PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                            SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                            CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                    THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                                AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                            THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                                --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                                --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                                WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                    THEN IRPF.GENERICNUMBER1
                                ELSE 0 
                            END AS IRPF,   
                            PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                            EC.DESCRIPTION AS COMISION,
                            SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                            SUM(PAY.VALUE) AS IMPORTE,
                            NULL AS SECUENCIAL
                        --ALM 20160216: Nos quedamos solo con los agentes que tienen recibos de Comisiones
                        --              NO ESTAN INCLUIDOS LOS POSIBLES AGENTES QUE SOLO TENGAN PAGOS ESPECIALES
                        --FROM (SELECT DISTINCT X.* FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                        --    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP Y ON X.PARTICIPANTSEQ = Y.PAYEESEQ 
                        --        AND X.PERIODSEQ = Y.PERIODSEQ
                        --        AND X.POSITIONSEQ = Y.POSITIONSEQ
                        --        AND Y.VALUE <> 0
                        --    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS Z ON Y.NAME = Z.REGLA
                        --        AND Z.F_INICIO <= X.STARTDATE AND  Z.F_FIN > X.STARTDATE
                        --        AND Z.COD_INFORME = 102.2
                        --) PAD_INS
                        --ALM 20160908: Incluimos agentes que solo tengan pagos comerciales
                        --              Para filtrar hacemos un inner a los pagos
                        --              NO SALDRaN AGENTES CON COMISONES QUE SE ANULEN ENTRE Si
                        --FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                        --ALM 20160909: Unimos la tabla de agentes por la posicion principal con los pagos haciendo un distinct para que no salgan lineas duplicadas
                        --              debidas al resto de posiciones que aparecen en la tabla arbol.
                        FROM (SELECT DISTINCT  
                                X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                                X.CUADRO_RRGG_ETERNA,X.CUADRO_RRTT_ETERNA,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID
                            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X 
                            INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                                AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                                AND X.PERIODSEQ = Y.PERIODSEQ 
                                AND Y.TENANTID = 'INYC'
                                AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                                AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                                --ALM 20171201: Filtramos para pagos sin postear, asi no cogemos los pagos del cierre
                                AND (Y.POSTPIPELINERUNSEQ IS NULL
                                    --ALM 20190122: Anadimos un control para quedarnos con el ultimo Post en caso de que haya mas de uno
                                    OR (v_periodo_posteado > 1
                                        AND Y.POSTPIPELINERUNSEQ = (SELECT MAX(PY.POSTPIPELINERUNSEQ) FROM INYCEXT.INYC_PAGOS_MES_TEMP PY)))
                        ) PAD_INS
                        --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                        --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                        INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                            THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME 
                        --ALM 20160908: Solo cogemos agentes con pagos
                        --              Unimos por la Position Principal porque los pagos solo llegaran a las Posiciones Principales
                        INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ_PRIN = PAY.POSITIONSEQ
                            AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                            AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                            AND PAY.TENANTID = 'INYC'
                            --ALM 20160216: Aplicamos los filtros de Compania y Tipo de Informe dentro de la tabla de Pagos
                            --              para que les salga Factura a los agentes sin Pagos, pero si con recibos de Comisiones
                            AND SUBSTR(PAY.EARNINGGROUPID,7,2) = '03'
                            AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S4'
                            --ALM 20171201: Filtramos para pagos sin postear, asi no cogemos los pagos del cierre
                            AND (PAY.POSTPIPELINERUNSEQ IS NULL
                                --ALM 20190122: Anadimos un control para quedarnos con el ultimo Post en caso de que haya mas de uno
                                OR (v_periodo_posteado > 1
                                    AND PAY.POSTPIPELINERUNSEQ = (SELECT MAX(PY.POSTPIPELINERUNSEQ) FROM INYCEXT.INYC_PAGOS_MES_TEMP PY)))
                        INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                            AND EC.TENANTID = 'INYC'
                            AND EC.REMOVEDATE = v_eot
                        LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                            AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                        --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                            PAD_INS.BOUSERID,PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                            PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,PAD_INS.POS_PRIN,PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                            SUBSTR(PAY.EARNINGGROUPID,7,2),
                            CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                    THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                                AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                            THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                                --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                                --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                                WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                    THEN IRPF.GENERICNUMBER1
                                ELSE 0 
                            END,   
                            PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2)
                        ;
                           
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S4_E_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_S4_E_FACTURA. AGENTES DERECHOS ECONOMICOS.', v_contador);
                    
                INSERT INTO INYCEXT.INYC_LC_S4_E_FACTURA
                        
                        SELECT
                            PAD_INS.PARTICIPANTSEQ,
                            PAD_INS.POSITIONSEQ_PRIN,
                            PAD_INS.PERIODSEQ,
                            PAD_INS.PERIODO,
                            PAD_INS.BOUSERID,
                            PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                            PAD_INS.MUNICIPIO,
                            PAD_INS.DOMICILIO,
                            PAD_INS.CP,
                            PAD_INS.POS_PRIN,
                            PAD_INS.CUADRO_RRGG_OCASO,
                            PAD_INS.CUADRO_RRTT_OCASO,
                            SUBSTR(CAR_LP.EARNINGGROUPID,7,2) AS COMPANIA,
                            CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                    THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                                AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                            THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                                WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                    THEN IRPF.GENERICNUMBER1
                                ELSE 0
                            END AS IRPF,
                            --LLS 20220127: codigo de oficina correcto
                            --CAR_LP.POSITIONNAME AS COD_OFICINA,
                            --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                            --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                            --SUBSTR(CAR_LP.COD_AGENTE, 1, 4) AS COD_OFICINA,
                            PAD_OF.POSITIONNAME AS COD_OFICINA,
                            PAD_OF.LASTNAME AS OFICINA,
                            EC.DESCRIPTION AS COMISION,
                            SUBSTR(CAR_LP.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                            sum(CAR_LP.importe) as importe,--SUM(PAY.VALUE) AS IMPORTE
                            NULL AS SECUENCIAL
                        FROM (SELECT DISTINCT
                            x.startdate, x.pos_callidus, /* variables a�adidas, daba error al no encontrarlas */
                            X.PARTICIPANTSEQ,X.POSITIONSEQ_PRIN,X.PERIODSEQ,X.PERIODO,X.BOUSERID,X.NIF,X.FIRSTNAME,X.LASTNAME,X.SUFFIX,X.MUNICIPIO,X.DOMICILIO,X.CP,X.POS_PRIN,
                                X.CUADRO_RRGG_OCASO,X.CUADRO_RRTT_OCASO,X.TIPO_PERSONA,X.ID_EMPLEADO,X.IRPF_EMPLEADO,X.CIA_EMPLEADO,X.TAXID
                            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP X
                            --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                            LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON X.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                                AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                                AND X.PERIODSEQ = Y.PERIODSEQ
                                AND Y.TENANTID = 'INYC'
                                AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                                AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                            WHERE Y.POSITIONSEQ IS NULL
                        ) PAD_INS
                        INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE
                            --LLS 20220125: Filtro para tener solo Eterna
                            AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                            --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                            AND CAR_LP.ESTADO = 'C'
                            --ALM 20220425: Filtramos para datos no posteados asi evitamos coger los ya pagados en el cierre.
                            AND CAR_LP.SEQ_POST IS NULL
                            --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                            AND CAR_LP.IMPORTE <> 0
                        --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                        --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                        INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                            THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME
                        INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(CAR_LP.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                            AND EC.TENANTID = 'INYC'
                            AND EC.REMOVEDATE = v_eot
                        LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                            AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                        GROUP BY
                            PAD_INS.PARTICIPANTSEQ,
                            PAD_INS.POSITIONSEQ_PRIN,
                            PAD_INS.PERIODSEQ,
                            PAD_INS.PERIODO,
                            PAD_INS.BOUSERID,
                            PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                            PAD_INS.MUNICIPIO,
                            PAD_INS.DOMICILIO,
                            PAD_INS.CP,
                            PAD_INS.POS_PRIN,
                            PAD_INS.CUADRO_RRGG_OCASO,
                            PAD_INS.CUADRO_RRTT_OCASO,
                            SUBSTR(CAR_LP.EARNINGGROUPID,7,2),
                            CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                    THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0
                                                AND PAD_INS.CIA_EMPLEADO = SUBSTR(CAR_LP.EARNINGGROUPID,7,2)
                                            THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END
                                WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                    THEN IRPF.GENERICNUMBER1
                                ELSE 0
                            END,
                            --ALM 20220512: Debemos usar el campo de la tabla de oficinas, no el cod_agente de la tabla de cartera porque puede haber mas de uno distinto para el mismo agente.
                            --              Ej: Agente 42930529V0000, con codigos 0157005922 y 0380005922 para el mes de abril 2022.
                            --SUBSTR(CAR_LP.COD_AGENTE, 1, 4),
                            PAD_OF.POSITIONNAME,
                            PAD_OF.LASTNAME,
                            EC.DESCRIPTION,
                            SUBSTR(CAR_LP.EARNINGGROUPID,4,2)
                        --ATV 20250321 Modificamos para evitar facturas a 0
                        HAVING SUM(CAR_LP.importe) <> 0
                ;
                    
                filas := sql%rowcount;
                COMMIT;
                    
                w_debug('Fin Carga INYC_LC_S4_E_FACTURA. AGENTES DERECHOS ECONOMICOS:'|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S4_E_FACTURA.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S4_E_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S4_E_FACTURA');

                w_debug('Fin Actualizacion Indices INYC_LC_S4_E_FACTURA.', v_contador);
                
                --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Fin borrado y carga de INYC_LC_S4_E_FACTURA
                
                --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Inicio borrado y carga de INYC_LC_S5_E_FACTURA
                
                w_debug('Inicio Borrado INYC_LC_S5_E_FACTURA.', v_contador);

                DELETE INYCEXT.INYC_LC_S5_E_FACTURA WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S5_E_FACTURA: '|| to_char(filas) || ' filas borradas.', v_contador);

                w_debug('Inicio Carga INYC_LC_S5_E_FACTURA.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S5_E_FACTURA 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        SUBSTR(PAY.EARNINGGROUPID,7,2) AS COMPANIA,
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                        --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                        --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                        THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                            -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                            --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                            --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0 
                        END AS IRPF,   
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA, 
                        EC.DESCRIPTION AS COMISION,
                        SUBSTR(PAY.EARNINGGROUPID,4,2) AS TIPO_INFORME,
                        SUM(PAY.VALUE) AS IMPORTE,
                        NULL AS SECUENCIAL
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    --ALM 20220628: Anadimos una condicion mas para tratar los casos no registrados como los nulos.
                    --INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON CASE WHEN PAD_INS.TAXID IS NULL THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END = IRPF.NAME
                    INNER JOIN INYCEXT.INYC_TABLA_IRPF IRPF ON (CASE WHEN PAD_INS.TAXID IS NULL OR CAST(PAD_INS.TAXID AS VARCHAR2(15)) NOT IN ('I','E','S','C') 
                        THEN 'P' ELSE CAST(PAD_INS.TAXID AS VARCHAR2(15)) END) = IRPF.NAME   
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON PAD_INS.POSITIONSEQ = PAY.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = PAY.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = PAY.PERIODSEQ 
                        AND PAY.TENANTID = 'INYC'
                        --ALM 20171201: Filtramos para pagos sin postear, asi no cogemos los pagos del cierre
                        AND (PAY.POSTPIPELINERUNSEQ IS NULL
                            --ALM 20190122: Anadimos un control para quedarnos con el ultimo Post en caso de que haya mas de uno
                            OR (v_periodo_posteado > 1
                                AND PAY.POSTPIPELINERUNSEQ = (SELECT MAX(PY.POSTPIPELINERUNSEQ) FROM INYCEXT.INYC_PAGOS_MES_TEMP PY)))
                    INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(PAY.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                        AND EC.TENANTID = 'INYC'
                        AND EC.REMOVEDATE = v_eot
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    --ALM 20170427: Quitamos el filtrado por tipologias de agente, para que se devuelva siempre que haya pagos
                    --              Los balances no aparecen sino a agnetes con cambios de tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --    AND AG.COD_INFORME = 103
                    WHERE SUBSTR(PAY.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(PAY.EARNINGGROUPID,4,2) = 'S5'
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),
                        PAD_INS.MUNICIPIO,PAD_INS.DOMICILIO,PAD_INS.CP,
                        PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_ETERNA,SUBSTR(PAY.EARNINGGROUPID,7,2),
                        CASE WHEN PAD_INS.TIPO_PERSONA = 'F'
                                THEN CASE WHEN PAD_INS.ID_EMPLEADO IS NOT NULL AND PAD_INS.ID_EMPLEADO <> 0 
                                        --ALM 20160811: A los pagos del S5 de los empleados no se les aplica IRPF
                                        --    AND PAD_INS.CIA_EMPLEADO = SUBSTR(PAY.EARNINGGROUPID,7,2)
                                        --THEN PAD_INS.IRPF_EMPLEADO ELSE IRPF.GENERICNUMBER1 END 
                                        THEN 0 ELSE IRPF.GENERICNUMBER1 END 
                            -- Juridicas que comiencen por estas letras, aplical el tipo de IRPF
                            --ALM 20170907:    Por peticion de Javier quitamos los CIF que empiezan por U
                            --ALM 20180521: A peticion de Javier ponemos IRPF 0 a la CIF pedido.
                            WHEN PAD_INS.TIPO_PERSONA = 'J' AND SUBSTR(PAD_INS.NIF,1,1) in ('G','J','E','V') AND PAD_INS.NIF <> 'J72106826'
                                THEN IRPF.GENERICNUMBER1
                            ELSE 0 
                        END,   
                        PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,EC.DESCRIPTION,SUBSTR(PAY.EARNINGGROUPID,4,2)
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S5_E_FACTURA: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S5_E_FACTURA.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S5_E_FACTURA COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S5_E_FACTURA');

                w_debug('Fin Actualizacion Indices INYC_LC_S5_E_FACTURA.', v_contador);                
                
                
                --LLS 20220103: Lanzamiento conjunto de FAC_S4_E y FAC_S5_E. Fin borrado y carga de INYC_LC_S5_E_FACTURA                
                
                --LLS 20211215: Petici�n PAC 2022, campo SECUENCIAL
                
                w_debug('Inicio Update campo SECUENCIAL INYC_LC_S4_E_FACTURA.', v_contador);
                
                UPDATE INYCEXT.INYC_LC_S4_E_FACTURA F
                SET SECUENCIAL = 1 +
                    ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                    FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_S4_E_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_LC_S4_E_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
