                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                        ) Y )
                    WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
                
