                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S4_E_FAC');
                
                --w_debug('Fin actualizacion del parametro INYC_LC_S4_E',v_contador);
