                w_debug('Inicio Update campo SECUENCIAL INYC_LC_S5_E_FACTURA.', v_contador);
                
                UPDATE INYCEXT.INYC_LC_S5_E_FACTURA F
                SET SECUENCIAL = 1 +
                    ( SELECT NVL(MAX(Y.SECUENCIAL),0)
                    FROM (    SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_S4_E_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
