                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
