                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                            
                            UNION
                            
                            SELECT MAX(X.SECUENCIAL) AS SECUENCIAL
                            FROM INYCEXT.INYC_LC_S5_E_FACTURA X
                            WHERE X.POS_PRIN = F.POS_PRIN
                            --ALM 20220228: Usamos el PERIODSEQ para que la consulta vaya mejor ya que la tabla esta particionada por ese campo.
                            --AND X.PERIODO LIKE '%' || SUBSTR(F.PERIODO,-4)
                            AND X.PERIODSEQ IN (
                                SELECT Y.PERIODSEQ FROM TCMP.CS_PERIOD Y
                                WHERE Y.NAME LIKE '%' || SUBSTR(F.PERIODO,-4)
                                AND Y.REMOVEDATE = v_eot
                                AND Y.PERIODTYPESEQ = 2814749767106561)
                        ) Y )
                    WHERE F.PERIODSEQ = v_periodRow.PERIODSEQ;
                    
                COMMIT;
                
                w_debug('Fin Update campo SECUENCIAL INYC_LC_S5_E_FACTURA.', v_contador);
                
                --ALM 20200601: Diferenciamos completamente el informe de Factura del de Detalle
                --w_debug('Inicio actualizacion del parametro INYC_LC_S5_E',v_contador);
                w_debug('Inicio actualizacion del parametro INYC_LC_S5_E_FAC',v_contador);
                
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S5_E_FAC');
                
                --w_debug('Fin actualizacion del parametro INYC_LC_S5_E',v_contador);
                w_debug('Fin actualizacion del parametro INYC_LC_S5_E_FAC',v_contador);
                
                
            END IF;
        
        END IF;

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;    

    --ALM 20151027: Tabla para el Detalle de Polizas y Productos del S5 de OCASO
    IF informe = 'S5' OR informe LIKE '%,S5,%' OR informe LIKE '%,S5' OR informe LIKE 'S5,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_S5_POLIZAS.', v_contador);

            DELETE INYCEXT.INYC_S5_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S5_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S5_POLIZAS. Creditos.', v_contador);

            INSERT INTO INYCEXT.INYC_S5_POLIZAS 
                --ALM 20170215: Modificamos la select para incluir los creditos que cuentan extornos
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_OCASO,
                    PAD_INS.ID_TIPO_AGENTE,
                    ST.CHANNEL AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --C.NAME,C.VALUE,C.GENERICNUMBER1 AS COEF_CORR,
                    SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida' AS NAME,
                    MAX(ABS(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END)) *
                        MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.VALUE) ELSE -1 END) AS VALUE,
                    MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                    --DIF.RATEVALUE AS PORC_DIFERENCIAL,DIF.VALUE AS IMP_DIFERENCIAL,
                    SUM(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                    --ALM 20160629: Anadimos un campo para contar las Polizas de Nueva Produccion
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) AS POLIZ_NP,
                    --CT.RATEVALUE AS PORC_LOCOMOCION,CT.VALUE AS IMP_LOCOMOCION,
                    SUM(CT.RATEVALUE) AS PORC_LOCOMOCION,SUM(CT.VALUE) AS IMP_LOCOMOCION,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --C.GENERICNUMBER5 AS PRIMA_NETA,
                    MAX(ABS(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END)) *
                        MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.GENERICNUMBER5) ELSE -1 END) AS PRIMA_NETA,
                    ST.GENERICATTRIBUTE12 AS DURACION,
                    PAD_AG.POSITIONNAME AS POSITIONNAME_AG,PAD_AG.CUADRO_RRGG_OCASO AS CUADRO_RRGG_AG,
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) AS POLIZ_CORR,
                    SUM(CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) AS ASEGURADOS,
                    --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                    PAD_AG.ID_TIPO_AGENTE AS ID_TIPO_AGENTE_AG,
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER1 ELSE 0 END) AS POLIZ_CORR_AG,
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER2 ELSE 0 END) AS CORR_TIPO_AGENTE,
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER6 ELSE 0 END) AS CORR_CAPTACION
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20180125: Filtramos por los creditos que cuentan polizas corregidas
                    AND (C.VALUE <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                    --Filtramos por el GB3 que marca si el inspector era antes un agente para no tener en cuenta estos creditos
                    --ALM 20170518: Modificamos el filtro para unificar con PEPI y RPI
                    --AND (C.GENERICBOOLEAN3 <> 1 OR C.GENERICBOOLEAN3 IS NULL)
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POS_CALLIDUS
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 101.2
                --ALM 20160630: Al anadir las Commission de CT hay que filtrar unicamente por las de DIF, para ello necesitamos hacer un inner con cs_incentive
                LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                            --ALM 20171213: Filtramos para no tener en cuenta las Commission Anuales 
                            AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-O-DIF-%' AND I_DIF.NAME NOT LIKE '%-Anual'
                        WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                    ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                --ALM 20160630: Por las modificaciones en el CT tenemos que usar las Commissions para calcular el CT
                LEFT OUTER JOIN (SELECT COM_CT.CREDITSEQ,COM_CT.RATEVALUE,COM_CT.VALUE FROM CS_COMMISSION COM_CT 
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON COM_CT.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN TCMP.CS_INCENTIVE I_CT ON COM_CT.INCENTIVESEQ = I_CT.INCENTIVESEQ AND COM_CT.PIPELINERUNSEQ = I_CT.PIPELINERUNSEQ
                            AND I_CT.TENANTID = 'INYC' AND I_CT.PERIODSEQ = v_periodRow.PERIODSEQ AND I_CT.NAME LIKE 'C-O-CT-%'
                        WHERE COM_CT.TENANTID = 'INYC' AND COM_CT.PERIODSEQ = v_periodRow.PERIODSEQ
                    ) CT ON C.CREDITSEQ = CT.CREDITSEQ 
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    AND AG.COD_INFORME = 101
                --ALM 20160912: Anadimos un filtro para que no se carguen casos en los que los Diferenciales y la Locomocion sea nula
                --ALM 20170215: Ademas de lo anterior incluimos los creditos que cuentan polizas distintos de 0
                --ALM 20170301: Ademas de lo anterior incluimos los resultados de la consulta cumplan el resto de filtros o no para los agentes 79
                --              necesario para el nuevo informe de Produccion Oficina que usa tambien esta tabla
                WHERE (DIF.VALUE IS NOT NULL OR CT.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79
                        OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0
                        --ALM 20180119: Cogemos tambien los creditos que cuentes pol. corregidas o asegurados
                        OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) <> 0
                        OR (CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) <> 0)
                    --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20170518: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61
                    --              Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                    AND ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                            --ALM 20170628: Por peticion de David anadimos los tipos 82
                            AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                        OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                    PAD_INS.ID_TIPO_AGENTE,ST.CHANNEL,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)),ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,
                    ST.GENERICATTRIBUTE12,PAD_AG.POSITIONNAME,PAD_AG.CUADRO_RRGG_OCASO,ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,PAD_INS.TIPO_AGENTE,
                    --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                    PAD_AG.ID_TIPO_AGENTE
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S5_POLIZAS. Creditos: '|| to_char(filas) || ' filas.', v_contador);

            w_debug('Inicio Carga INYC_S5_POLIZAS. Pagos Comerciales 2** y 5**.', v_contador);

            INSERT INTO INYCEXT.INYC_S5_POLIZAS 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_OCASO,
                    PAD_INS.ID_TIPO_AGENTE,
                    SUBSTR(D.EARNINGCODEID,5,2) AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    D.NAME,CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN 0 ELSE D.VALUE END AS VALUE,0 AS COEF_CORR,
                    0 AS PORC_DIFERENCIAL,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '2' THEN D.VALUE ELSE 0 END AS IMP_DIFERENCIAL,
                    0 AS POLIZ_NP,
                    0 AS PORC_LOCOMOCION,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '5' THEN D.VALUE ELSE 0 END AS IMP_LOCOMOCION,
                    --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                    SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                    '999999900000000' AS POLIZA,
                    --ALM 20160914: Para Abril y Mayo los Pagos Comerciales no traen el producto en el EARNINGCODEID sino en el GA1
                    --SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                    D.DEPOSITDATE AS FEC_CARGO,0 AS PRIMA_NETA,'' AS DURACION,
                    '' AS POSITIONNAME_AG,'' CUADRO_RRGG_AG,
                    --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                    --              depende del concepto de pago.
                    --CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN
                    --        (SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                    --    ELSE ''
                    --END AS EVENTO,
                    --ALM 20160914: Como solo cogemos conceptos 2xx y 5xx ponemos regularizacion a todo.
                    'Regularizacion' AS EVENTO,
                    PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                    '' AS FEC_VTO_REC,
                    PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    0 AS POLIZ_CORR,
                    0 AS ASEGURADOS,
                    --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                    '' AS ID_TIPO_AGENTE_AG,
                    0 AS POLIZ_CORR_AG,
                    0 AS CORR_TIPO_AGENTE,
                    0 AS CORR_CAPTACION
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND D.TENANTID = 'INYC'
                    --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S5% (ej: 04-S5-03)
                    AND D.EARNINGGROUPID LIKE '%S5%'
                    --ALM 20160914: Solo nos quedamos con los Pagos Comerciales que pertenezcan a Diferenciales o Compensacion por Transaporte
                    AND ((D.NAME = 'D-O-Pagos-Fijos' AND SUBSTR(D.EARNINGCODEID,1,1) IN ('2','5')) OR D.NAME LIKE 'DD-O-COLC-Inspector-Pago-00%')
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON SUBSTR(D.NAME,1,27) = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 101.2
                --INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                --ALM 20160822: Como existen pagos comerciales antiguos en los que el producto venia informado en el GA1 del deposito cambiamos la join
                --              Necesario para Pagos Comerciales de Abril y Mayo 2016
                INNER JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END 
                    AND CL.REMOVEDATE = v_eot  
                    AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND CL.TENANTID = 'INYC'
                LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                    AND PROD.REMOVEDATE = v_eot  
                    AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND PROD.TENANTID = 'INYC'
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    AND AG.COD_INFORME = 101
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                    --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                    --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '01'
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S5_POLIZAS. Pagos Comerciales 2** y 5**: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_S5_POLIZAS.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S5_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S5_POLIZAS');

            w_debug('Fin Actualizacion Indices INYC_S5_POLIZAS.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_S5',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S5');
        
            w_debug('Fin actualizacion del parametro INYC_S5',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_S5_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_LC_S5_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S5_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S5_POLIZAS. Creditos.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S5_POLIZAS 
                    --ALM 20170215: Modificamos la select para incluir los creditos que cuentan extornos
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --C.NAME,C.VALUE,C.GENERICNUMBER1 AS COEF_CORR,
                        SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida' AS NAME,
                        MAX(ABS(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END)) *
                            MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.VALUE) ELSE -1 END) AS VALUE,
                        MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                        --DIF.RATEVALUE AS PORC_DIFERENCIAL,DIF.VALUE AS IMP_DIFERENCIAL,
                        SUM(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                        --ALM 20160629: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) AS POLIZ_NP,
                        --CT.RATEVALUE AS PORC_LOCOMOCION,CT.VALUE AS IMP_LOCOMOCION,
                        SUM(CT.RATEVALUE) AS PORC_LOCOMOCION,SUM(CT.VALUE) AS IMP_LOCOMOCION,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --C.GENERICNUMBER5 AS PRIMA_NETA,
                        MAX(ABS(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END)) *
                            MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.GENERICNUMBER5) ELSE -1 END) AS PRIMA_NETA,
                        ST.GENERICATTRIBUTE12 AS DURACION,
                        PAD_AG.POSITIONNAME AS POSITIONNAME_AG,PAD_AG.CUADRO_RRGG_OCASO AS CUADRO_RRGG_AG,
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) AS POLIZ_CORR,
                        SUM(CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) AS ASEGURADOS,
                        --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                        PAD_AG.ID_TIPO_AGENTE AS ID_TIPO_AGENTE_AG,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER1 ELSE 0 END) AS POLIZ_CORR_AG,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER2 ELSE 0 END) AS CORR_TIPO_AGENTE,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER6 ELSE 0 END) AS CORR_CAPTACION
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20180125: Filtramos por los creditos que cuentan polizas corregidas
                        AND (C.VALUE <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                        --Filtramos por el GB3 que marca si el inspector era antes un agente para no tener en cuenta estos creditos
                        --ALM 20170518: Modificamos el filtro para unificar con PEPI y RPI
                        --AND (C.GENERICBOOLEAN3 <> 1 OR C.GENERICBOOLEAN3 IS NULL)
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POS_CALLIDUS
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 101.2
                    --ALM 20160630: Al anadir las Commission de CT hay que filtrar unicamente por las de DIF, para ello necesitamos hacer un inner con cs_incentive
                    LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                            --ALM 20171213: Filtramos para no tener en cuenta las Commission Anuales 
                            AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-O-DIF-%' AND I_DIF.NAME NOT LIKE '%-Anual'
                            WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                    --ALM 20160630: Por las modificaciones en el CT tenemos que usar las Commissions para calcular el CT
                    LEFT OUTER JOIN (SELECT COM_CT.CREDITSEQ,COM_CT.RATEVALUE,COM_CT.VALUE FROM CS_COMMISSION COM_CT 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_CT.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_CT ON COM_CT.INCENTIVESEQ = I_CT.INCENTIVESEQ AND COM_CT.PIPELINERUNSEQ = I_CT.PIPELINERUNSEQ
                                AND I_CT.TENANTID = 'INYC' AND I_CT.PERIODSEQ = v_periodRow.PERIODSEQ AND I_CT.NAME LIKE 'C-O-CT-%' 
                            WHERE COM_CT.TENANTID = 'INYC' AND COM_CT.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) CT ON C.CREDITSEQ = CT.CREDITSEQ 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    --ALM 20160912: Anadimos un filtro para que no se carguen casos en los que los Diferenciales y la Locomocion sea nula
                    --ALM 20170215: Ademas de lo anterior incluimos los creditos que cuentan polizas distintos de 0
                    --ALM 20170301: Ademas de lo anterior incluimos los resultados de la consulta cumplan el resto de filtros o no para los agentes 79
                    --              necesario para el nuevo informe de Produccion Oficina que usa tambien esta tabla
                    WHERE (DIF.VALUE IS NOT NULL OR CT.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79
                            OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0
                            --ALM 20180119: Cogemos tambien los creditos que cuentes pol. corregidas o asegurados
                            OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) <> 0
                            OR (CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) <> 0)
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20170518: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61
                        --              Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                        AND ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                --ALM 20170628: Por peticion de David anadimos los tipos 82
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,ST.CHANNEL,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)),ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,
                        ST.GENERICATTRIBUTE12,PAD_AG.POSITIONNAME,PAD_AG.CUADRO_RRGG_OCASO,ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,PAD_INS.TIPO_AGENTE,
                        --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                        PAD_AG.ID_TIPO_AGENTE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S5_POLIZAS. Creditos: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_LC_S5_POLIZAS. Pagos Comerciales 2** y 5**.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S5_POLIZAS 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        SUBSTR(D.EARNINGCODEID,5,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        D.NAME,CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN 0 ELSE D.VALUE END AS VALUE,0 AS COEF_CORR,
                        0 AS PORC_DIFERENCIAL,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '2' THEN D.VALUE ELSE 0 END AS IMP_DIFERENCIAL,
                        0 AS POLIZ_NP,
                        0 AS PORC_LOCOMOCION,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '5' THEN D.VALUE ELSE 0 END AS IMP_LOCOMOCION,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        --ALM 20160914: Para Abril y Mayo los Pagos Comerciales no traen el producto en el EARNINGCODEID sino en el GA1
                        --SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,0 AS PRIMA_NETA,'' AS DURACION,
                        '' AS POSITIONNAME_AG,'' CUADRO_RRGG_AG,
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN
                        --        (SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        --    ELSE ''
                        --END AS EVENTO,
                        --ALM 20160914: Como solo cogemos conceptos 2xx y 5xx ponemos regularizacion a todo.
                        'Regularizacion' AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        0 AS POLIZ_CORR,
                        0 AS ASEGURADOS,
                        --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                        '' AS ID_TIPO_AGENTE_AG,
                        0 AS POLIZ_CORR_AG,
                        0 AS CORR_TIPO_AGENTE,
                        0 AS CORR_CAPTACION
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S5% (ej: 04-S5-03)
                        AND D.EARNINGGROUPID LIKE '%S5%'
                        --ALM 20160914: Solo nos quedamos con los Pagos Comerciales que pertenezcan a Diferenciales o Compensacion por Transaporte
                        AND ((D.NAME = 'D-O-Pagos-Fijos' AND SUBSTR(D.EARNINGCODEID,1,1) IN ('2','5')) OR D.NAME LIKE 'DD-O-COLC-Inspector-Pago-00%')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON SUBSTR(D.NAME,1,27) = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 101.2
                    --INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                    --ALM 20160822: Como existen pagos comerciales antiguos en los que el producto venia informado en el GA1 del deposito cambiamos la join
                    --              Necesario para Pagos Comerciales de Abril y Mayo 2016
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END 
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '01'
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S5_POLIZAS. Pagos Comerciales 2** y 5**: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S5_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S5_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S5_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_LC_S5_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_S5',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S5');
            
                w_debug('Fin actualizacion del parametro INYC_LC_S5',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_S5_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_BAL_S5_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_S5_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_S5_POLIZAS. Creditos.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_S5_POLIZAS 
                    --ALM 20170215: Modificamos la select para incluir los creditos que cuentan extornos
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --C.NAME,C.VALUE,C.GENERICNUMBER1 AS COEF_CORR,
                        SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida' AS NAME,
                        MAX(ABS(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END)) *
                            MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.VALUE) ELSE -1 END) AS VALUE,
                        MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                        --DIF.RATEVALUE AS PORC_DIFERENCIAL,DIF.VALUE AS IMP_DIFERENCIAL,
                        SUM(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                        --ALM 20160629: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) AS POLIZ_NP,
                        --CT.RATEVALUE AS PORC_LOCOMOCION,CT.VALUE AS IMP_LOCOMOCION,
                        SUM(CT.RATEVALUE) AS PORC_LOCOMOCION,SUM(CT.VALUE) AS IMP_LOCOMOCION,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --C.GENERICNUMBER5 AS PRIMA_NETA,
                        MAX(ABS(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END)) *
                            MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.GENERICNUMBER5) ELSE -1 END) AS PRIMA_NETA,
                        ST.GENERICATTRIBUTE12 AS DURACION,
                        PAD_AG.POSITIONNAME AS POSITIONNAME_AG,PAD_AG.CUADRO_RRGG_OCASO AS CUADRO_RRGG_AG,
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) AS POLIZ_CORR,
                        SUM(CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) AS ASEGURADOS,
                        --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                        PAD_AG.ID_TIPO_AGENTE AS ID_TIPO_AGENTE_AG,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER1 ELSE 0 END) AS POLIZ_CORR_AG,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER2 ELSE 0 END) AS CORR_TIPO_AGENTE,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER6 ELSE 0 END) AS CORR_CAPTACION
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20180125: Filtramos por los creditos que cuentan polizas corregidas
                        AND (C.VALUE <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                        --Filtramos por el GB3 que marca si el inspector era antes un agente para no tener en cuenta estos creditos
                        --ALM 20170518: Modificamos el filtro para unificar con PEPI y RPI
                        --AND (C.GENERICBOOLEAN3 <> 1 OR C.GENERICBOOLEAN3 IS NULL)
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POS_CALLIDUS
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 101.2
                    --ALM 20160630: Al anadir las Commission de CT hay que filtrar unicamente por las de DIF, para ello necesitamos hacer un inner con cs_incentive
                    LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                            --ALM 20171213: Filtramos para no tener en cuenta las Commission Anuales 
                            AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-O-DIF-%' AND I_DIF.NAME NOT LIKE '%-Anual'
                            WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                    --ALM 20160630: Por las modificaciones en el CT tenemos que usar las Commissions para calcular el CT
                    LEFT OUTER JOIN (SELECT COM_CT.CREDITSEQ,COM_CT.RATEVALUE,COM_CT.VALUE FROM CS_COMMISSION COM_CT 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_CT.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_CT ON COM_CT.INCENTIVESEQ = I_CT.INCENTIVESEQ AND COM_CT.PIPELINERUNSEQ = I_CT.PIPELINERUNSEQ
                                AND I_CT.TENANTID = 'INYC' AND I_CT.PERIODSEQ = v_periodRow.PERIODSEQ AND I_CT.NAME LIKE 'C-O-CT-%' 
                            WHERE COM_CT.TENANTID = 'INYC' AND COM_CT.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) CT ON C.CREDITSEQ = CT.CREDITSEQ 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    --ALM 20160912: Anadimos un filtro para que no se carguen casos en los que los Diferenciales y la Locomocion sea nula
                    --ALM 20170215: Ademas de lo anterior incluimos los creditos que cuentan polizas distintos de 0
                    --ALM 20170301: Ademas de lo anterior incluimos los resultados de la consulta cumplan el resto de filtros o no para los agentes 79
                    --              necesario para el nuevo informe de Produccion Oficina que usa tambien esta tabla
                    WHERE (DIF.VALUE IS NOT NULL OR CT.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79
                            OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0
                            --ALM 20180119: Cogemos tambien los creditos que cuentes pol. corregidas o asegurados
                            OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) <> 0
                            OR (CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) <> 0)
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20170518: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61
                        --              Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                        AND ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                --ALM 20170628: Por peticion de David anadimos los tipos 82
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,ST.CHANNEL,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)),ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,
                        ST.GENERICATTRIBUTE12,PAD_AG.POSITIONNAME,PAD_AG.CUADRO_RRGG_OCASO,ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,PAD_INS.TIPO_AGENTE,
                        --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                        PAD_AG.ID_TIPO_AGENTE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S5_POLIZAS. Creditos: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_BAL_S5_POLIZAS. Pagos Comerciales 2** y 5**.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_S5_POLIZAS 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        SUBSTR(D.EARNINGCODEID,5,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        D.NAME,CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN 0 ELSE D.VALUE END AS VALUE,0 AS COEF_CORR,
                        0 AS PORC_DIFERENCIAL,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '2' THEN D.VALUE ELSE 0 END AS IMP_DIFERENCIAL,
                        0 AS POLIZ_NP,
                        0 AS PORC_LOCOMOCION,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '5' THEN D.VALUE ELSE 0 END AS IMP_LOCOMOCION,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        --ALM 20160914: Para Abril y Mayo los Pagos Comerciales no traen el producto en el EARNINGCODEID sino en el GA1
                        --SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,0 AS PRIMA_NETA,'' AS DURACION,
                        '' AS POSITIONNAME_AG,'' CUADRO_RRGG_AG,
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN
                        --        (SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        --    ELSE ''
                        --END AS EVENTO,
                        --ALM 20160914: Como solo cogemos conceptos 2xx y 5xx ponemos regularizacion a todo.
                        'Regularizacion' AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        0 AS POLIZ_CORR,
                        0 AS ASEGURADOS,
                        --ALM 20230201: Incluimos nuevos campos solicitados para el PAC 2023.
                        '' AS ID_TIPO_AGENTE_AG,
                        0 AS POLIZ_CORR_AG,
                        0 AS CORR_TIPO_AGENTE,
                        0 AS CORR_CAPTACION
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S5% (ej: 04-S5-03)
                        AND D.EARNINGGROUPID LIKE '%S5%'
                        --ALM 20160914: Solo nos quedamos con los Pagos Comerciales que pertenezcan a Diferenciales o Compensacion por Transaporte
                        AND ((D.NAME = 'D-O-Pagos-Fijos' AND SUBSTR(D.EARNINGCODEID,1,1) IN ('2','5')) OR D.NAME LIKE 'DD-O-COLC-Inspector-Pago-00%')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON SUBSTR(D.NAME,1,27) = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 101.2
                    --INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                    --ALM 20160822: Como existen pagos comerciales antiguos en los que el producto venia informado en el GA1 del deposito cambiamos la join
                    --              Necesario para Pagos Comerciales de Abril y Mayo 2016
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON CL.CLASSIFIERID = CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END 
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '01'
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S5_POLIZAS. Pagos Comerciales 2** y 5**: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_S5_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_S5_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_S5_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_BAL_S5_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_S5',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_S5');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_S5',v_contador);
            
            END IF;
        
        END IF;

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;    
     
   
     
    --ALM 20151027: Tabla para el Detalle de Polizas y Productos del S5 de ETERNA
    IF informe = 'S5_E' OR informe LIKE '%,S5_E,%' OR informe LIKE '%,S5_E' OR informe LIKE 'S5_E,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_S5_E_POLIZAS.', v_contador);

            DELETE INYCEXT.INYC_S5_E_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_S5_E_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_S5_E_POLIZAS. Creditos', v_contador);

            INSERT INTO INYCEXT.INYC_S5_E_POLIZAS 
                --ALM 20170215: Modificamos la select para incluir los creditos que cuentan extornos
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_ETERNA,
                    PAD_INS.ID_TIPO_AGENTE,
                    ST.CHANNEL AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --C.NAME,C.VALUE,C.GENERICNUMBER1 AS COEF_CORR,
                    SUBSTR(C.NAME,1,1) || 'C-E-GEN-Inspector-PrimaCorregida' AS NAME,
                    SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END) AS VALUE,
                    SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                    --DIF.RATEVALUE AS PORC_DIFERENCIAL,DIF.VALUE AS IMP_DIFERENCIAL,
                    SUM(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                    --ALM 20160629: Anadimos un campo para contar las Polizas de Nueva Produccion
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) AS POLIZ_NP,
                    0 AS LOCOMOCION,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                    --C.GENERICNUMBER5 AS PRIMA_NETA,
                    SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END) AS PRIMA_NETA,
                    ST.GENERICATTRIBUTE12 AS DURACION,
                    PAD_AG.POSITIONNAME AS POSITIONNAME_AG,PAD_AG.CUADRO_RRGG_ETERNA AS CUADRO_RRGG_AG,
                    ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                    PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) AS POLIZ_CORR,
                    SUM(CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) AS ASEGURADOS
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20180209: Filtramos por los creditos que cuentan polizas corregidas tambien para Eterna
                    --AND C.VALUE <> 0
                    AND (C.VALUE <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                    --Filtramos por el GB3 que marca si el inspector era antes un agente para no tener en cuenta estos creditos
                    --ALM 20170518: Modificamos el filtro para unificar con PEPI y RPI
                    --AND (C.GENERICBOOLEAN3 <> 1 OR C.GENERICBOOLEAN3 IS NULL)
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                --    AND TA.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POS_CALLIDUS
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 103.2
                --ALM 20160915: Modificamos el calculo de diferenciales de Eterna y utilizamos Commission
                LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                            AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-E-DIF-%' 
                        WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                    ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    AND AG.COD_INFORME = 103
                --ALM 20160912: Anadimos un filtro para que no se carguen casos en los que los Diferenciales sea nulos
                --ALM 20170215: Ademas de lo anterior incluimos los creditos que cuentan polizas distintos de 0
                --ALM 20170301: Ademas de lo anterior incluimos los resultados de la consulta cumplan el resto de filtros o no para los agentes 79
                --              necesario para el nuevo informe de Produccion Oficina que usa tambien esta tabla
                WHERE (DIF.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79 
                        OR (CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0
                        --ALM 20180119: Cogemos tambien los creditos que cuentes pol. corregidas o asegurados
                        OR (CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) <> 0
                        OR (CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) <> 0)
                    --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_ETERNA,
                    PAD_INS.ID_TIPO_AGENTE,ST.CHANNEL,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)),ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,
                    ST.GENERICATTRIBUTE12,PAD_AG.POSITIONNAME,PAD_AG.CUADRO_RRGG_ETERNA,ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,PAD_INS.TIPO_AGENTE
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S5_E_POLIZAS. Creditos: '|| to_char(filas) || ' filas.', v_contador);

            w_debug('Inicio Carga INYC_S5_E_POLIZAS.. Pagos Comerciales 2** y 5**', v_contador);

            INSERT INTO INYCEXT.INYC_S5_E_POLIZAS 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_ETERNA,
                    PAD_INS.ID_TIPO_AGENTE,
                    SUBSTR(D.EARNINGCODEID,5,2) AS COMPANIA,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    D.NAME,CASE WHEN D.NAME = 'D-E-Pagos-Fijos' THEN 0 ELSE D.VALUE END AS VALUE,0 AS COEF_CORR,
                    0 AS PORC_DIFERENCIAL,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '2' THEN D.VALUE ELSE 0 END AS IMP_DIFERENCIAL,
                    0 AS POLIZ_NP,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '5' THEN D.VALUE ELSE 0 END AS LOCOMOCION,
                    --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                    SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                    '999999900000000' AS POLIZA,
                    --ALM 20160914: Para Abril y Mayo los Pagos Comerciales no traen el producto en el EARNINGCODEID sino en el GA1
                    --SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                    CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                        THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                    D.DEPOSITDATE AS FEC_CARGO,0 AS PRIMA_NETA,'' AS DURACION,
                    '' AS POSITIONNAME_AG,'' CUADRO_RRGG_AG,
                    --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                    --              depende del concepto de pago.
                    --CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN
                    --        (SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                    --    ELSE ''
                    --END AS EVENTO,
                    --ALM 20160914: Como solo cogemos conceptos 2xx y 5xx ponemos regularizacion a todo.
                    'Regularizacion' AS EVENTO,
                    PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                    '' AS FEC_VTO_REC,
                    PAD_INS.TIPO_AGENTE,
                    --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                    0 AS POLIZ_CORR,
                    0 AS ASEGURADOS
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND D.TENANTID = 'INYC'
                    --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S5% (ej: 04-S5-03)
                    AND D.EARNINGGROUPID LIKE '%S5%'
                    --ALM 20160914: Solo nos quedamos con los Pagos Comerciales que pertenezcan a Diferenciales o Compensacion por Transaporte
                    AND SUBSTR(D.EARNINGCODEID,1,1) IN ('2','5')
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 103.2
                --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                    AND CL.REMOVEDATE = v_eot  
                    AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND CL.TENANTID = 'INYC'
                LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                    AND PROD.REMOVEDATE = v_eot  
                    AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                    AND PROD.TENANTID = 'INYC'
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    AND AG.COD_INFORME = 103
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                    --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                    --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '03'
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_S5_E_POLIZAS. Pagos Comerciales 2** y 5**: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_S5_E_POLIZAS.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_S5_E_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_S5_E_POLIZAS');

            w_debug('Fin Actualizacion Indices INYC_S5_E_POLIZAS.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_S5_E',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_S5_E');
        
            w_debug('Fin actualizacion del parametro INYC_S5_E',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_S5_E_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_LC_S5_E_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_S5_E_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_S5_E_POLIZAS. Creditos', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S5_E_POLIZAS 
                    --ALM 20170215: Modificamos la select para incluir los creditos que cuentan extornos
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.ID_TIPO_AGENTE,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --C.NAME,C.VALUE,C.GENERICNUMBER1 AS COEF_CORR,
                        SUBSTR(C.NAME,1,1) || 'C-E-GEN-Inspector-PrimaCorregida' AS NAME,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END) AS VALUE,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                        --DIF.RATEVALUE AS PORC_DIFERENCIAL,DIF.VALUE AS IMP_DIFERENCIAL,
                        SUM(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                        --ALM 20160629: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) AS POLIZ_NP,
                        0 AS LOCOMOCION,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --C.GENERICNUMBER5 AS PRIMA_NETA,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END) AS PRIMA_NETA,
                        ST.GENERICATTRIBUTE12 AS DURACION,
                        PAD_AG.POSITIONNAME AS POSITIONNAME_AG,PAD_AG.CUADRO_RRGG_ETERNA AS CUADRO_RRGG_AG,
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) AS POLIZ_CORR,
                        SUM(CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20180209: Filtramos por los creditos que cuentan polizas corregidas tambien para Eterna
                        --AND C.VALUE <> 0
                        AND (C.VALUE <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                        --Filtramos por el GB3 que marca si el inspector era antes un agente para no tener en cuenta estos creditos
                        --ALM 20170518: Modificamos el filtro para unificar con PEPI y RPI
                        --AND (C.GENERICBOOLEAN3 <> 1 OR C.GENERICBOOLEAN3 IS NULL)
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POS_CALLIDUS
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 103.2
                    --ALM 20160915: Modificamos el calculo de diferenciales de Eterna y utilizamos Commission
                    LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                                AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-E-DIF-%' 
                            WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 103
                    --ALM 20160912: Anadimos un filtro para que no se carguen casos en los que los Diferenciales sea nulos
                    --ALM 20170215: Ademas de lo anterior incluimos los creditos que cuentan polizas distintos de 0
                    --ALM 20170301: Ademas de lo anterior incluimos los resultados de la consulta cumplan el resto de filtros o no para los agentes 79
                    --              necesario para el nuevo informe de Produccion Oficina que usa tambien esta tabla
                    WHERE (DIF.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79 
                            OR (CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0
                            --ALM 20180119: Cogemos tambien los creditos que cuentes pol. corregidas o asegurados
                            OR (CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) <> 0
                            OR (CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) <> 0)
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.ID_TIPO_AGENTE,ST.CHANNEL,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)),ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,
                        ST.GENERICATTRIBUTE12,PAD_AG.POSITIONNAME,PAD_AG.CUADRO_RRGG_ETERNA,ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,PAD_INS.TIPO_AGENTE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S5_E_POLIZAS. Creditos: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_LC_S5_E_POLIZAS.. Pagos Comerciales 2** y 5**', v_contador);

                INSERT INTO INYCEXT.INYC_LC_S5_E_POLIZAS 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.ID_TIPO_AGENTE,
                        SUBSTR(D.EARNINGCODEID,5,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        D.NAME,CASE WHEN D.NAME = 'D-E-Pagos-Fijos' THEN 0 ELSE D.VALUE END AS VALUE,0 AS COEF_CORR,
                        0 AS PORC_DIFERENCIAL,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '2' THEN D.VALUE ELSE 0 END AS IMP_DIFERENCIAL,
                        0 AS POLIZ_NP,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '5' THEN D.VALUE ELSE 0 END AS LOCOMOCION,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        --ALM 20160914: Para Abril y Mayo los Pagos Comerciales no traen el producto en el EARNINGCODEID sino en el GA1
                        --SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,0 AS PRIMA_NETA,'' AS DURACION,
                        '' AS POSITIONNAME_AG,'' CUADRO_RRGG_AG,
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN
                        --        (SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        --    ELSE ''
                        --END AS EVENTO,
                        --ALM 20160914: Como solo cogemos conceptos 2xx y 5xx ponemos regularizacion a todo.
                        'Regularizacion' AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        0 AS POLIZ_CORR,
                        0 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S5% (ej: 04-S5-03)
                        AND D.EARNINGGROUPID LIKE '%S5%'
                        --ALM 20160914: Solo nos quedamos con los Pagos Comerciales que pertenezcan a Diferenciales o Compensacion por Transaporte
                        AND SUBSTR(D.EARNINGCODEID,1,1) IN ('2','5')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 103.2
                    --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                    --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 103
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '03'
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_S5_E_POLIZAS. Pagos Comerciales 2** y 5**: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_S5_E_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_S5_E_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_S5_E_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_LC_S5_E_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_S5_E',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_S5_E');
            
                w_debug('Fin actualizacion del parametro INYC_LC_S5_E',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_S5_E_POLIZAS.', v_contador);

                DELETE INYCEXT.INYC_BAL_S5_E_POLIZAS WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_S5_E_POLIZAS: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_S5_E_POLIZAS. Creditos', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_S5_E_POLIZAS 
                    --ALM 20170215: Modificamos la select para incluir los creditos que cuentan extornos
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.ID_TIPO_AGENTE,
                        ST.CHANNEL AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --C.NAME,C.VALUE,C.GENERICNUMBER1 AS COEF_CORR,
                        SUBSTR(C.NAME,1,1) || 'C-E-GEN-Inspector-PrimaCorregida' AS NAME,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END) AS VALUE,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                        --DIF.RATEVALUE AS PORC_DIFERENCIAL,DIF.VALUE AS IMP_DIFERENCIAL,
                        SUM(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                        --ALM 20160629: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) AS POLIZ_NP,
                        0 AS LOCOMOCION,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1 AS POLIZA,ST.PRODUCTID,ST.ACCOUNTINGDATE AS FEC_CARGO,
                        --C.GENERICNUMBER5 AS PRIMA_NETA,
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END) AS PRIMA_NETA,
                        ST.GENERICATTRIBUTE12 AS DURACION,
                        PAD_AG.POSITIONNAME AS POSITIONNAME_AG,PAD_AG.CUADRO_RRGG_ETERNA AS CUADRO_RRGG_AG,
                        ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        SUM(CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) AS POLIZ_CORR,
                        SUM(CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20180209: Filtramos por los creditos que cuentan polizas corregidas tambien para Eterna
                        --AND C.VALUE <> 0
                        AND (C.VALUE <> 0 OR (C.GENERICNUMBER4 <> 0 AND C.NAME LIKE '%Polizas%'))
                        --Filtramos por el GB3 que marca si el inspector era antes un agente para no tener en cuenta estos creditos
                        --ALM 20170518: Modificamos el filtro para unificar con PEPI y RPI
                        --AND (C.GENERICBOOLEAN3 <> 1 OR C.GENERICBOOLEAN3 IS NULL)
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POS_CALLIDUS
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 103.2
                    --ALM 20160915: Modificamos el calculo de diferenciales de Eterna y utilizamos Commission
                    LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                                AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-E-DIF-%' 
                            WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 103
                    --ALM 20160912: Anadimos un filtro para que no se carguen casos en los que los Diferenciales sea nulos
                    --ALM 20170215: Ademas de lo anterior incluimos los creditos que cuentan polizas distintos de 0
                    --ALM 20170301: Ademas de lo anterior incluimos los resultados de la consulta cumplan el resto de filtros o no para los agentes 79
                    --              necesario para el nuevo informe de Produccion Oficina que usa tambien esta tabla
                    WHERE (DIF.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79 
                            OR (CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0
                            --ALM 20180119: Cogemos tambien los creditos que cuentes pol. corregidas o asegurados
                            OR (CASE WHEN C.NAME LIKE '%C-E-GEN-Inspector-NumeroPolizas-%' THEN C.GENERICNUMBER4 ELSE 0 END) <> 0
                            OR (CASE WHEN C.NAME LIKE '%-NumAsegurados%' THEN C.VALUE ELSE 0 END) <> 0)
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.ID_TIPO_AGENTE,ST.CHANNEL,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)),ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,
                        ST.GENERICATTRIBUTE12,PAD_AG.POSITIONNAME,PAD_AG.CUADRO_RRGG_ETERNA,ST.EVENTO,ST.PRODUCTO,ST.FEC_VTO_REC,PAD_INS.TIPO_AGENTE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S5_E_POLIZAS. Creditos: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_BAL_S5_E_POLIZAS.. Pagos Comerciales 2** y 5**', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_S5_E_POLIZAS 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.ID_TIPO_AGENTE,
                        SUBSTR(D.EARNINGCODEID,5,2) AS COMPANIA,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        D.NAME,CASE WHEN D.NAME = 'D-E-Pagos-Fijos' THEN 0 ELSE D.VALUE END AS VALUE,0 AS COEF_CORR,
                        0 AS PORC_DIFERENCIAL,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '2' THEN D.VALUE ELSE 0 END AS IMP_DIFERENCIAL,
                        0 AS POLIZ_NP,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,1,1) = '5' THEN D.VALUE ELSE 0 END AS LOCOMOCION,
                        --ALM 20160907: Como este campo no usa para Pagos Comerciales devolvemos el concepto de pago para utilizarlo en el informe
                        SUBSTR(D.EARNINGCODEID,1,3) AS SALESTRANSACTIONSEQ,
                        '999999900000000' AS POLIZA,
                        --ALM 20160914: Para Abril y Mayo los Pagos Comerciales no traen el producto en el EARNINGCODEID sino en el GA1
                        --SUBSTR(D.EARNINGCODEID,5,7) AS PRODUCTID,
                        CASE WHEN SUBSTR(D.EARNINGCODEID,5,7) IS NOT NULL 
                            THEN SUBSTR(D.EARNINGCODEID,5,7) ELSE D.GENERICATTRIBUTE1 END AS PRODUCTID,
                        D.DEPOSITDATE AS FEC_CARGO,0 AS PRIMA_NETA,'' AS DURACION,
                        '' AS POSITIONNAME_AG,'' CUADRO_RRGG_AG,
                        --ALM 20160914: Segun el correo de Alfonso del 06/09/2016 17:30 el tipo de recibo (EVENTO) de los pagos comerciales
                        --              depende del concepto de pago.
                        --CASE WHEN D.NAME = 'D-O-Pagos-Fijos' THEN
                        --        (SELECT ET.DESCRIPTION FROM TCMP.CS_EVENTTYPE ET WHERE ET.EVENTTYPEID = 'Pago Comercial' AND ET.REMOVEDATE = v_eot)
                        --    ELSE ''
                        --END AS EVENTO,
                        --ALM 20160914: Como solo cogemos conceptos 2xx y 5xx ponemos regularizacion a todo.
                        'Regularizacion' AS EVENTO,
                        PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        '' AS FEC_VTO_REC,
                        PAD_INS.TIPO_AGENTE,
                        --ALM 20180119: Anadimos campos a incluir para el PAC 2018
                        0 AS POLIZ_CORR,
                        0 AS ASEGURADOS
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = D.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND D.TENANTID = 'INYC'
                        --ALM 20160704: Solo nos quedamos con los Pagos Comerciales que tengan EarningGroup %S5% (ej: 04-S5-03)
                        AND D.EARNINGGROUPID LIKE '%S5%'
                        --ALM 20160914: Solo nos quedamos con los Pagos Comerciales que pertenezcan a Diferenciales o Compensacion por Transaporte
                        AND SUBSTR(D.EARNINGCODEID,1,1) IN ('2','5')
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON D.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 103.2
                    --ALM 20160701: Utilizamos un INNER porque si el Pago Comercial viene sin producto no queremos que aparezca en el detalle (correo Javier 21/06)
                    --              Unimos por el Producto que vendra en el EARNINGCODEID (ej: 101-0121000)
                    INNER JOIN TCMP.CS_CLASSIFIER CL ON SUBSTR(D.EARNINGCODEID,5,7) = CL.CLASSIFIERID
                        AND CL.REMOVEDATE = v_eot  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = v_eot  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 103
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                        --ALM 20160617: Pueden llegar Pagos Comerciales sin Producto
                        --No es necesario filtrar por la compania porque el Deposito ya lo distingue (D-O-Pagos-Fijos o D-E-Pagos-Fijos)
                        --AND SUBSTR(D.GENERICATTRIBUTE1,1,2) = '03'
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_S5_E_POLIZAS. Pagos Comerciales 2** y 5**: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_S5_E_POLIZAS.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_S5_E_POLIZAS COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_S5_E_POLIZAS');

                w_debug('Fin Actualizacion Indices INYC_BAL_S5_E_POLIZAS.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_S5_E',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_S5_E');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_S5_E',v_contador);
            
            END IF;
        
        END IF;

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --ALM 20151027: Tabla para el Informe de Percepciones Emitidas Provisionales de Agentes OCASO Resumen
    IF informe = 'PEPA' OR informe LIKE '%,PEPA,%' OR informe LIKE '%,PEPA' OR informe LIKE 'PEPA,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_PEPA_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_PEPA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_PEPA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_PEPA_RESUMEN. Percepciones.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    PERC.DESCRIPCION AS COMISION,D.VALUE AS IMPORTE,
                    (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS PERIODO_DEPOSITO,                
                    '' AS N_MEDIDA,0 AS V_MEDIDA,
                    D.EARNINGCODEID,D.EARNINGGROUPID
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                    AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                            AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                            AND PD.STARTDATE <= PAD_INS.STARTDATE
                                            --Filtramos por el tipo de periodo para quedarnos solo los meses
                                            AND PD.PERIODTYPESEQ = 2814749767106561)
                    AND D.TENANTID = 'INYC'
                    --AND D.VALUE <> 0
                    AND SUBSTR(D.EARNINGGROUPID,7,2) = '01'
                    --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                    AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                    --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                    AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                --    AND AG.COD_INFORME = 104
                --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;

            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_RESUMEN. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_PEPA_RESUMEN. Balances.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ AS POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    --ALM 20170526: Introduccimos el mes del que proviene el balance
                    --'Regularizacion meses anteriores ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                    'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                    B.VALUE AS IMPORTE,
                    EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                    'Balance' AS N_MEDIDA,0 AS V_MEDIDA,
                    B.EARNINGCODEID,B.EARNINGGROUPID
                --ALM 20170523: Modificamos la carga para coger la jerarquia del mes en ejecucion no la de cuando se realizo el balance
                --FROM TCMP.CSA_PADIMENSION PAD_INS
                --INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD_INS.PERIODSEQ = PD.PERIODSEQ AND PD.TENANTID = 'INYC'
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
                INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                    --ALM 20170516: No filtramos por el PERIODSEQ de los balances sino por las fechas de posteado para aplicarlos a un mes u otro
                    --AND B.PERIODSEQ IN (SELECT PER.PERIODSEQ FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    --                        AND SUBSTR(PER.NAME,-4) = SUBSTR(PD.NAME,-4)
                    --                        AND PER.STARTDATE <= PD.STARTDATE
                    --                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                    --                        AND PER.PERIODTYPESEQ = 2814749767106561)
                    AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                    AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                    AND B.TENANTID = 'INYC'
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND B.PROCESSINGUNITSEQ = 38280596832649217
                    --AND D.VALUE <> 0
                    AND SUBSTR(B.EARNINGGROUPID,7,2) = '01'
                    --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                    AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S4'
                    --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                    AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
                --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
                --ALM 20211126: Comentamos estas inner porque provocan errores en el proceso para el cierre de noviembre 2021.
                /*
                INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                    AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
                INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
                */
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot 
                --ALM 20170427: No podemos unir con las percepciones porque no podemos diferenciar entre depositos del mismo earningcode y earninggroup
                --INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                --    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                --    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --ALM 20170427: Para los balances no filtramos por tipologias porque pueden haber cambiado. Devolvemos todos los balances.
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.POSITIONGENERICNUMBER2 = AG.ID_TIPO_AGENTE
                --    AND AG.COD_INFORME = 104
                --    AND AG.F_INICIO <= PD.STARTDATE AND  AG.F_FIN > PD.STARTDATE
                --ALM 20170427: Filtramos por el periodo anterior al atual
                --ALM 20170523: No hace falta filtrar porque ya viene filtrada la tabla temporal principal por el periodo actual
                --WHERE PAD_INS.PERIODSEQ = (SELECT MAX(PER.PERIODSEQ) FROM TCMP.CS_PERIOD PER
                --                            INNER JOIN TCMP.CS_PERIODTYPE PT ON PER.PERIODTYPESEQ = PT.PERIODTYPESEQ AND PT.REMOVEDATE = v_eot
                --                            WHERE PER.REMOVEDATE = v_eot AND PT.NAME = 'month' AND PER.PERIODSEQ < v_periodRow.PERIODSEQ)
                ;

            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_RESUMEN. Balances: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_PEPA_RESUMEN. Medidas Agentes.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_RESUMEN
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    '' AS COMISION,0 AS IMPORTE,0 AS IMPORTE_ACUMULADO,
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                    '' AS EARNINGCODEID,'' AS EARNINGGROUPID
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = M.PERIODSEQ 
                    AND M.TENANTID = 'INYC'
                    AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 104.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                --    AND AG.COD_INFORME = 104
                --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_RESUMEN. Medidas Agente: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Carga INYC_PEPA_RESUMEN. DERECHOS ECONOMICOS', v_contador);
 
            INSERT INTO INYCEXT.INYC_PEPA_RESUMEN
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,
                    PAD_INS.SUPERRAPEL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    'Comisiones Cartera DDEE' AS COMISION,
                    SUM(CAR_LP.IMPORTE) AS IMPORTE,
                    EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                    '' AS N_MEDIDA,
                    0 AS V_MEDIDA,
                    CAR_LP.EARNINGCODEID,
                    CAR_LP.EARNINGGROUPID
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME  AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                    AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                    --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                    AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                    --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                    AND CAR_LP.IMPORTE <> 0
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                WHERE Y.POSITIONSEQ IS NULL
                GROUP BY
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX), 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,
                    PAD_INS.SUPERRAPEL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END,
                    EXTRACT(MONTH FROM PAD_INS.STARTDATE),                
                    CAR_LP.EARNINGCODEID,
                    CAR_LP.EARNINGGROUPID;
                    
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_PEPA_RESUMEN. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                
            --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
            --END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_PEPA_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PEPA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PEPA_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_PEPA_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_PEPA_RESUMEN',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_PEPA_RESUMEN');
        
            w_debug('Fin actualizacion del parametro INYC_PEPA_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_PEPA_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_PEPA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_PEPA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_PEPA_RESUMEN. Percepciones.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PERC.DESCRIPCION AS COMISION,D.VALUE AS IMPORTE,
                        (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS PERIODO_DEPOSITO,                
                        '' AS N_MEDIDA,0 AS V_MEDIDA,
                        D.EARNINGCODEID,D.EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                        AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                                AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                                AND PD.STARTDATE <= PAD_INS.STARTDATE
                                                --Filtramos por el tipo de periodo para quedarnos solo los meses
                                                AND PD.PERIODTYPESEQ = 2814749767106561)
                        AND D.TENANTID = 'INYC'
                        --AND D.VALUE <> 0
                        AND SUBSTR(D.EARNINGGROUPID,7,2) = '01'
                        --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                        AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                        --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                        AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                        AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                        AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 104
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPA_RESUMEN. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_PEPA_RESUMEN. Balances.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ AS POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20170526: Introduccimos el mes del que proviene el balance
                        --'Regularizacion meses anteriores ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                        'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                            AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                        B.VALUE AS IMPORTE,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                        'Balance' AS N_MEDIDA,0 AS V_MEDIDA,
                        B.EARNINGCODEID,B.EARNINGGROUPID
                    --ALM 20170523: Modificamos la carga para coger la jerarquia del mes en ejecucion no la de cuando se realizo el balance
                    --FROM TCMP.CSA_PADIMENSION PAD_INS
                    --INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD_INS.PERIODSEQ = PD.PERIODSEQ AND PD.TENANTID = 'INYC'
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
                    INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                        --ALM 20170516: No filtramos por el PERIODSEQ de los balances sino por las fechas de posteado para aplicarlos a un mes u otro
                        --AND B.PERIODSEQ IN (SELECT PER.PERIODSEQ FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        --                        AND SUBSTR(PER.NAME,-4) = SUBSTR(PD.NAME,-4)
                        --                        AND PER.STARTDATE <= PD.STARTDATE
                        --                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                        --                        AND PER.PERIODTYPESEQ = 2814749767106561)
                        AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                            AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                        AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                            AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                        AND B.TENANTID = 'INYC'
                        --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                        AND B.PROCESSINGUNITSEQ = 38280596832649217
                        --AND D.VALUE <> 0
                        AND SUBSTR(B.EARNINGGROUPID,7,2) = '01'
                        --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                        AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S4'
                        --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                        AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
                    --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
                    INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                    AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
                    INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                        AND EC.TENANTID = 'INYC'
                        AND EC.REMOVEDATE = v_eot 
                    --ALM 20170427: No podemos unir con las percepciones porque no podemos diferenciar entre depositos del mismo earningcode y earninggroup
                    --INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                    --    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                    --    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170427: Para los balances no filtramos por tipologias porque pueden haber cambiado. Devolvemos todos los balances.
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.POSITIONGENERICNUMBER2 = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 104
                    --    AND AG.F_INICIO <= PD.STARTDATE AND  AG.F_FIN > PD.STARTDATE
                    --ALM 20170427: Filtramos por el periodo anterior al atual
                    --ALM 20170523: No hace falta filtrar porque ya viene filtrada la tabla temporal principal por el periodo actual
                    --WHERE PAD_INS.PERIODSEQ = (SELECT MAX(PER.PERIODSEQ) FROM TCMP.CS_PERIOD PER
                    --                            INNER JOIN TCMP.CS_PERIODTYPE PT ON PER.PERIODTYPESEQ = PT.PERIODTYPESEQ AND PT.REMOVEDATE = v_eot
                    --                            WHERE PER.REMOVEDATE = v_eot AND PT.NAME = 'month' AND PER.PERIODSEQ < v_periodRow.PERIODSEQ)
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPA_RESUMEN. Balances: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_PEPA_RESUMEN. Medidas Agentes.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_RESUMEN
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        '' AS COMISION,0 AS IMPORTE,0 AS IMPORTE_ACUMULADO,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        '' AS EARNINGCODEID,'' AS EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = M.PERIODSEQ 
                        AND M.TENANTID = 'INYC'
                        AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 104.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 104
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPA_RESUMEN. Medidas Agente: '|| to_char(filas) || ' filas.', v_contador);
            
            
                w_debug('Inicio Carga INYC_LC_PEPA_RESUMEN. DERECHOS ECONOMICOS', v_contador);
     
                INSERT INTO INYCEXT.INYC_LC_PEPA_RESUMEN
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,
                        PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        'Comisiones Cartera DDEE' AS COMISION,
                        SUM(CAR_LP.IMPORTE) AS IMPORTE,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                        '' AS N_MEDIDA,
                        0 AS V_MEDIDA,
                        CAR_LP.EARNINGCODEID,
                        CAR_LP.EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME  AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                        AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        AND CAR_LP.ESTADO = 'C'
                        --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                    GROUP BY
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX), 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,
                        PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE),                
                        CAR_LP.EARNINGCODEID,
                        CAR_LP.EARNINGGROUPID;
                        
                filas := sql%rowcount;            
                COMMIT;           
                        
                w_debug('Fin Carga INYC_LC_PEPA_RESUMEN. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_PEPA_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_PEPA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_PEPA_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_PEPA_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_PEPA_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_PEPA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_PEPA_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_PEPA_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_PEPA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_PEPA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_PEPA_RESUMEN. Percepciones.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_PEPA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PERC.DESCRIPCION AS COMISION,D.VALUE AS IMPORTE,
                        (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS PERIODO_DEPOSITO,                
                        '' AS N_MEDIDA,0 AS V_MEDIDA,
                        D.EARNINGCODEID,D.EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                        AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                                AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                                AND PD.STARTDATE <= PAD_INS.STARTDATE
                                                --Filtramos por el tipo de periodo para quedarnos solo los meses
                                                AND PD.PERIODTYPESEQ = 2814749767106561)
                        AND D.TENANTID = 'INYC'
                        --AND D.VALUE <> 0
                        AND SUBSTR(D.EARNINGGROUPID,7,2) = '01'
                        --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                        AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                        --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                        AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                        AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                        AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 104
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_PEPA_RESUMEN. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
                
                
                
                w_debug('Inicio Carga INYC_BAL_PEPA_RESUMEN. Medidas Agentes.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_PEPA_RESUMEN
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        '' AS COMISION,0 AS IMPORTE,0 AS IMPORTE_ACUMULADO,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        '' AS EARNINGCODEID,'' AS EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = M.PERIODSEQ 
                        AND M.TENANTID = 'INYC'
                        AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 104.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 104
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_PEPA_RESUMEN. Medidas Agente: '|| to_char(filas) || ' filas.', v_contador);
            
            
                w_debug('Inicio Carga INYC_BAL_PEPA_RESUMEN. DERECHOS ECONOMICOS', v_contador);
     
                INSERT INTO INYCEXT.INYC_BAL_PEPA_RESUMEN
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,
                        PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        'Comisiones Cartera DDEE' AS COMISION,
                        SUM(CAR_LP.IMPORTE) AS IMPORTE,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                        '' AS N_MEDIDA,
                        0 AS V_MEDIDA,
                        CAR_LP.EARNINGCODEID,
                        CAR_LP.EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME  AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                        AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        AND CAR_LP.ESTADO = 'C'
                        --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '01'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                    GROUP BY
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX), 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,
                        PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE),                
                        CAR_LP.EARNINGCODEID,
                        CAR_LP.EARNINGGROUPID;
                        
                filas := sql%rowcount;            
                COMMIT;           
                        
                w_debug('Fin Carga INYC_BAL_PEPA_RESUMEN. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_PEPA_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_PEPA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_PEPA_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_PEPA_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_PEPA_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_PEPA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_PEPA_RESUMEN',v_contador);
            
            END IF;
        
        END IF;        

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --Carga tabla para el Informe de Percepciones Emitidas Provisionales de Agentes OCASO Detalle
    --ALM 20180119: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'PEPA' OR informe like '%,PEPA,%' OR informe like '%,PEPA' OR informe like 'PEPA,%' OR informe = 'ALL' THEN
    IF informe = 'PEPA_DETALLE' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_PEPA_DETALLE.', v_contador);

            DELETE INYCEXT.INYC_PEPA_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_PEPA_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_PEPA_DETALLE. Medidas Agente.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_DETALLE 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    C.NAME,
                    --ALM 20161006: Para los creditos de polizas de recuperadas y renovaciones incluimos en el valor de la prima
                    --ALM 20170313: Por peticion de alfonso devolvemos en valor de los creditos para todos los casos tal y como esta
                    --CASE WHEN C.NAME like 'DC-O-GEN-Agente-NumeroPolizas-998-Re%' THEN C.GENERICNUMBER5 ELSE C.VALUE END AS VALUE,
                    C.VALUE,
                    C.GENERICNUMBER4 AS C_GN1,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                    ST.EVENTO,
                    CT.DESCRIPTION AS TIPO_CREDITO,
                    ST.PRODUCTO,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 POSITIONNAME_AG,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    ----ALM 20160928: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas
                    --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    --ALM 20170407: Filtramos por los creditos de agente
                    AND C.NAME LIKE 'DC-O-GEN-Agente-%'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 104.2
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                    AND CT.REMOVEDATE = v_eot
                    AND CT.TENANTID = 'INYC'
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 104
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170405: Filtramos por las tipologias de agentes
                    AND AG.ID_TIPO_AGENTE < 50
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_DETALLE. Medidas Agente: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_PEPA_DETALLE. Medidas Agente con Grupo.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_DETALLE 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                    PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    C.NAME,
                    --ALM 20161006: Para los creditos de polizas de recuperadas y renovaciones incluimos en el valor de la prima
                    --ALM 20170313: Por peticion de alfonso devolvemos en valor de los creditos para todos los casos tal y como esta
                    --CASE WHEN C.NAME like 'DC-O-GEN-Agente-NumeroPolizas-998-Re%' THEN C.GENERICNUMBER5 ELSE C.VALUE END AS VALUE,
                    C.VALUE,
                    C.GENERICNUMBER4 AS C_GN1,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                    ST.EVENTO,
                    CT.DESCRIPTION AS TIPO_CREDITO,
                    ST.PRODUCTO,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 POSITIONNAME_AG,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    ----ALM 20160928: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas
                    --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    --ALM 20170407: Filtramos por los creditos de agente con grupo
                    AND C.NAME LIKE 'DC-O-GEN-Inspector-%'
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 104.2
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                    AND CT.REMOVEDATE = v_eot
                    AND CT.TENANTID = 'INYC'
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 104
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170405: Filtramos por las tipologias de agentes con grupo
                    AND AG.ID_TIPO_AGENTE >= 50
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_DETALLE. Medidas Agente con Grupo: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_PEPA_DETALLE.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PEPA_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PEPA_DETALLE');

            w_debug('Fin Actualizacion Indices INYC_PEPA_DETALLE.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_PEPA_DETALLE',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_PEPA_DETALLE');
        
            w_debug('Fin actualizacion del parametro INYC_PEPA_DETALLE',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_PEPA_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_LC_PEPA_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_PEPA_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_PEPA_DETALLE. Medidas Agente.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_RRGG_OCASO,PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
