                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 105
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_PEPI_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_PEPI_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_PEPI_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_PEPI_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_PEPI_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_PEPI_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_PEPI_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_PEPI_RESUMEN',v_contador);
            
            END IF;
        
        END IF;

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --Carga tabla para el Informe de Percepciones Emitidas Provisionales de Inspectores OCASO Detalle
    --ALM 20180119: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'PEPI' OR informe like '%,PEPI,%' OR informe like '%,PEPI' OR informe like 'PEPI,%' OR informe = 'ALL' THEN
    IF informe = 'PEPI_DETALLE' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_PEPI_DETALLE.', v_contador);

            DELETE INYCEXT.INYC_PEPI_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_PEPI_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_PEPI_DETALLE.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPI_DETALLE 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                    PAD_INS.CUADRO_INSP_OCASO,                
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                    ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                    ST.EVENTO,
                    CT.DESCRIPTION AS TIPO_CREDITO,
                    ST.PRODUCTO,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 POSITIONNAME_AG,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    C.GENERICNUMBER5 AS C_GN5
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    --ALM 20161004: Filtramos los creditos que tengan el valor y la prima neta a 0, sino no coinciden con las medidas de Prima
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER5 <> 0)
                    --ALM 20161004: Filtramos para no tener en cuenta los creditos directos que pertenecen a inspectores que 
                    --              cuando emitieron la poliza eran agentes
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                LEFT JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 105.2
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                    AND CT.REMOVEDATE = v_eot
                    AND CT.TENANTID = 'INYC'
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 105
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --ALM 20161003: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61 porque no aparecen en el Resumen
                --ALM 20170323: Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                --WHERE (PAD_INS.ID_TIPO_AGENTE in (57,61) OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                            --ALM 20170628: Por peticion de David anadimos los tipos 82
                            AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                        OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPI_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_PEPI_DETALLE.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PEPI_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PEPI_DETALLE');

            w_debug('Fin Actualizacion Indices INYC_PEPI_DETALLE.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_PEPI_DETALLE',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_PEPI_DETALLE');
        
            w_debug('Fin actualizacion del parametro INYC_PEPI_DETALLE',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_PEPI_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_LC_PEPI_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_PEPI_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_PEPI_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPI_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_OCASO,                
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        C.GENERICNUMBER5 AS C_GN5
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161004: Filtramos los creditos que tengan el valor y la prima neta a 0, sino no coinciden con las medidas de Prima
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER5 <> 0)
                        --ALM 20161004: Filtramos para no tener en cuenta los creditos directos que pertenecen a inspectores que 
                        --              cuando emitieron la poliza eran agentes
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    LEFT JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 105.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 105
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20161003: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61 porque no aparecen en el Resumen
                    --ALM 20170323: Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                    --WHERE (PAD_INS.ID_TIPO_AGENTE in (57,61) OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                --ALM 20170628: Por peticion de David anadimos los tipos 82
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPI_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_PEPI_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_PEPI_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_PEPI_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_LC_PEPI_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_PEPI_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_PEPI_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_LC_PEPI_DETALLE',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_PEPI_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_BAL_PEPI_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_PEPI_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_PEPI_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_PEPI_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_OCASO,                
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        C.GENERICNUMBER5 AS C_GN5
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        --ALM 20161004: Filtramos los creditos que tengan el valor y la prima neta a 0, sino no coinciden con las medidas de Prima
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER5 <> 0)
                        --ALM 20161004: Filtramos para no tener en cuenta los creditos directos que pertenecen a inspectores que 
                        --              cuando emitieron la poliza eran agentes
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    LEFT JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 105.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 105
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20161003: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 82 y 61 porque no aparecen en el Resumen
                    --ALM 20170323: Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                    --WHERE (PAD_INS.ID_TIPO_AGENTE in (57,61) OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                --ALM 20170628: Por peticion de David anadimos los tipos 82
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_PEPI_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_PEPI_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_PEPI_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_PEPI_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_PEPI_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_PEPI_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_PEPI_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_PEPI_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --ALM 20151027: Tabla para el Informe de Percepciones Emitidas Provisionales de Agentes ETERNA Resumen
    IF informe = 'PEPA_E' OR informe LIKE '%,PEPA_E,%' OR informe LIKE '%,PEPA_E' OR informe LIKE 'PEPA_E,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_PEPA_E_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_PEPA_E_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_PEPA_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_PEPA_E_RESUMEN. Percepciones.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_E_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    PERC.DESCRIPCION AS COMISION,D.VALUE AS IMPORTE,
                    (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS PERIODO_DEPOSITO,
                    '' AS N_MEDIDA,0 AS V_MEDIDA,
                    D.EARNINGCODEID,D.EARNINGGROUPID
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                    AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                            AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                            AND PD.STARTDATE <= PAD_INS.STARTDATE
                                            --Filtramos por el tipo de periodo para quedarnos solo los meses
                                            AND PD.PERIODTYPESEQ = 2814749767106561)
                    AND D.TENANTID = 'INYC'
                    --AND D.VALUE <> 0
                    AND SUBSTR(D.EARNINGGROUPID,7,2) = '03'
                    --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                    AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                    --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                    AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                --    AND AG.COD_INFORME = 106
                --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;

            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_E_RESUMEN. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_PEPA_E_RESUMEN. Balances.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_E_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ AS POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                    PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    --ALM 20170526: Introduccimos el mes del que proviene el balance
                    --'Regularizacion meses anteriores ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                    'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                    B.VALUE AS IMPORTE,
                    EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                    'Balance' AS N_MEDIDA,0 AS V_MEDIDA,
                    B.EARNINGCODEID,B.EARNINGGROUPID
                --ALM 20170523: Modificamos la carga para coger la jerarquia del mes en ejecucion no la de cuando se realizo el balance
                --FROM TCMP.CSA_PADIMENSION PAD_INS
                --INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD_INS.PERIODSEQ = PD.PERIODSEQ AND PD.TENANTID = 'INYC'
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
                INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                    --ALM 20170516: No filtramos por el PERIODSEQ de los balances sino por las fechas de posteado para aplicarlos a un mes u otro
                    --AND B.PERIODSEQ IN (SELECT PER.PERIODSEQ FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                    --                        AND SUBSTR(PER.NAME,-4) = SUBSTR(PD.NAME,-4)
                    --                        AND PER.STARTDATE <= PD.STARTDATE
                    --                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                    --                        AND PER.PERIODTYPESEQ = 2814749767106561)
                    AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                    AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                    AND B.TENANTID = 'INYC'
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND B.PROCESSINGUNITSEQ = 38280596832649217
                    --AND D.VALUE <> 0
                    AND SUBSTR(B.EARNINGGROUPID,7,2) = '03'
                    --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                    AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S4'
                    --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                    AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
                --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
                INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                    --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                    AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                    AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
                INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
                INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                    AND EC.TENANTID = 'INYC'
                    AND EC.REMOVEDATE = v_eot 
                --ALM 20170427: No podemos unir con las percepciones porque no podemos diferenciar entre depositos del mismo earningcode y earninggroup
                --INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                --    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                --    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --ALM 20170427: Para los balances no filtramos por tipologias porque pueden haber cambiado. Devolvemos todos los balances.
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.POSITIONGENERICNUMBER2 = AG.ID_TIPO_AGENTE
                --    AND AG.COD_INFORME = 104
                --    AND AG.F_INICIO <= PD.STARTDATE AND  AG.F_FIN > PD.STARTDATE
                --ALM 20170427: Filtramos por el periodo anterior al atual
                --ALM 20170523: No hace falta filtrar porque ya viene filtrada la tabla temporal principal por el periodo actual
                --WHERE PAD_INS.PERIODSEQ = (SELECT MAX(PER.PERIODSEQ) FROM TCMP.CS_PERIOD PER
                --                            INNER JOIN TCMP.CS_PERIODTYPE PT ON PER.PERIODTYPESEQ = PT.PERIODTYPESEQ AND PT.REMOVEDATE = v_eot
                --                            WHERE PER.REMOVEDATE = v_eot AND PT.NAME = 'month' AND PER.PERIODSEQ < v_periodRow.PERIODSEQ)
                ;

            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_E_RESUMEN. Balances: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_PEPA_E_RESUMEN. Medidas.', v_contador);

            INSERT INTO INYCEXT.INYC_PEPA_E_RESUMEN
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                    --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                    --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                    --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                    --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                    --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                    --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    '' AS COMISION,0 AS IMPORTE,0 AS IMPORTE_ACUMULADO,
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                    '' AS EARNINGCODEID,'' AS EARNINGGROUPID
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    AND PAD_INS.PERIODSEQ = M.PERIODSEQ 
                    AND M.TENANTID = 'INYC'
                    AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 106.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                --    AND AG.COD_INFORME = 106
                --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_PEPA_E_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Carga INYC_PEPA_E_RESUMEN. DERECHOS ECONOMICOS', v_contador);
 
            INSERT INTO INYCEXT.INYC_PEPA_E_RESUMEN
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,
                    PAD_INS.SUPERRAPEL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END AS COD_SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END AS SUCURSAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END AS COD_REGIONAL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END AS REGIONAL,
                    'Comisiones Cartera DDEE' AS COMISION,
                    SUM(CAR_LP.IMPORTE) AS IMPORTE,
                    EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                    '' AS N_MEDIDA,
                    0 AS V_MEDIDA,
                    CAR_LP.EARNINGCODEID,
                    CAR_LP.EARNINGGROUPID
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME  AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                    AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                    AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                    --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                    AND (v_FV_EstadoTrx = 0 OR (v_FV_EstadoTrx = 1 AND CAR_LP.ESTADO = 'C'))
                    --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                    AND CAR_LP.IMPORTE <> 0   
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'                    
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                    AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                    AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                    AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                WHERE Y.POSITIONSEQ IS NULL
                GROUP BY
                    PAD_INS.PARTICIPANTSEQ,
                    PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,
                    PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,
                    PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX), 
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_INS.TIPO_AGENTE,
                    PAD_INS.CUADRO_RRGG_OCASO,
                    PAD_INS.CUADRO_RRTT_OCASO,
                    PAD_INS.PROMOCION,
                    PAD_INS.SUPERRAPEL,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                        ELSE PAD_PTO_VENTA.POSITIONNAME END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                        ELSE PAD_PTO_VENTA.LASTNAME END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                            ELSE PAD_PTO_VENTA.POSITIONNAME END 
                    END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                            ELSE PAD_PTO_VENTA.LASTNAME END 
                    END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END
                    END END,
                    CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                        ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END
                    END END,
                    EXTRACT(MONTH FROM PAD_INS.STARTDATE),                
                    CAR_LP.EARNINGCODEID,
                    CAR_LP.EARNINGGROUPID;
                    
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_PEPA_E_RESUMEN. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                
            --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
            --END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_PEPA_E_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PEPA_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PEPA_E_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_PEPA_E_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_PEPA_E_RESUMEN',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_PEPA_E_RESUMEN');
        
            w_debug('Fin actualizacion del parametro INYC_PEPA_E_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_PEPA_E_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_PEPA_E_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_PEPA_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_PEPA_E_RESUMEN. Percepciones.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        PERC.DESCRIPCION AS COMISION,D.VALUE AS IMPORTE,
                        (SELECT EXTRACT(MONTH FROM PD.STARTDATE) FROM TCMP.CS_PERIOD PD WHERE PD.PERIODSEQ = D.PERIODSEQ) AS PERIODO_DEPOSITO,
                        '' AS N_MEDIDA,0 AS V_MEDIDA,
                        D.EARNINGCODEID,D.EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_DEPOSIT D ON PAD_INS.POSITIONSEQ = D.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = D.PAYEESEQ
                        AND D.PERIODSEQ IN (SELECT PD.PERIODSEQ FROM TCMP.CS_PERIOD PD WHERE PD.REMOVEDATE = to_date('22000101','yyyymmdd') 
                                                AND SUBSTR(PD.NAME,-4) = SUBSTR(PAD_INS.PERIODO,-4)
                                                AND PD.STARTDATE <= PAD_INS.STARTDATE
                                                --Filtramos por el tipo de periodo para quedarnos solo los meses
                                                AND PD.PERIODTYPESEQ = 2814749767106561)
                        AND D.TENANTID = 'INYC'
                        --AND D.VALUE <> 0
                        AND SUBSTR(D.EARNINGGROUPID,7,2) = '03'
                        --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                        AND SUBSTR(D.EARNINGGROUPID,4,2) = 'S4'
                        --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                        AND SUBSTR(D.EARNINGCODEID,1,3) <> '801'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON D.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                        AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                        AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 106
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPA_E_RESUMEN. Percepciones: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_PEPA_E_RESUMEN. Balances.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ AS POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,
                        PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20170526: Introduccimos el mes del que proviene el balance
                        --'Regularizacion meses anteriores ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                        'Balance ' || (SELECT PER.NAME FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                            AND PER.PERIODSEQ = B.PERIODSEQ) ||' - ' || INITCAP(EC.DESCRIPTION) AS COMISION,
                        B.VALUE AS IMPORTE,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                        'Balance' AS N_MEDIDA,0 AS V_MEDIDA,
                        B.EARNINGCODEID,B.EARNINGGROUPID
                    --ALM 20170523: Modificamos la carga para coger la jerarquia del mes en ejecucion no la de cuando se realizo el balance
                    --FROM TCMP.CSA_PADIMENSION PAD_INS
                    --INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD_INS.PERIODSEQ = PD.PERIODSEQ AND PD.TENANTID = 'INYC'
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS 
                    INNER JOIN TCMP.CS_BALANCE B ON PAD_INS.POSITIONSEQ = B.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = B.PAYEESEQ
                        --ALM 20170516: No filtramos por el PERIODSEQ de los balances sino por las fechas de posteado para aplicarlos a un mes u otro
                        --AND B.PERIODSEQ IN (SELECT PER.PERIODSEQ FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                        --                        AND SUBSTR(PER.NAME,-4) = SUBSTR(PD.NAME,-4)
                        --                        AND PER.STARTDATE <= PD.STARTDATE
                        --                        --Filtramos por el tipo de periodo para quedarnos solo los meses
                        --                        AND PER.PERIODTYPESEQ = 2814749767106561)
                        AND B.POSTPIPELINERUNDATE < (SELECT PER.ENDDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                            AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                        AND B.POSTPIPELINERUNDATE > (SELECT PER.STARTDATE FROM TCMP.CS_PERIOD PER WHERE PER.REMOVEDATE = v_eot 
                            AND PER.PERIODSEQ = PAD_INS.PERIODSEQ)
                        AND B.TENANTID = 'INYC'
                        --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                        AND B.PROCESSINGUNITSEQ = 38280596832649217
                        --AND D.VALUE <> 0
                        AND SUBSTR(B.EARNINGGROUPID,7,2) = '03'
                        --ALM 20170309: A peticion de Alfonso filtramos por los depositos del S4
                        AND SUBSTR(B.EARNINGGROUPID,4,2) = 'S4'
                        --ALM 20170309: A peticion de Alfonso excluimos el concepto de pago 801 porque van despues del calculo del IRPF
                        AND SUBSTR(B.EARNINGCODEID,1,3) <> '801'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON B.TRIALPIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                        AND PL.TENANTID = 'INYC' AND PL.PROCESSINGUNITSEQ = 38280596832649217
                    --ALM 20170609: Unimos los balances con los pagos para filtrar balances que finalmente no se abonen en el periodo
                    INNER JOIN TCMP.CS_BALANCEPAYMENTTRACE BPAY ON B.BALANCESEQ = BPAY.BALANCESEQ
                        --ALM 20211025: Anadimos condicion para mejorar el rendimeinto de la consulta
                        AND BPAY.TENANTID = 'INYC' AND BPAY.PROCESSINGUNITSEQ = 38280596832649217
                        AND BPAY.TARGETPERIODSEQ = v_periodRow.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_PAGOS_MES_TEMP PAY ON BPAY.PAYMENTSEQ = PAY.PAYMENTSEQ
                    INNER JOIN TCMP.CS_EARNINGCODE EC ON (SUBSTR(B.EARNINGCODEID,1,1) || '00') = EC.EARNINGCODEID
                        AND EC.TENANTID = 'INYC'
                        AND EC.REMOVEDATE = v_eot 
                    --ALM 20170427: No podemos unir con las percepciones porque no podemos diferenciar entre depositos del mismo earningcode y earninggroup
                    --INNER JOIN INYCEXT.INYC_TABLA_PERCEPCIONES PERC ON D.NAME = PERC.DEPOSITO
                    --    AND SUBSTR(D.EARNINGCODEID,1,3) = PERC.EARNINGCODE
                    --    AND D.EARNINGGROUPID = PERC.EARNINGGROUP
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170427: Para los balances no filtramos por tipologias porque pueden haber cambiado. Devolvemos todos los balances.
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.POSITIONGENERICNUMBER2 = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 104
                    --    AND AG.F_INICIO <= PD.STARTDATE AND  AG.F_FIN > PD.STARTDATE
                    --ALM 20170427: Filtramos por el periodo anterior al atual
                    --ALM 20170523: No hace falta filtrar porque ya viene filtrada la tabla temporal principal por el periodo actual
                    --WHERE PAD_INS.PERIODSEQ = (SELECT MAX(PER.PERIODSEQ) FROM TCMP.CS_PERIOD PER
                    --                            INNER JOIN TCMP.CS_PERIODTYPE PT ON PER.PERIODTYPESEQ = PT.PERIODTYPESEQ AND PT.REMOVEDATE = v_eot
                    --                            WHERE PER.REMOVEDATE = v_eot AND PT.NAME = 'month' AND PER.PERIODSEQ < v_periodRow.PERIODSEQ)
                    ;

                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPA_E_RESUMEN. Balances: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_PEPA_E_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PEPA_E_RESUMEN
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_ETERNA,PAD_INS.CUADRO_RRTT_ETERNA,PAD_INS.PROMOCION,PAD_INS.SUPERRAPEL,
                        --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                        --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                        --PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.POSITIONNAME  
                        --    ELSE PAD_SUC.POSITIONNAME END AS COD_SUCURSAL,
                        --CASE WHEN PAD_OF.POSITIONGENERICATTRIBUTE1 = 'SUCURSAL' THEN PAD_OF.LASTNAME  
                        --    ELSE PAD_SUC.LASTNAME END AS SUCURSAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.POSITIONNAME  
                        --    ELSE PAD_REG.POSITIONNAME END AS COD_REGIONAL,
                        --CASE WHEN PAD_SUC.POSITIONGENERICATTRIBUTE1 = 'REGIONAL' THEN PAD_SUC.LASTNAME  
                        --    ELSE PAD_REG.LASTNAME END AS REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        '' AS COMISION,0 AS IMPORTE,0 AS IMPORTE_ACUMULADO,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        '' AS EARNINGCODEID,'' AS EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = M.PERIODSEQ 
                        AND M.TENANTID = 'INYC'
                        AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 106.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170307: Modificamos la obtencion de la regional, sucursal y oficina de los agentes 
                    --              debido a la existencia de Puntos de Venta ocasionales dependientes de algunas oficinas
                    --LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    --    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_INS.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --    AND AG.COD_INFORME = 106
                    --    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_PEPA_E_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
            
            
                w_debug('Inicio Carga INYC_LC_PEPA_E_RESUMEN. DERECHOS ECONOMICOS', v_contador);
     
                INSERT INTO INYCEXT.INYC_LC_PEPA_E_RESUMEN
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE, 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,
                        PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        'Comisiones Cartera DDEE' AS COMISION,
                        SUM(CAR_LP.IMPORTE) AS IMPORTE,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE) AS PERIODO_DEPOSITO,                
                        '' AS N_MEDIDA,
                        0 AS V_MEDIDA,
                        CAR_LP.EARNINGCODEID,
                        CAR_LP.EARNINGGROUPID
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CARTERA_LP_DET CAR_LP ON PAD_INS.POS_CALLIDUS = CAR_LP.POSITIONNAME  AND PAD_INS.STARTDATE = CAR_LP.COMPENSATIONDATE 
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(CAR_LP.EARNINGGROUPID,4,2) = 'S4'
                        AND SUBSTR(CAR_LP.EARNINGCODEID,1,3) <> '801'
                        --ALM 20220221: Segun el nuevo parametro v_FV_EstadoTrx filtramos transacciones cobradas o no. Para Balances y LC siempre estado Cobrado.
                        AND CAR_LP.ESTADO = 'C'
                        --ATV 20241218 No incluimos los registros con importe 0. Cambio debido a problemas en factura
                        AND CAR_LP.IMPORTE <> 0
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    LEFT JOIN INYCEXT.INYC_PAGOS_MES_TEMP Y ON PAD_INS.POSITIONSEQ_PRIN = Y.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = Y.PAYEESEQ
                        AND PAD_INS.PERIODSEQ = Y.PERIODSEQ
                        AND Y.TENANTID = 'INYC'
                        AND SUBSTR(Y.EARNINGGROUPID,7,2) = '03'
                        AND SUBSTR(Y.EARNINGGROUPID,4,2) = 'S4'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --LLS 20220127: Cruce para que no salgan los agentes calculados en LP si se han calculado en comisions
                    WHERE Y.POSITIONSEQ IS NULL
                    GROUP BY
                        PAD_INS.PARTICIPANTSEQ,
                        PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,
                        PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,
                        PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX), 
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_INS.TIPO_AGENTE,
                        PAD_INS.CUADRO_RRGG_OCASO,
                        PAD_INS.CUADRO_RRTT_OCASO,
                        PAD_INS.PROMOCION,
                        PAD_INS.SUPERRAPEL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END,
                        EXTRACT(MONTH FROM PAD_INS.STARTDATE),                
                        CAR_LP.EARNINGCODEID,
                        CAR_LP.EARNINGGROUPID;
                        
                filas := sql%rowcount;            
                COMMIT;           
                        
                w_debug('Fin Carga INYC_LC_PEPA_E_RESUMEN. DERECHOS ECONOMICOS: '|| to_char(filas) || ' filas.', v_contador);
                    
                --ALM 20220221: Quitamos el uso del parametro v_licencias para reducir codigo.
                --END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_PEPA_E_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_PEPA_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_PEPA_E_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_PEPA_E_RESUMEN.', v_contador);
                
                
