                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_PEPA_E_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_PEPA_E_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_PEPA_E_RESUMEN.', v_contador);

