                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_INS.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    --ALM 20170904:    Por peticion de Pepe Boto no filtramos en los informes de Percepciones por la tipologia
                    --INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
