                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_PEPA_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_PEPA_E_RESUMEN');

