                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --ATV 20240719 Anyadimos el informe 25.1
                        AND AG.COD_INFORME in (1, 25.1)
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RPI_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_BAL_RPI_RESUMEN. Incentivos.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RPI_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA,I.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        '' AS N_CREDITO,0 AS V_CREDITO,
                        '' AS FIRSTNAME_AG,'' AS LASTNAME_AG,'' AS SUFFIX_AG,
                        --ALM 20180126: Anadimos un * al codigo del agente para informar si el agente pertenece al grupo del inspector
                        '' AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                        --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                        ,CASE WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            WHEN PAD_PTO_VENTA.POSITIONNAME = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                                                ELSE PAD_PTO_VENTA.POSITIONNAME END) THEN 3
                            ELSE 4
                        END AS NIVEL_PTO_VENTA,
                        PAD_PTO_VENTA.POSITIONNAME AS COD_PTO_VENTA,
                        PAD_PTO_VENTA.LASTNAME AS PTO_VENTA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                                                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                                                            ELSE PAD_PTO_VENTA.POSITIONNAME END END) THEN 2
                            ELSE 3
                        END AS NIVEL_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.POSITIONNAME  
                            ELSE PAD_PTO_VENTA.POSITIONNAME END AS COD_OFICINA,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_OF.LASTNAME  
                            ELSE PAD_PTO_VENTA.LASTNAME END AS OFICINA,
                        CASE WHEN (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME 
                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME 
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END END) = (CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                                                                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                                                                    ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                                                                        ELSE PAD_PTO_VENTA.POSITIONNAME END END END) THEN 1
                            ELSE 2
                        END AS NIVEL_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.POSITIONNAME
                                ELSE PAD_PTO_VENTA.POSITIONNAME END 
                        END AS COD_SUCURSAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_SUC.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_OF.LASTNAME
                                ELSE PAD_PTO_VENTA.LASTNAME END 
                        END AS SUCURSAL,
                        1 AS NIVEL_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.POSITIONNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.POSITIONNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.POSITIONNAME
                                    ELSE PAD_PTO_VENTA.POSITIONNAME END
                        END END AS COD_REGIONAL,
                        CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (5) THEN PAD_REG.LASTNAME
                            ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (4,7) THEN PAD_SUC.LASTNAME
                                ELSE CASE WHEN PAD_PTO_VENTA.POSITIONGENERICNUMBER3 IN (3,6,8,10) THEN PAD_OF.LASTNAME
                                    ELSE PAD_PTO_VENTA.LASTNAME END
                        END END AS REGIONAL,
                        --ALM 20180123: Anadimos las polizas corregidas del credito para poder sacarlo a nivel de detalle de agentes en el informe
                        0 as C_GN4
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                    --ATV 20240719 Anyadimos el informe 25.1
                        AND REG.COD_INFORME in (1.1, 25.1)
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    --ALM 20170331: Anadimos la estructura jerarquica de oficinas para poder realizar filtros en el informe
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_PTO_VENTA ON PAD_INS.PERIODSEQ = PAD_PTO_VENTA.PERIODSEQ
                        AND PAD_PTO_VENTA.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_PTO_VENTA.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONSEQ = PAD_PTO_VENTA.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_SUC ON PAD_OF.PERIODSEQ = PAD_SUC.PERIODSEQ
                        AND PAD_SUC.POSITIONSEQ = PAD_OF.MANAGERSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_REG ON PAD_SUC.PERIODSEQ = PAD_REG.PERIODSEQ
                        AND PAD_REG.POSITIONSEQ = PAD_SUC.MANAGERSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    --ATV 20240719 Anyadimos el informe 25.1
                        AND AG.COD_INFORME in (1, 25.1)
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                                
                filas := sql%rowcount;            
                COMMIT;           
                        
                w_debug('Fin Carga INYC_BAL_RPI_RESUMEN. Incentivos: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_RPI_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RPI_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RPI_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_RPI_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RPI_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RPI_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RPI_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --Carga tabla de Informe Rappel por Produccion Detalle 
    --ALM 20180119: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'RPI' OR informe like '%,RPI,%' OR informe like '%,RPI' OR informe like 'RPI,%' OR informe = 'ALL' THEN
    IF informe = 'RPI_DETALLE' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RPI_DETALLE.', v_contador);

            DELETE INYCEXT.INYC_RPI_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_RPI_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_RPI_DETALLE.', v_contador);

            INSERT INTO INYCEXT.INYC_RPI_DETALLE 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                    C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                    ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                    ST.EVENTO,
                    CT.DESCRIPTION AS TIPO_CREDITO,
                    ST.PRODUCTO,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    AND C.VALUE <> 0
                    --ALM 20170518: Al igual que en el S5 y en el PEPI filtramos para no tener en cuenta los creditos directos que pertenecen a 
                    --              inspectores que cuando emitieron la poliza eran agentes
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 1.2
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                    AND CT.REMOVEDATE = v_eot
                    AND CT.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 1
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --ALM 20170518: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61
                --              Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                            --ALM 20170628: Por peticion de David anadimos los tipos 82
                            AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                        OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                ;
                            
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_RPI_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
            w_debug('Inicio Actualizacion Indices INYC_RPI_DETALLE.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_RPI_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_RPI_DETALLE');

            w_debug('Fin Actualizacion Indices INYC_RPI_DETALLE.', v_contador);
                
                
            w_debug('Inicio actualizacion del parametro INYC_RPI_DETALLE',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_RPI_DETALLE');
            
            w_debug('Fin actualizacion del parametro INYC_RPI_DETALLE',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_RPI_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_LC_RPI_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_RPI_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_RPI_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_RPI_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                        --ALM 20170518: Al igual que en el S5 y en el PEPI filtramos para no tener en cuenta los creditos directos que pertenecen a 
                        --              inspectores que cuando emitieron la poliza eran agentes
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 1.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 1
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170518: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61
                    --              Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                --ALM 20170628: Por peticion de David anadimos los tipos 82
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_RPI_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_RPI_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RPI_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RPI_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_LC_RPI_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_RPI_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_RPI_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_LC_RPI_DETALLE',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RPI_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_BAL_RPI_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RPI_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_RPI_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RPI_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                        --ALM 20170518: Al igual que en el S5 y en el PEPI filtramos para no tener en cuenta los creditos directos que pertenecen a 
                        --              inspectores que cuando emitieron la poliza eran agentes
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 1.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 1
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --ALM 20170518: Filtramos las transaccion con tipo de evento REC-RRTT para los agentes que no sean 57 y 61
                    --              Tenemos que usar la tipologia de la Position del inspector que recibe la poliza no del principal.
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    WHERE ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                --ALM 20170628: Por peticion de David anadimos los tipos 82
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RPI_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_RPI_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RPI_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RPI_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_RPI_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RPI_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RPI_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RPI_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;   
     
    --Carga tabla de Informe Rappel Agentes con Grupo Resumen
    IF informe = 'RAG' OR informe LIKE '%,RAG,%' OR informe LIKE '%,RAG' OR informe LIKE 'RAG,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RAG_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_RAG_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_RAG_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_RAG_RESUMEN.', v_contador);

            INSERT INTO INYCEXT.INYC_RAG_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,                                    
                    C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    --ALM 20180123: Anadimos las polizas corregidas del credito para poder sacarlo a nivel de detalle de agentes en el informe
                    C.GENERICNUMBER4 as C_GN4
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 2.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    AND PMCT.TENANTID = 'INYC' 
                LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 2
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_RAG_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_RAG_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_RAG_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_RAG_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_RAG_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_RAG_RESUMEN',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_RAG_RESUMEN');
        
            w_debug('Fin actualizacion del parametro INYC_RAG_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_RAG_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_RAG_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_RAG_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_RAG_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_RAG_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,                                    
                        C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180123: Anadimos las polizas corregidas del credito para poder sacarlo a nivel de detalle de agentes en el informe
                        C.GENERICNUMBER4 as C_GN4
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 2.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                        AND PMCT.TENANTID = 'INYC' 
                    LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 2
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_RAG_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_RAG_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RAG_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RAG_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_RAG_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_RAG_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_RAG_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_RAG_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RAG_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_RAG_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RAG_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_RAG_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RAG_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,                                    
                        C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180123: Anadimos las polizas corregidas del credito para poder sacarlo a nivel de detalle de agentes en el informe
                        C.GENERICNUMBER4 as C_GN4
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 2.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                        AND PMCT.TENANTID = 'INYC' 
                    LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 2
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RAG_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
