                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RAG_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RAG_DETALLE');

