                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 2
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
