                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        --ALM 20220420: Nuevo campo para coger la bolsa de financiacion marcada para el calculo.
                        M.GENERICATTRIBUTE1 AS GA1_MEDIDA
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 6.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 6
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    WHERE PAD_INS.BOUSERID IN (
                            SELECT DISTINCT X.BOUSERID FROM INYCEXT.INYC_AGENTES_MES_TEMP X 
                            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP Y ON X.PERIODSEQ = Y.PERIODSEQ
                                AND X.POSITIONSEQ = Y.POSITIONSEQ
                                AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS Z ON Y.NAME = Z.REGLA
                                AND Z.COD_INFORME = 6.2
                            WHERE X.BOUSERID = PAD_INS.BOUSERID
                                AND Z.F_INICIO <= PAD_INS.STARTDATE AND  Z.F_FIN > PAD_INS.STARTDATE
                                AND Y.VALUE <> 0)
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_RPA_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_RPA_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RPA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RPA_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_RPA_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_RPA_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_RPA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_RPA_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RPA_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_RPA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RPA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_RPA_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RPA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,  
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,M.GENERICNUMBER1 AS M_GN1,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        --ALM 20220420: Nuevo campo para coger la bolsa de financiacion marcada para el calculo.
                        M.GENERICATTRIBUTE1 AS GA1_MEDIDA
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 6.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 6
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    WHERE PAD_INS.BOUSERID IN (
                            SELECT DISTINCT X.BOUSERID FROM INYCEXT.INYC_AGENTES_MES_TEMP X 
                            INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP Y ON X.PERIODSEQ = Y.PERIODSEQ
                                AND X.POSITIONSEQ = Y.POSITIONSEQ
                                AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS Z ON Y.NAME = Z.REGLA
                                AND Z.COD_INFORME = 6.2
                            WHERE X.BOUSERID = PAD_INS.BOUSERID
                                AND Z.F_INICIO <= PAD_INS.STARTDATE AND  Z.F_FIN > PAD_INS.STARTDATE
                                AND Y.VALUE <> 0)
                        --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RPA_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_RPA_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RPA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RPA_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_RPA_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RPA_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RPA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RPA_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --Carga tabla de Informe Rappel Produccion Agentes Detalle 
    IF informe = 'RPA' OR informe LIKE '%,RPA,%' OR informe LIKE '%,RPA' OR informe LIKE 'RPA,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RPA_DETALLE.', v_contador);

            DELETE INYCEXT.INYC_RPA_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_RPA_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_RPA_DETALLE.', v_contador);

            INSERT INTO INYCEXT.INYC_RPA_DETALLE 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,             
                    C.NAME,
                    --ALM 20161006: Para los creditos de polizas de recuperadas y renovaciones incluimos en el valor de la prima
                    CASE WHEN C.NAME LIKE 'DC-O-GEN-Agente-NumeroPolizas-998-Re%' THEN C.GENERICNUMBER5 ELSE C.VALUE END AS VALUE,
                    C.GENERICNUMBER4 AS C_GN4,
                    C.GENERICBOOLEAN1 AS C_GB1,
                    ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                    ST.EVENTO,
                    CT.DESCRIPTION AS TIPO_CREDITO,
                    ST.PRODUCTO,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    ----ALM 20161006: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas(Renovaciones)
                    --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 6.2
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                    AND CT.REMOVEDATE = v_eot
                    AND CT.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 6
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE 
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_RPA_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_RPA_DETALLE.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_RPA_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_RPA_DETALLE');

            w_debug('Fin Actualizacion Indices INYC_RPA_DETALLE.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_RPA_DETALLE',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_RPA_DETALLE');
        
            w_debug('Fin actualizacion del parametro INYC_RPA_DETALLE',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_RPA_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_LC_RPA_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_RPA_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_RPA_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_RPA_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,             
                        C.NAME,
                        --ALM 20161006: Para los creditos de polizas de recuperadas y renovaciones incluimos en el valor de la prima
                        CASE WHEN C.NAME LIKE 'DC-O-GEN-Agente-NumeroPolizas-998-Re%' THEN C.GENERICNUMBER5 ELSE C.VALUE END AS VALUE,
                        C.GENERICNUMBER4 AS C_GN4,
                        C.GENERICBOOLEAN1 AS C_GB1,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        ----ALM 20161006: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas(Renovaciones)
                        --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 6.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 6
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE 
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_RPA_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_RPA_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RPA_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RPA_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_LC_RPA_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_RPA_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_RPA_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_LC_RPA_DETALLE',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RPA_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_BAL_RPA_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RPA_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_RPA_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RPA_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,             
                        C.NAME,
                        --ALM 20161006: Para los creditos de polizas de recuperadas y renovaciones incluimos en el valor de la prima
                        CASE WHEN C.NAME LIKE 'DC-O-GEN-Agente-NumeroPolizas-998-Re%' THEN C.GENERICNUMBER5 ELSE C.VALUE END AS VALUE,
                        C.GENERICNUMBER4 AS C_GN4,
                        C.GENERICBOOLEAN1 AS C_GB1,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        ----ALM 20161006: Filtramos para que los creditos 998-81 solo se tengan en cuenta con los productos de Hogar con polizas corregidas(Renovaciones)
                        --AND (C.NAME LIKE '%998' OR (C.NAME LIKE '%998-81' AND C.GENERICATTRIBUTE2 LIKE '01501%' AND C.GENERICNUMBER4 <> 0))
                        AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 6.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 6
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE 
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RPA_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_RPA_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RPA_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RPA_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_RPA_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RPA_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RPA_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RPA_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Rappel Produccion Propia Ag. Grupo Resumen
    IF informe = 'RPP' OR informe LIKE '%,RPP,%' OR informe LIKE '%,RPP' OR informe LIKE 'RPP,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RPP_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_RPP_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_RPP_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_RPP_RESUMEN.', v_contador);

            INSERT INTO INYCEXT.INYC_RPP_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,  
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,M.GENERICNUMBER1 AS M_GN1,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
