                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RDC_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RDC_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_RDC_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RDC_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RDC_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RDC_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --ALM 20180109: Tabla para el Informe de Regularizacion Anual de Diferenciales
    IF informe = 'RDIF' OR informe LIKE '%,RDIF,%' OR informe LIKE '%,RDIF' OR informe LIKE 'RDIF,%' OR informe = 'ALL' THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RDIF_RESUMEN. Mensual', v_contador);

            DELETE INYCEXT.INYC_RDIF_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_RDIF_RESUMEN. Mensual: '|| to_char(filas) || ' filas borradas.', v_contador);

            IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN
                w_debug('Inicio Borrado INYC_RDIF_RESUMEN. Regularizacion', v_contador);

                DELETE INYCEXT.INYC_RDIF_RESUMEN WHERE SUBSTR(PERIODO,-4) = SUBSTR(v_periodo,-4) AND NAME LIKE '%-Anual';
            
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_RDIF_RESUMEN. Regularizacion: '|| to_char(filas) || ' filas borradas.', v_contador);
            END IF;

            
            w_debug('Inicio Carga INYC_RDIF_RESUMEN. Diferenciales Mensuales.', v_contador);

            INSERT INTO INYCEXT.INYC_RDIF_RESUMEN 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                    PAD_INS.POS_PRIN,
                    PAD_INS.CUADRO_INSP_OCASO,
                    PAD_INS.ID_TIPO_AGENTE,
                    PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                    SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida' AS NAME,
                    --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                    --MAX(ABS(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END)) *
                    --    MAX(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.VALUE) ELSE -1 END) AS VALUE,
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END) AS VALUE,
                    MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                    MAX(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                    ST.PRODUCTID,ST.PRODUCTO,
                    --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                    --MAX(ABS(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END)) *
                    --    MAX(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.GENERICNUMBER5) ELSE -1 END) AS PRIMA_NETA,
                    SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END) AS PRIMA_NETA,
                    PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    AND C.VALUE <> 0
                    AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    AND REG.COD_INFORME = 101.2
                LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                            AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-O-DIF-%' AND I_DIF.NAME NOT LIKE '%-Anual'
                        WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                    ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                    AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    AND AG.COD_INFORME = 101
                WHERE (DIF.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79
                        OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0)
                    AND ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                            AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                        OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                    RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                    PAD_INS.ID_TIPO_AGENTE,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                    ST.PRODUCTID,ST.PRODUCTO,PAD_INS.TIPO_AGENTE
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_RDIF_RESUMEN. Diferenciales Mensuales: '|| to_char(filas) || ' filas.', v_contador);            
            
            IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN
                w_debug('Inicio Carga INYC_RDIF_RESUMEN. Regularizacion Anual.', v_contador);

                INSERT INTO INYCEXT.INYC_RDIF_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PD.PERIODSEQ,PD.NAME AS PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida-Anual' AS NAME,
                        --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                        --MAX(ABS(C.VALUE)) * MAX(SIGN(C.VALUE)) AS VALUE,
                        SUM(C.VALUE) AS VALUE,
                        MAX(C.GENERICNUMBER1) AS COEF_CORR,
                        MAX(COM.RATEVALUE) AS PORC_DIFERENCIAL,SUM(COM.VALUE) AS IMP_DIFERENCIAL,
                        C.GENERICATTRIBUTE2 AS PRODUCTID,PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                        --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                        --MAX(ABS(C.GENERICNUMBER5)) * MAX(SIGN(C.GENERICNUMBER5)) AS PRIMA_NETA,
                        SUM(C.GENERICNUMBER5) AS PRIMA_NETA,
                        PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PD.YEAR = PAD_INS.YEAR
                        AND PD.TENANTID = 'INYC'
                    INNER JOIN TCMP.CS_COMMISSION COM ON PAD_INS.PARTICIPANTSEQ = COM.PAYEESEQ
                        AND PAD_INS.POSITIONSEQ_PRIN = COM.POSITIONSEQ
                        AND PD.PERIODSEQ = COM.PERIODSEQ
                        AND COM.TENANTID = 'INYC'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON COM.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ 
                        AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                        --AND COM.PERIODSEQ = I.PERIODSEQ 
                        AND I.TENANTID = 'INYC'
                        AND I.NAME LIKE 'C-O-DIF-%-Anual'   
                    INNER JOIN (SELECT X.CREDITSEQ,X.PERIODSEQ,X.NAME,X.VALUE,X.GENERICNUMBER1,X.GENERICNUMBER5,X.GENERICATTRIBUTE2 
                                FROM TCMP.CS_CREDIT X 
                                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                                INNER JOIN TCMP.CS_PLRUN PL ON X.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                                WHERE X.TENANTID = 'INYC' AND X.VALUE <> 0 AND (X.NAME LIKE 'IC-%' OR X.GENERICBOOLEAN3 = 0)
                                    AND X.NAME IN ('DC-O-GEN-Inspector-PrimaCorregida-998','IC-O-GEN-Inspector-PrimaCorregida-998','DC-O-GEN-Inspector-PrimaCorregida-004','IC-O-GEN-Inspector-PrimaCorregida-004')
                    ) C ON COM.CREDITSEQ = C.CREDITSEQ AND COM.PERIODSEQ = C.PERIODSEQ
                    LEFT OUTER JOIN TCMP.CS_CLASSIFIER CL ON C.GENERICATTRIBUTE2 = CL.CLASSIFIERID 
                        AND CL.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
                        AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND CL.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                        AND PROD.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
                        AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                        AND PROD.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PD.PERIODSEQ,PD.NAME,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        C.GENERICATTRIBUTE2,PROD.GENERICATTRIBUTE5,PAD_INS.TIPO_AGENTE
                ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_RDIF_RESUMEN. Regularizacion Anual: '|| to_char(filas) || ' filas.', v_contador);
            END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_RDIF_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_RDIF_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_RDIF_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_RDIF_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_RDIF',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_RDIF');
        
            w_debug('Fin actualizacion del parametro INYC_RDIF',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_RDIF_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_RDIF_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_RDIF_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN
                    w_debug('Inicio Borrado INYC_LC_RDIF_RESUMEN. Regularizacion', v_contador);

                    DELETE INYCEXT.INYC_LC_RDIF_RESUMEN WHERE SUBSTR(PERIODO,-4) = SUBSTR(v_periodo,-4) AND NAME LIKE '%-Anual';
                
                    filas := sql%rowcount;            
                    COMMIT;
                    
                    w_debug('Fin Borrado INYC_LC_RDIF_RESUMEN. Regularizacion: '|| to_char(filas) || ' filas borradas.', v_contador);
                END IF;

                
                w_debug('Inicio Carga INYC_LC_RDIF_RESUMEN. Diferenciales Mensuales.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_RDIF_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida' AS NAME,
                        --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                        --MAX(ABS(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END)) *
                        --    MAX(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.VALUE) ELSE -1 END) AS VALUE,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END) AS VALUE,
                        MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                        MAX(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                        ST.PRODUCTID,ST.PRODUCTO,
                        --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                        --MAX(ABS(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END)) *
                        --    MAX(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.GENERICNUMBER5) ELSE -1 END) AS PRIMA_NETA,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END) AS PRIMA_NETA,
                        PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 101.2
                    LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                                AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-O-DIF-%' AND I_DIF.NAME NOT LIKE '%-Anual'
                            WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    WHERE (DIF.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79
                            OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0)
                        AND ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        ST.PRODUCTID,ST.PRODUCTO,PAD_INS.TIPO_AGENTE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_RDIF_RESUMEN. Diferenciales Mensuales: '|| to_char(filas) || ' filas.', v_contador);           
            
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN
                    w_debug('Inicio Carga INYC_LC_RDIF_RESUMEN. Regularizacion Anual.', v_contador);

                    INSERT INTO INYCEXT.INYC_LC_RDIF_RESUMEN 
                        SELECT
                            PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                            PD.PERIODSEQ,PD.NAME AS PERIODO,
                            PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                            PAD_INS.POS_PRIN,
                            PAD_INS.CUADRO_INSP_OCASO,
                            PAD_INS.ID_TIPO_AGENTE,
                            PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                            SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida-Anual' AS NAME,
                            --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                            --MAX(ABS(C.VALUE)) * MAX(SIGN(C.VALUE)) AS VALUE,
                            SUM(C.VALUE) AS VALUE,
                            MAX(C.GENERICNUMBER1) AS COEF_CORR,
                            MAX(COM.RATEVALUE) AS PORC_DIFERENCIAL,SUM(COM.VALUE) AS IMP_DIFERENCIAL,
                            C.GENERICATTRIBUTE2 AS PRODUCTID,PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                            --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                            --MAX(ABS(C.GENERICNUMBER5)) * MAX(SIGN(C.GENERICNUMBER5)) AS PRIMA_NETA,
                            SUM(C.GENERICNUMBER5) AS PRIMA_NETA,
                            PAD_INS.TIPO_AGENTE
                        FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                        INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PD.YEAR = PAD_INS.YEAR
                            AND PD.TENANTID = 'INYC'
                        INNER JOIN TCMP.CS_COMMISSION COM ON PAD_INS.PARTICIPANTSEQ = COM.PAYEESEQ
                            AND PAD_INS.POSITIONSEQ_PRIN = COM.POSITIONSEQ
                            AND PD.PERIODSEQ = COM.PERIODSEQ
                            AND COM.TENANTID = 'INYC'
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON COM.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ 
                            AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                            --AND COM.PERIODSEQ = I.PERIODSEQ 
                            AND I.TENANTID = 'INYC'
                            AND I.NAME LIKE 'C-O-DIF-%-Anual'   
                        INNER JOIN (SELECT X.CREDITSEQ,X.PERIODSEQ,X.NAME,X.VALUE,X.GENERICNUMBER1,X.GENERICNUMBER5,X.GENERICATTRIBUTE2 
                                    FROM TCMP.CS_CREDIT X 
                                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                                    INNER JOIN TCMP.CS_PLRUN PL ON X.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                                    WHERE X.TENANTID = 'INYC' AND X.VALUE <> 0 AND (X.NAME LIKE 'IC-%' OR X.GENERICBOOLEAN3 = 0)
                                        AND X.NAME IN ('DC-O-GEN-Inspector-PrimaCorregida-998','IC-O-GEN-Inspector-PrimaCorregida-998','DC-O-GEN-Inspector-PrimaCorregida-004','IC-O-GEN-Inspector-PrimaCorregida-004')
                        ) C ON COM.CREDITSEQ = C.CREDITSEQ AND COM.PERIODSEQ = C.PERIODSEQ
                        LEFT OUTER JOIN TCMP.CS_CLASSIFIER CL ON C.GENERICATTRIBUTE2 = CL.CLASSIFIERID 
                            AND CL.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
                            AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                            AND CL.TENANTID = 'INYC'
                        LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                            AND PROD.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
                            AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                            AND PROD.TENANTID = 'INYC'
                        LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                            AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                        INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                            AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                            AND AG.COD_INFORME = 101
                        GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PD.PERIODSEQ,PD.NAME,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                            PAD_INS.ID_TIPO_AGENTE,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                            C.GENERICATTRIBUTE2,PROD.GENERICATTRIBUTE5,PAD_INS.TIPO_AGENTE
                    ;
                                
                    filas := sql%rowcount;            
                    COMMIT;           
                        
                    w_debug('Fin Carga INYC_LC_RDIF_RESUMEN. Regularizacion Anual: '|| to_char(filas) || ' filas.', v_contador);
                END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_RDIF_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RDIF_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RDIF_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_RDIF_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_RDIF',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_RDIF');
            
                w_debug('Fin actualizacion del parametro INYC_LC_RDIF',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RDIF_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_RDIF_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RDIF_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN
                    w_debug('Inicio Borrado INYC_BAL_RDIF_RESUMEN. Regularizacion', v_contador);

                    DELETE INYCEXT.INYC_BAL_RDIF_RESUMEN WHERE SUBSTR(PERIODO,-4) = SUBSTR(v_periodo,-4) AND NAME LIKE '%-Anual';
                
                    filas := sql%rowcount;            
                    COMMIT;
                    
                    w_debug('Fin Borrado INYC_BAL_RDIF_RESUMEN. Regularizacion: '|| to_char(filas) || ' filas borradas.', v_contador);
                END IF;

                
                w_debug('Inicio Carga INYC_BAL_RDIF_RESUMEN. Diferenciales Mensuales.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RDIF_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                        PAD_INS.POS_PRIN,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,
                        PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                        SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida' AS NAME,
                        --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                        --MAX(ABS(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END)) *
                        --    MAX(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.VALUE) ELSE -1 END) AS VALUE,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.VALUE ELSE 0 END) AS VALUE,
                        MAX(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER1 ELSE 0 END) AS COEF_CORR,
                        MAX(DIF.RATEVALUE) AS PORC_DIFERENCIAL,SUM(DIF.VALUE) AS IMP_DIFERENCIAL,
                        ST.PRODUCTID,ST.PRODUCTO,
                        --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                        --MAX(ABS(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END)) *
                        --    MAX(CASE WHEN C.NAME like '%C-O-GEN-Inspector-PrimaCorregida%' THEN SIGN(C.GENERICNUMBER5) ELSE -1 END) AS PRIMA_NETA,
                        SUM(CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-PrimaCorregida%' THEN C.GENERICNUMBER5 ELSE 0 END) AS PRIMA_NETA,
                        PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        AND REG.COD_INFORME = 101.2
                    LEFT OUTER JOIN (SELECT COM_DIF.CREDITSEQ,COM_DIF.RATEVALUE,COM_DIF.VALUE FROM CS_COMMISSION COM_DIF 
                            --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                            INNER JOIN TCMP.CS_PLRUN PL ON COM_DIF.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                            INNER JOIN TCMP.CS_INCENTIVE I_DIF ON COM_DIF.INCENTIVESEQ = I_DIF.INCENTIVESEQ AND COM_DIF.PIPELINERUNSEQ = I_DIF.PIPELINERUNSEQ
                                AND I_DIF.TENANTID = 'INYC' AND I_DIF.PERIODSEQ = v_periodRow.PERIODSEQ AND I_DIF.NAME LIKE 'C-O-DIF-%' AND I_DIF.NAME NOT LIKE '%-Anual'
                            WHERE COM_DIF.TENANTID = 'INYC' AND COM_DIF.PERIODSEQ = v_periodRow.PERIODSEQ
                        ) DIF ON C.CREDITSEQ = DIF.CREDITSEQ 
                    LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                        AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        AND AG.COD_INFORME = 101
                    WHERE (DIF.VALUE IS NOT NULL OR PAD_INS.ID_TIPO_AGENTE = 79
                            OR (CASE WHEN C.NAME LIKE '%C-O-GEN-Inspector-NumeroPolizas-%' THEN C.VALUE ELSE 0 END) <> 0)
                        AND ((SELECT MAX(X.POSITIONGENERICNUMBER2) FROM INYCEXT.INYC_AGENTES_MES_TEMP X WHERE X.PERIODSEQ = PAD_INS.PERIODSEQ
                                AND X.PARTICIPANTSEQ = PAD_INS.PARTICIPANTSEQ AND X.POSITIONSEQ = PAD_INS.POSITIONSEQ) IN (82,61)
                            OR ST.EVENTO <> 'Recuperaciones Ramos Tradicionales')
                    GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                        RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.ID_TIPO_AGENTE,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                        ST.PRODUCTID,ST.PRODUCTO,PAD_INS.TIPO_AGENTE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RDIF_RESUMEN. Diferenciales Mensuales: '|| to_char(filas) || ' filas.', v_contador);           
            
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN
                    w_debug('Inicio Carga INYC_BAL_RDIF_RESUMEN. Regularizacion Anual.', v_contador);

                    INSERT INTO INYCEXT.INYC_BAL_RDIF_RESUMEN 
                        SELECT
                            PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                            PD.PERIODSEQ,PD.NAME AS PERIODO,
                            PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX) AS NOMBRE,
                            PAD_INS.POS_PRIN,
                            PAD_INS.CUADRO_INSP_OCASO,
                            PAD_INS.ID_TIPO_AGENTE,
                            PAD_OF.POSITIONNAME AS COD_OFICINA,PAD_OF.LASTNAME AS OFICINA,
                            SUBSTR(C.NAME,1,1) || 'C-O-GEN-Inspector-PrimaCorregida-Anual' AS NAME,
                            --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                            --MAX(ABS(C.VALUE)) * MAX(SIGN(C.VALUE)) AS VALUE,
                            SUM(C.VALUE) AS VALUE,
                            MAX(C.GENERICNUMBER1) AS COEF_CORR,
                            MAX(COM.RATEVALUE) AS PORC_DIFERENCIAL,SUM(COM.VALUE) AS IMP_DIFERENCIAL,
                            C.GENERICATTRIBUTE2 AS PRODUCTID,PROD.GENERICATTRIBUTE5 AS PRODUCTO,
                            --ALM 20191227: No podemos usar MAX porque agrupamos por producto y puede haber mas de una poliza por cada uno.
                            --MAX(ABS(C.GENERICNUMBER5)) * MAX(SIGN(C.GENERICNUMBER5)) AS PRIMA_NETA,
                            SUM(C.GENERICNUMBER5) AS PRIMA_NETA,
                            PAD_INS.TIPO_AGENTE
                        FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                        INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PD.YEAR = PAD_INS.YEAR
                            AND PD.TENANTID = 'INYC'
                        INNER JOIN TCMP.CS_COMMISSION COM ON PAD_INS.PARTICIPANTSEQ = COM.PAYEESEQ
                            AND PAD_INS.POSITIONSEQ_PRIN = COM.POSITIONSEQ
                            AND PD.PERIODSEQ = COM.PERIODSEQ
                            AND COM.TENANTID = 'INYC'
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON COM.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ 
                            AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                            --AND COM.PERIODSEQ = I.PERIODSEQ 
                            AND I.TENANTID = 'INYC'
                            AND I.NAME LIKE 'C-O-DIF-%-Anual'   
                        INNER JOIN (SELECT X.CREDITSEQ,X.PERIODSEQ,X.NAME,X.VALUE,X.GENERICNUMBER1,X.GENERICNUMBER5,X.GENERICATTRIBUTE2 
                                    FROM TCMP.CS_CREDIT X 
                                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                                    INNER JOIN TCMP.CS_PLRUN PL ON X.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                                    WHERE X.TENANTID = 'INYC' AND X.VALUE <> 0 AND (X.NAME LIKE 'IC-%' OR X.GENERICBOOLEAN3 = 0)
                                        AND X.NAME IN ('DC-O-GEN-Inspector-PrimaCorregida-998','IC-O-GEN-Inspector-PrimaCorregida-998','DC-O-GEN-Inspector-PrimaCorregida-004','IC-O-GEN-Inspector-PrimaCorregida-004')
                        ) C ON COM.CREDITSEQ = C.CREDITSEQ AND COM.PERIODSEQ = C.PERIODSEQ
                        LEFT OUTER JOIN TCMP.CS_CLASSIFIER CL ON C.GENERICATTRIBUTE2 = CL.CLASSIFIERID 
                            AND CL.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
                            AND CL.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND CL.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                            AND CL.TENANTID = 'INYC'
                        LEFT OUTER JOIN TCMP.CS_PRODUCT PROD ON CL.CLASSIFIERSEQ = PROD.CLASSIFIERSEQ 
                            AND PROD.REMOVEDATE = TO_DATE('22000101','yyyymmdd')  
                            AND PROD.EFFECTIVESTARTDATE <= PAD_INS.STARTDATE AND PROD.EFFECTIVEENDDATE > PAD_INS.STARTDATE
                            AND PROD.TENANTID = 'INYC'
                        LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                            AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
                        INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                            AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                            AND AG.COD_INFORME = 101
                        GROUP BY PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,PD.PERIODSEQ,PD.NAME,PAD_INS.BOUSERID,PAD_INS.POSITIONNAME,PAD_INS.NIF,
                            RTRIM(PAD_INS.FIRSTNAME) || ' ' || RTRIM(PAD_INS.LASTNAME) || ' ' || RTRIM(PAD_INS.SUFFIX),PAD_INS.POS_PRIN,PAD_INS.CUADRO_INSP_OCASO,
                            PAD_INS.ID_TIPO_AGENTE,PAD_OF.POSITIONNAME,PAD_OF.LASTNAME,SUBSTR(C.NAME,1,1),
                            C.GENERICATTRIBUTE2,PROD.GENERICATTRIBUTE5,PAD_INS.TIPO_AGENTE
                    ;
                                
                    filas := sql%rowcount;            
                    COMMIT;           
                        
                    w_debug('Fin Carga INYC_BAL_RDIF_RESUMEN. Regularizacion Anual: '|| to_char(filas) || ' filas.', v_contador);
                END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_RDIF_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RDIF_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RDIF_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_RDIF_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RDIF',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RDIF');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RDIF',v_contador);
            
            END IF;
        
        END IF;

        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Diferenciales - Inspector Resumen
    IF informe = 'DIF' OR informe LIKE '%,DIF,%' OR informe LIKE '%,DIF' OR informe LIKE 'DIF,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_DIF_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_DIF_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_DIF_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_DIF_RESUMEN.', v_contador);

            INSERT INTO INYCEXT.INYC_DIF_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_OCASO,
                    C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICNUMBER4 AS C_GN4,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 7.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    AND PMCT.TENANTID = 'INYC' 
                LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 7
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_DIF_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
            
            w_debug('Inicio Carga INYC_DIF_RESUMEN.', v_contador);
            
            INSERT INTO INYCEXT.INYC_DIF_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_OCASO,
                    NULL AS N_CREDITO,NULL AS V_CREDITO,NULL AS C_GN4,
                    NULL AS FIRSTNAME_AG,NULL AS MIDDLENAME_AG,NULL AS LASTNAME_AG,NULL AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                    AND I.TENANTID = 'INYC'
                    --AND I.VALUE <> 0
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                    AND REG.COD_INFORME = 7.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 7
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_DIF_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_DIF_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_DIF_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_DIF_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_DIF_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_DIF_RESUMEN',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_DIF_RESUMEN');
        
            w_debug('Fin actualizacion del parametro INYC_DIF_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_DIF_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_DIF_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_DIF_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_DIF_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_DIF_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICNUMBER4 AS C_GN4,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                        AND PMCT.TENANTID = 'INYC' 
                    LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_DIF_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_LC_DIF_RESUMEN.', v_contador);
                
                INSERT INTO INYCEXT.INYC_LC_DIF_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        NULL AS N_CREDITO,NULL AS V_CREDITO,NULL AS C_GN4,
                        NULL AS FIRSTNAME_AG,NULL AS MIDDLENAME_AG,NULL AS LASTNAME_AG,NULL AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        AND I.TENANTID = 'INYC'
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_DIF_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_DIF_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_DIF_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_DIF_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_DIF_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_DIF_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_DIF_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_DIF_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_DIF_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_DIF_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_DIF_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_DIF_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_DIF_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICNUMBER4 AS C_GN4,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                        AND PMCT.TENANTID = 'INYC' 
                    LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_DIF_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_BAL_DIF_RESUMEN.', v_contador);
                
                INSERT INTO INYCEXT.INYC_BAL_DIF_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        NULL AS N_CREDITO,NULL AS V_CREDITO,NULL AS C_GN4,
                        NULL AS FIRSTNAME_AG,NULL AS MIDDLENAME_AG,NULL AS LASTNAME_AG,NULL AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        AND I.TENANTID = 'INYC'
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_DIF_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_DIF_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_DIF_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_DIF_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_DIF_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_DIF_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_DIF_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_DIF_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --Carga tabla de Informe Diferenciales - Inspector Detalle 
    --ALM 20180119: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'DIF' OR informe like '%,DIF,%' OR informe like '%,DIF' OR informe like 'DIF,%' OR informe = 'ALL' THEN
    IF informe = 'DIF_DETALLE' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_DIF_DETALLE.', v_contador);

            DELETE INYCEXT.INYC_DIF_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_DIF_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_DIF_DETALLE.', v_contador);

            INSERT INTO INYCEXT.INYC_DIF_DETALLE 
                SELECT DISTINCT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_OCASO,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,C.GENERICNUMBER4 AS TIPO_PRIORIDAD_PRODUCTO,
                        COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                        ST.EVENTO,
                        --ALM 20171229: Modificamos la carga de la tabla para devolvernos el nombre del incentivo (mensual o anual) para el nuevo informe de Regularizaci�n de Diferenciales
                        --CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),
                        I.NAME AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20160923: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                        AND COM.PERIODSEQ = C.PERIODSEQ
                        AND COM.TENANTID = 'INYC'
                    INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                        AND COM.PERIODSEQ = I.PERIODSEQ 
                        AND I.TENANTID = 'INYC'
                        AND I.NAME LIKE 'C-O-DIF-%'
                        --ALM 20170103: Filtramos las reglas anuales ya que se cargan en la nueva carga Anual
                        AND I.NAME NOT LIKE '%-Anual'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_DIF_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
            
            IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                w_debug('Inicio Carga INYC_DIF_DETALLE. Anual', v_contador);

                INSERT INTO INYCEXT.INYC_DIF_DETALLE 
                    SELECT DISTINCT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PD.PERIODSEQ,PD.NAME,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_OCASO,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,C.GENERICNUMBER4 AS TIPO_PRIORIDAD_PRODUCTO,
                        COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL,
                        CAST(C.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        C.GENERICATTRIBUTE1,C.GENERICATTRIBUTE2,'' AS ACCOUNTINGDATE,C.GENERICNUMBER5,'' AS GENERICDATE2, 
                        '' ASEVENTO,
                        I.NAME AS TIPO_CREDITO,
                        '' AS PRODUCTO,
                        '' AS POSITIONNAME_AG,
                        '' AS FIRSTNAME_AG,'' AS LASTNAME_AG,'' AS SUFFIX_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        '' AS POLIZ_NP
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN CSA_PERIODDIMENSION PD ON PD.YEAR = PAD_INS.YEAR
                        AND PD.TENANTID = 'INYC'
                    INNER JOIN TCMP.CS_CREDIT C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.PERIODSEQ IN PD.PERIODSEQ
                        AND C.TENANTID = 'INYC'
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON C.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                        AND COM.PERIODSEQ = C.PERIODSEQ
                        AND COM.TENANTID = 'INYC'
                    INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ
                        AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                        --AND COM.PERIODSEQ = I.PERIODSEQ 
                        AND I.TENANTID = 'INYC'
                        AND I.NAME LIKE 'C-O-DIF-%-Anual'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_DIF_DETALLE. Anual: '|| to_char(filas) || ' filas.', v_contador);
            END IF;
            
            
            w_debug('Inicio Actualizacion Indices INYC_DIF_DETALLE.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_DIF_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_DIF_DETALLE');

            w_debug('Fin Actualizacion Indices INYC_DIF_DETALLE.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_DIF_DETALLE',v_contador);

            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_DIF_DETALLE');
        
            w_debug('Fin actualizacion del parametro INYC_DIF_DETALLE',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_DIF_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_LC_DIF_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_DIF_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_DIF_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_DIF_DETALLE 
                    SELECT DISTINCT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_OCASO,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,C.GENERICNUMBER4 AS TIPO_PRIORIDAD_PRODUCTO,
                        COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                        ST.EVENTO,
                        --ALM 20171229: Modificamos la carga de la tabla para devolvernos el nombre del incentivo (mensual o anual) para el nuevo informe de Regularizaci�n de Diferenciales
                        --CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),
                        I.NAME AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20160923: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                        AND COM.PERIODSEQ = C.PERIODSEQ
                        AND COM.TENANTID = 'INYC'
                    INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                        AND COM.PERIODSEQ = I.PERIODSEQ 
                        AND I.TENANTID = 'INYC'
                        AND I.NAME LIKE 'C-O-DIF-%'
                        --ALM 20170103: Filtramos las reglas anuales ya que se cargan en la nueva carga Anual
                        AND I.NAME NOT LIKE '%-Anual'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_DIF_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
            
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                    w_debug('Inicio Carga INYC_LC_DIF_DETALLE. Anual', v_contador);

                    INSERT INTO INYCEXT.INYC_LC_DIF_DETALLE 
                        SELECT DISTINCT
                            PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                            PD.PERIODSEQ,PD.NAME,
                            PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                            PAD_INS.CUADRO_INSP_OCASO,
                            C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,C.GENERICNUMBER4 AS TIPO_PRIORIDAD_PRODUCTO,
                            COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL,
                            CAST(C.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                            C.GENERICATTRIBUTE1,C.GENERICATTRIBUTE2,'' AS ACCOUNTINGDATE,C.GENERICNUMBER5,'' AS GENERICDATE2, 
                            '' ASEVENTO,
                            I.NAME AS TIPO_CREDITO,
                            '' AS PRODUCTO,
                            '' AS POSITIONNAME_AG,
                            '' AS FIRSTNAME_AG,'' AS LASTNAME_AG,'' AS SUFFIX_AG,
                            PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                            '' AS POLIZ_NP
                        FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                        INNER JOIN CSA_PERIODDIMENSION PD ON PD.YEAR = PAD_INS.YEAR
                            AND PD.TENANTID = 'INYC'
                        INNER JOIN TCMP.CS_CREDIT C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                            AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                            AND C.PERIODSEQ IN PD.PERIODSEQ
                            AND C.TENANTID = 'INYC'
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON C.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                            AND REG.COD_INFORME = 7.2
                            AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        INNER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                            AND COM.PERIODSEQ = C.PERIODSEQ
                            AND COM.TENANTID = 'INYC'
                        INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ
                            AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                            --AND COM.PERIODSEQ = I.PERIODSEQ 
                            AND I.TENANTID = 'INYC'
                            AND I.NAME LIKE 'C-O-DIF-%-Anual'
                        INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                            AND AG.COD_INFORME = 7
                            AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        ;
                                
                    filas := sql%rowcount;            
                    COMMIT;           
                        
                    w_debug('Fin Carga INYC_LC_DIF_DETALLE. Anual: '|| to_char(filas) || ' filas.', v_contador);
                END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_DIF_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_DIF_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_DIF_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_LC_DIF_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_DIF_DETALLE',v_contador);

                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_DIF_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_LC_DIF_DETALLE',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_DIF_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_BAL_DIF_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_DIF_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_DIF_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_DIF_DETALLE 
                    SELECT DISTINCT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_OCASO,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,C.GENERICNUMBER4 AS TIPO_PRIORIDAD_PRODUCTO,
                        COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL,
                        CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.VALUE,ST.GENERICDATE2, 
                        ST.EVENTO,
                        --ALM 20171229: Modificamos la carga de la tabla para devolvernos el nombre del incentivo (mensual o anual) para el nuevo informe de Regularizaci�n de Diferenciales
                        --CAST(ST.SALESTRANSACTIONSEQ AS VARCHAR2(127 BYTE)),
                        I.NAME AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20160923: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 7.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                        AND COM.PERIODSEQ = C.PERIODSEQ
                        AND COM.TENANTID = 'INYC'
                    INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                        AND COM.PERIODSEQ = I.PERIODSEQ 
                        AND I.TENANTID = 'INYC'
                        AND I.NAME LIKE 'C-O-DIF-%'
                        --ALM 20170103: Filtramos las reglas anuales ya que se cargan en la nueva carga Anual
                        AND I.NAME NOT LIKE '%-Anual'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 7
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_DIF_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
            
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                    w_debug('Inicio Carga INYC_BAL_DIF_DETALLE. Anual', v_contador);

                    INSERT INTO INYCEXT.INYC_BAL_DIF_DETALLE 
                        SELECT DISTINCT
                            PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                            PD.PERIODSEQ,PD.NAME,
                            PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                            PAD_INS.CUADRO_INSP_OCASO,
                            C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,C.GENERICNUMBER4 AS TIPO_PRIORIDAD_PRODUCTO,
                            COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL,
                            CAST(C.SALESTRANSACTIONSEQ AS VARCHAR2(127)) AS SALESTRANSACTIONSEQ,
                            C.GENERICATTRIBUTE1,C.GENERICATTRIBUTE2,'' AS ACCOUNTINGDATE,C.GENERICNUMBER5,'' AS GENERICDATE2, 
                            '' ASEVENTO,
                            I.NAME AS TIPO_CREDITO,
                            '' AS PRODUCTO,
                            '' AS POSITIONNAME_AG,
                            '' AS FIRSTNAME_AG,'' AS LASTNAME_AG,'' AS SUFFIX_AG,
                            PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                            '' AS POLIZ_NP
                        FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                        INNER JOIN CSA_PERIODDIMENSION PD ON PD.YEAR = PAD_INS.YEAR
                            AND PD.TENANTID = 'INYC'
                        INNER JOIN TCMP.CS_CREDIT C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                            AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                            AND C.PERIODSEQ IN PD.PERIODSEQ
                            AND C.TENANTID = 'INYC'
                        --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                        INNER JOIN TCMP.CS_PLRUN PL ON C.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                        INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                            AND REG.COD_INFORME = 7.2
                            AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                        INNER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                            AND COM.PERIODSEQ = C.PERIODSEQ
                            AND COM.TENANTID = 'INYC'
                        INNER JOIN TCMP.CS_INCENTIVE I ON COM.INCENTIVESEQ = I.INCENTIVESEQ
                            AND COM.PIPELINERUNSEQ = I.PIPELINERUNSEQ
                            --AND COM.PERIODSEQ = I.PERIODSEQ 
                            AND I.TENANTID = 'INYC'
                            AND I.NAME LIKE 'C-O-DIF-%-Anual'
                        INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                            AND AG.COD_INFORME = 7
                            AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                        ;
                                
                    filas := sql%rowcount;            
                    COMMIT;           
                        
                    w_debug('Fin Carga INYC_BAL_DIF_DETALLE. Anual: '|| to_char(filas) || ' filas.', v_contador);
                END IF;
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_DIF_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_DIF_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_DIF_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_DIF_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_DIF_DETALLE',v_contador);

                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_DIF_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_DIF_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Incentivos por Cumplimiento de Objetivos y Liquidacion a Cuenta Resumen
    IF informe = 'COLC' OR informe LIKE '%,COLC,%' OR informe LIKE '%,COLC' OR informe LIKE 'COLC,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_COLC_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_COLC_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_COLC_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_COLC_RESUMEN.', v_contador);

            INSERT INTO INYCEXT.INYC_COLC_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_OCASO,
                    --C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICBOOLEAN1 AS PRIORITARIO,
                    NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 8.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                --ALM 20170619: No necesitamos medidas de todos agentes subordinados
                --LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                --    AND PMCT.TENANTID = 'INYC' 
                --LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                --LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                --LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                --    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 8
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_COLC_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
            
            --Semestre 1
            IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                w_debug('Inicio Carga Semestre Anterior (Junio) - INYC_COLC_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_COLC_RESUMEN 
                    SELECT COLC.PARTICIPANTSEQ,COLC.POSITIONSEQ_PRIN,COLC.PERIODSEQ,COLC.PERIODO,COLC.QUARTER,COLC.YEAR,COLC.STARTDATE,
                        CASE WHEN COLC.N_MEDIDA LIKE 'SM-O-COLC-Inspector-Pago-00%' THEN COLC.N_MEDIDA || '-Junio' END AS N_MEDIDA,
                        --ALM 20180102: Cogemos el valor de la tabla de balances para el dato pagado en Junio para cada l�nea de producto.
                        --(SELECT X.V_MEDIDA FROM INYCEXT.INYC_COLC_RESUMEN X
                        (SELECT X.V_MEDIDA FROM INYCEXT.INYC_BAL_COLC_RESUMEN X
                            WHERE X.PARTICIPANTSEQ = COLC.PARTICIPANTSEQ
                                AND X.POSITIONSEQ_PRIN = COLC.POSITIONSEQ_PRIN
                                AND X.N_MEDIDA = COLC.N_MEDIDA
                                AND X.YEAR = COLC.YEAR
                                AND X.PERIODO LIKE 'Junio %'
                        ) AS V_MEDIDA,
                        COLC.BOUSERID,COLC.FIRSTNAME,COLC.MIDDLENAME,COLC.LASTNAME,COLC.POSITIONNAME,COLC.CUADRO,
                        --COLC.N_CREDITO,COLC.V_CREDITO,COLC.PRIORITARIO,
                        COLC.FIRSTNAME_AG,COLC.MIDDLENAME_AG,COLC.LASTNAME_AG,COLC.POSITIONNAME_AG,
                        COLC.POS_PRIN,COLC.ID_TIPO_AGENTE,COLC.TIPO_AGENTE,COLC.NIF
                    FROM INYCEXT.INYC_COLC_RESUMEN COLC
                    WHERE COLC.PERIODSEQ = v_periodRow.PERIODSEQ
                        AND COLC.N_MEDIDA LIKE 'SM-O-COLC-Inspector-Pago-00%' AND COLC.N_MEDIDA NOT LIKE '%Junio%';
                     
                filas := sql%rowcount;            
                COMMIT;           
                
                w_debug('Fin Carga Semestre Anterior (Junio) - INYC_COLC_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
            END IF;
            
            w_debug('Inicio Carga INYC_COLC_RESUMEN. Agentes Captados.', v_contador);

            INSERT INTO INYCEXT.INYC_COLC_RESUMEN 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,PAD_INS.CUADRO_INSP_OCASO,
                    PAD_AG.FIRSTNAME AS FIRSTNAME_AG,PAD_AG.LASTNAME AS LASTNAME_AG,PAD_AG.SUFFIX AS SUFFIX_AG,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 8
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.YEAR = PAD_AG.POSITIONGENERICATTRIBUTE13
                    AND PAD_INS.POS_CALLIDUS = PAD_AG.POSITIONGENERICATTRIBUTE14
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_AG.PERIODSEQ = M.PERIODSEQ
                    AND PAD_AG.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_AG.PARTICIPANTSEQ = M.PAYEESEQ
                    AND (M.NAME = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalAnual'
                        OR M.NAME = 'SM-O-GEN-Agente-Prima-998-TotalAnual')
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_COLC_RESUMEN. Agentes Captados: '|| to_char(filas) || ' filas.', v_contador);

            
            w_debug('Inicio Actualizacion Indices INYC_COLC_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_COLC_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_COLC_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_COLC_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_COLC_RESUMEN',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_COLC_RESUMEN');
        
            w_debug('Fin actualizacion del parametro INYC_COLC_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_COLC_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_COLC_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
