                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_COLC_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_COLC_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_COLC_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_COLC_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_COLC_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_COLC_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_COLC_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_COLC_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_COLC_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_COLC_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_COLC_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        --C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICBOOLEAN1 AS PRIORITARIO,
                        NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 8.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    --ALM 20170619: No necesitamos medidas de todos agentes subordinados
                    --LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    --    AND PMCT.TENANTID = 'INYC' 
                    --LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    --LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    --LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    --    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 8
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_COLC_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                --Semestre 1
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                    w_debug('Inicio Carga Semestre Anterior (Junio) - INYC_BAL_COLC_RESUMEN.', v_contador);

                    INSERT INTO INYCEXT.INYC_BAL_COLC_RESUMEN 
                        SELECT COLC.PARTICIPANTSEQ,COLC.POSITIONSEQ_PRIN,COLC.PERIODSEQ,COLC.PERIODO,COLC.QUARTER,COLC.YEAR,COLC.STARTDATE,
                            CASE WHEN COLC.N_MEDIDA LIKE 'SM-O-COLC-Inspector-Pago-00%' THEN COLC.N_MEDIDA || '-Junio' END AS N_MEDIDA,
                            (SELECT X.V_MEDIDA FROM INYCEXT.INYC_BAL_COLC_RESUMEN X
                                WHERE X.PARTICIPANTSEQ = COLC.PARTICIPANTSEQ
                                    AND X.POSITIONSEQ_PRIN = COLC.POSITIONSEQ_PRIN
                                    AND X.N_MEDIDA = COLC.N_MEDIDA
                                    AND X.YEAR = COLC.YEAR
                                    AND X.PERIODO LIKE 'Junio %'
                            ) AS V_MEDIDA,
                            COLC.BOUSERID,COLC.FIRSTNAME,COLC.MIDDLENAME,COLC.LASTNAME,COLC.POSITIONNAME,COLC.CUADRO,
                            --COLC.N_CREDITO,COLC.V_CREDITO,COLC.PRIORITARIO,
                            COLC.FIRSTNAME_AG,COLC.MIDDLENAME_AG,COLC.LASTNAME_AG,COLC.POSITIONNAME_AG,
                            COLC.POS_PRIN,COLC.ID_TIPO_AGENTE,COLC.TIPO_AGENTE,COLC.NIF
                        FROM INYCEXT.INYC_BAL_COLC_RESUMEN COLC
                        WHERE COLC.PERIODSEQ = v_periodRow.PERIODSEQ
                            AND COLC.N_MEDIDA LIKE 'SM-O-COLC-Inspector-Pago-00%' AND COLC.N_MEDIDA NOT LIKE '%Junio%';
                         
                    filas := sql%rowcount;            
                    COMMIT;           
                    
                    w_debug('Fin Carga Semestre Anterior (Junio) - INYC_BAL_COLC_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                END IF;
                
                w_debug('Inicio Carga INYC_BAL_COLC_RESUMEN. Agentes Captados.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_COLC_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,PAD_INS.CUADRO_INSP_OCASO,
                        PAD_AG.FIRSTNAME AS FIRSTNAME_AG,PAD_AG.LASTNAME AS LASTNAME_AG,PAD_AG.SUFFIX AS SUFFIX_AG,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 8
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.YEAR = PAD_AG.POSITIONGENERICATTRIBUTE13
                        AND PAD_INS.POS_CALLIDUS = PAD_AG.POSITIONGENERICATTRIBUTE14
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_AG.PERIODSEQ = M.PERIODSEQ
                        AND PAD_AG.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_AG.PARTICIPANTSEQ = M.PAYEESEQ
                        AND (M.NAME = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalAnual'
                            OR M.NAME = 'SM-O-GEN-Agente-Prima-998-TotalAnual')
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_COLC_RESUMEN. Agentes Captados: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_COLC_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_COLC_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_COLC_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_COLC_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_COLC_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_COLC_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_COLC_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Anulaciones de Primer Ano Resumen
    IF informe = 'AN' OR informe LIKE '%,AN,%' OR informe LIKE '%,AN' OR informe LIKE 'AN,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_AN_RESUMEN.', v_contador);
            
            --ALM 20210111: No cargamos datos de las anulaciones de primer anio hasta que este bien los calculos.
            --ALM 20210128: Volvemos a incluir la recarga de las AN1 en el informe.
            DELETE INYCEXT.INYC_AN_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            --DELETE INYCEXT.INYC_AN_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ AND N_MEDIDA NOT LIKE 'SM-O-AN1-%';
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_AN_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_AN_RESUMEN. Medidas.', v_contador);

            INSERT INTO INYCEXT.INYC_AN_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                    --ALM 20210108: No cargamos datos de las anulaciones de primer anio hasta que este bien los calculos.
                    --ALM 20210128: Volvemos a incluir la recarga de las AN1 en el informe.
                    --AND M.NAME NOT LIKE 'SM-O-AN1-%'
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 12.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 12
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_AN_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
            
            --ALM 20171212: Anadimos los incentivos para el importe del pago de las anulaciones 
            w_debug('Inicio Carga INYC_AN_RESUMEN. Incentivos.', v_contador);

            INSERT INTO INYCEXT.INYC_AN_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                    --ALM 20171222: Nos quedamos solo con los incentivos calculados para poder filtrar en el informe a los insp. que no cobren
                    AND I.RULESEQ IS NOT NULL
                    --AND I.VALUE <> 0
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                    AND REG.COD_INFORME = 12.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 12
