                --ALM 20210128: Volvemos a incluir la recarga de las AN1 y AN2 en el informe.
                DELETE INYCEXT.INYC_BAL_AN_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                --DELETE INYCEXT.INYC_BAL_AN_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ AND N_MEDIDA NOT LIKE 'SM-O-AN1-%'
