                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_AN_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_LC_AN_DETALLE',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_AN_DETALLE.', v_contador);

                --ALM 20210111: No cargamos datos de las anulaciones de primer anio hasta que este bien los calculos.
                --ALM 20210128: Volvemos a incluir la recarga de las AN1 en el informe.
                DELETE INYCEXT.INYC_BAL_AN_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                --DELETE INYCEXT.INYC_BAL_AN_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ AND NAME NOT LIKE '%C-O-AN1-%';
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_AN_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_AN_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_AN_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        ST.RECIBO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                        --ALM 20210113: Filtramos para no tener en cuenta los creditos directos que pertenecen a inspectores que 
                        --              cuando emitieron la poliza eran agentes
                        AND (C.NAME LIKE 'IC-%' OR C.GENERICBOOLEAN3 = 0)
                        --ALM 20210108: No cargamos datos de las anulaciones de primer anio hasta que este bien los calculos.
                        --ALM 20210128: Volvemos a incluir la recarga de las AN1 en el informe.
                        --AND C.NAME NOT LIKE '%C-O-AN1-%'
                        --AND C.GENERICATTRIBUTE2 NOT LIKE '01103%'
                        --AND C.GENERICATTRIBUTE2 NOT LIKE '01106%'
                        --AND C.GENERICATTRIBUTE2 NOT LIKE '01108%'
                        --AND C.GENERICATTRIBUTE2 NOT LIKE '01503%'
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    --INNER JOIN TCMP.CS_TRANSACTIONASSIGNMENT TA ON ST.SALESTRANSACTIONSEQ = TA.SALESTRANSACTIONSEQ
                    --    AND TA.TENANTID = 'INYC'
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 12.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 12
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_AN_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_AN_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_AN_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_AN_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_AN_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_AN_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_AN_DETALLE');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_AN_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Diferenciales Eterna Resumen
    IF informe = 'DIF_E' OR informe LIKE '%,DIF_E,%' OR informe LIKE '%,DIF_E' OR informe LIKE 'DIF_E,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_DIF_E_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_DIF_E_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_DIF_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_DIF_E_RESUMEN. Medidas.', v_contador);

            INSERT INTO INYCEXT.INYC_DIF_E_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_ETERNA,
                    C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --ALM 20161021: Debido al cambio de tipologias activamos este filtro para que no salga todo el mundo.
                    --              Lo malo que para los de eterna que no tengan medidas tampoco les saldra.
                    AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 13.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    AND PMCT.TENANTID = 'INYC' 
                LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 13
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_DIF_E_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);

            w_debug('Inicio Carga INYC_DIF_E_RESUMEN. Incentivos.', v_contador);

            INSERT INTO INYCEXT.INYC_DIF_E_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_ETERNA,
                    NULL AS N_CREDITO,NULL AS V_CREDITO,
                    NULL AS FIRSTNAME_AG,NULL AS MIDDLENAME_AG,NULL AS LASTNAME_AG,NULL AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                    AND I.TENANTID = 'INYC'
                    --AND I.VALUE <> 0
                --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                    AND REG.COD_INFORME = 13.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 13
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_DIF_E_RESUMEN. Incentivos: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_DIF_E_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_DIF_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_DIF_E_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_DIF_E_RESUMEN.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_DIF_E_RESUMEN',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_DIF_E_RESUMEN');
        
            w_debug('Fin actualizacion del parametro INYC_DIF_E_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_DIF_E_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_DIF_E_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_DIF_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_DIF_E_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_DIF_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --ALM 20161021: Debido al cambio de tipologias activamos este filtro para que no salga todo el mundo.
                        --              Lo malo que para los de eterna que no tengan medidas tampoco les saldra.
                        AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 13.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                        AND PMCT.TENANTID = 'INYC' 
                    LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 13
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_DIF_E_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_LC_DIF_E_RESUMEN. Incentivos.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_DIF_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        NULL AS N_CREDITO,NULL AS V_CREDITO,
                        NULL AS FIRSTNAME_AG,NULL AS MIDDLENAME_AG,NULL AS LASTNAME_AG,NULL AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        AND I.TENANTID = 'INYC'
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                        AND REG.COD_INFORME = 13.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 13
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_DIF_E_RESUMEN. Incentivos: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_DIF_E_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_DIF_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_DIF_E_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_DIF_E_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_DIF_E_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_DIF_E_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_DIF_E_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_DIF_E_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_DIF_E_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_DIF_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_DIF_E_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_DIF_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --ALM 20161021: Debido al cambio de tipologias activamos este filtro para que no salga todo el mundo.
                        --              Lo malo que para los de eterna que no tengan medidas tampoco les saldra.
                        AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 13.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                        AND PMCT.TENANTID = 'INYC' 
                    LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 13
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_DIF_E_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_BAL_DIF_E_RESUMEN. Incentivos.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_DIF_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA, I.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        NULL AS N_CREDITO,NULL AS V_CREDITO,
                        NULL AS FIRSTNAME_AG,NULL AS MIDDLENAME_AG,NULL AS LASTNAME_AG,NULL AS POSITIONNAME_AG,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        AND I.TENANTID = 'INYC'
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                        AND REG.COD_INFORME = 13.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 13
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_DIF_E_RESUMEN. Incentivos: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_DIF_E_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_DIF_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_DIF_E_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_DIF_E_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_DIF_E_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_DIF_E_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_DIF_E_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --Carga tabla de Informe Diferenciales Eterna Detalle 
    --ALM 20180119: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'DIF_E' OR informe like '%,DIF_E,%' OR informe like '%,DIF_E' OR informe like 'DIF_E,%' OR informe = 'ALL' THEN
    IF informe = 'DIF_E_DETALLE' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_DIF_E_DETALLE.', v_contador);

            DELETE INYCEXT.INYC_DIF_E_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_DIF_E_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_DIF_E_DETALLE.', v_contador);

            INSERT INTO INYCEXT.INYC_DIF_E_DETALLE 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                    PAD_INS.CUADRO_INSP_ETERNA,
                    C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                    --ALM 20160923: Anadimos un campo para contar las Polizas de Nueva Produccion
                    --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                    --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                    ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                    ST.EVENTO,
                    CT.DESCRIPTION AS TIPO_CREDITO,
                    ST.PRODUCTO,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                    AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                    AND C.VALUE <> 0
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                    AND REG.COD_INFORME = 13.2
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                LEFT OUTER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                    AND COM.TENANTID = 'INYC'
                LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                    AND CT.REMOVEDATE = v_eot
                    AND CT.TENANTID = 'INYC'
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 13
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_DIF_E_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_DIF_E_DETALLE.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_DIF_E_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_DIF_E_DETALLE');

            w_debug('Fin Actualizacion Indices INYC_DIF_E_DETALLE.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_DIF_E_DETALLE',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_DIF_E_DETALLE');
            
            w_debug('Fin actualizacion del parametro INYC_DIF_E_DETALLE',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_DIF_E_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_LC_DIF_E_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_DIF_E_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_DIF_E_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_DIF_E_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        --ALM 20160923: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 13.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                        AND COM.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 13
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_DIF_E_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_DIF_E_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_DIF_E_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_DIF_E_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_LC_DIF_E_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_DIF_E_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_DIF_E_DETALLE');
                
                w_debug('Fin actualizacion del parametro INYC_LC_DIF_E_DETALLE',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_DIF_E_DETALLE.', v_contador);

                DELETE INYCEXT.INYC_BAL_DIF_E_DETALLE WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_DIF_E_DETALLE: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_DIF_E_DETALLE.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_DIF_E_DETALLE 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        C.NAME,C.VALUE,C.GENERICNUMBER1 AS C_GN1,
                        --ALM 20160923: Anadimos un campo para contar las Polizas de Nueva Produccion
                        --ALM 20170911: Utilizamos el EVENTYPESEQ de la transaccion en lugar de la descripcion para evitar problemas con las tildes
                        --CASE WHEN ST.EVENTO = 'Alta Nueva Produccion' AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        CASE WHEN ST.EVENTTYPESEQ = 16607023625928867 AND ST.GARANTIA = 0 AND C.NAME LIKE '%-998' THEN 1*SIGN(C.VALUE) ELSE 0 END AS POLIZ_NP,
                        ST.GENERICATTRIBUTE1,ST.PRODUCTID,ST.ACCOUNTINGDATE,ST.GENERICDATE2,ST.GENERICNUMBER1,ST.GENERICNUMBER2,ST.VALUE, 
                        ST.EVENTO,
                        CT.DESCRIPTION AS TIPO_CREDITO,
                        ST.PRODUCTO,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        COM.RATEVALUE AS PORC_DIFERENCIAL,COM.VALUE AS IMP_DIFERENCIAL
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PAD_INS.PARTICIPANTSEQ = C.PAYEESEQ 
                        AND PAD_INS.PERIODSEQ = C.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = C.POSITIONSEQ
                        AND C.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                        AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON C.NAME = REG.REGLA
                        AND REG.COD_INFORME = 13.2
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE
                    LEFT OUTER JOIN TCMP.CS_COMMISSION COM ON C.CREDITSEQ = COM.CREDITSEQ
                        AND COM.TENANTID = 'INYC'
                    LEFT OUTER JOIN TCMP.CS_CREDITTYPE CT ON C.CREDITTYPESEQ = CT.DATATYPESEQ
                        AND CT.REMOVEDATE = v_eot
                        AND CT.TENANTID = 'INYC'
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 13
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_DIF_E_DETALLE: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_DIF_E_DETALLE.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_DIF_E_DETALLE COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_DIF_E_DETALLE');

                w_debug('Fin Actualizacion Indices INYC_BAL_DIF_E_DETALLE.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_DIF_E_DETALLE',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_DIF_E_DETALLE');
                
                w_debug('Fin actualizacion del parametro INYC_BAL_DIF_E_DETALLE',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Produccion Propia Resumen
    IF informe = 'PP' OR informe LIKE '%,PP,%' OR informe LIKE '%,PP' OR informe LIKE 'PP,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_PP_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_PP_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_PP_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_PP_RESUMEN.', v_contador);

            INSERT INTO INYCEXT.INYC_PP_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.POS_PRIN,
                    PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                    --ALM 20180312: Anadimos el NIF para actualizar la cabecera del informe
                    PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 14.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 14
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --ALM 20180312: Quitamos el filtro de los meses para tener los datos de los agentes en cada periodo
                --WHERE PAD_INS.BOUSERID IN (
                --        SELECT DISTINCT X.BOUSERID FROM INYCEXT.INYC_AGENTES_MES_TEMP X 
                --        INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP Y ON X.PERIODSEQ = Y.PERIODSEQ
                --            AND X.POSITIONSEQ = Y.POSITIONSEQ
                --            AND X.PARTICIPANTSEQ = Y.PAYEESEQ
                --            --AND Y.VALUE <> 0
                --        WHERE X.BOUSERID = PAD_INS.BOUSERID
                --            AND Y.NAME = 'SM-O-GEN-Inspector-Meses'
                --            AND Y.VALUE IN (3,6,9,12))
                    --AND PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                            
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_PP_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
            w_debug('Inicio Actualizacion Indices INYC_PP_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_PP_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_PP_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_PP_RESUMEN.', v_contador);
                
                
            w_debug('Inicio actualizacion del parametro INYC_PP_RESUMEN',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_PP_RESUMEN');
            
            w_debug('Fin actualizacion del parametro INYC_PP_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_PP_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_PP_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_PP_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_PP_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_PP_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,
                        PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,
                        --ALM 20180312: Anadimos el NIF para actualizar la cabecera del informe
                        PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 14.1
