                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                INNER JOIN TCMP.CS_PMCREDITTRACE PM ON M.MEASUREMENTSEQ = PM.MEASUREMENTSEQ
                INNER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PM.CREDITSEQ = C.CREDITSEQ
                    AND (C.VALUE <> 0 OR C.GENERICNUMBER4 <> 0)
                INNER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON ST.SALESTRANSACTIONSEQ = C.SALESTRANSACTIONSEQ 
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 14.2
