                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_COMU_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_COMU_RESUMEN.', v_contador);

