                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,0 AS V_QUOTA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 22.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 22
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_MIN_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_LC_MIN_RESUMEN. Incentivos.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_MIN_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA,I.VALUE AS V_MEDIDA,I.GENERICNUMBER1 AS V_QUOTA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                        AND REG.COD_INFORME = 22.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 22
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_MIN_RESUMEN. Incentivos: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_MIN_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_MIN_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_MIN_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_MIN_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_MIN_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_MIN_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_MIN_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_MIN_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_MIN_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_MIN_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_MIN_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_MIN_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,0 AS V_QUOTA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 22.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 22
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_MIN_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);

                w_debug('Inicio Carga INYC_BAL_MIN_RESUMEN. Incentivos.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_MIN_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO, PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        I.NAME AS N_MEDIDA,I.VALUE AS V_MEDIDA,I.GENERICNUMBER1 AS V_QUOTA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN TCMP.CS_INCENTIVE I ON PAD_INS.PERIODSEQ = I.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = I.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = I.PAYEESEQ
                        --AND I.VALUE <> 0
                    --ALM 20191008: Anadimos condicion para no coger posibles resultados de los MODELS
                    INNER JOIN TCMP.CS_PLRUN PL ON I.PIPELINERUNSEQ = PL.PIPELINERUNSEQ AND PL.MODELSEQ = 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON I.NAME = REG.REGLA
                        AND REG.COD_INFORME = 22.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 22
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_MIN_RESUMEN. Incentivos: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_MIN_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_MIN_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_MIN_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_MIN_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_MIN_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_MIN_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_MIN_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Rappel Actividad Agentes con Grupo (Liquidacion a Cuenta)
    IF informe = 'REA' OR informe LIKE '%,REA,%' OR informe LIKE '%,REA' OR informe LIKE 'REA,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_REA_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_REA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_REA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_REA_RESUMEN. Medidas.', v_contador);

            INSERT INTO INYCEXT.INYC_REA_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_OCASO,
                    --ALM 20170615: No necesitamos medidas de todos agentes subordinados
                    --C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICBOOLEAN1 AS PRIORITARIO,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                    --PAD_AG.POSITIONGENERICATTRIBUTE13 AS ANIO_CAPTACION,PAD_AG.POSITIONGENERICATTRIBUTE14 AS INSP_CAPTADOR,PAD_INS.POS_CALLIDUS
                    NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 23.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                --ALM 20170615: No necesitamos medidas de todos agentes subordinados
                --LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                --    AND PMCT.TENANTID = 'INYC' 
                --LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                --LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                --LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                --    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 23
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                            
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_REA_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
            --Incluimos INSERT para cargar en Diciembre lo calculado en Junio
            IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                w_debug('Inicio Carga Semestre Anterior (Junio) - INYC_REA_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_REA_RESUMEN 
                    SELECT REA.PARTICIPANTSEQ,REA.POSITIONSEQ_PRIN,REA.PERIODSEQ,REA.PERIODO,REA.QUARTER,REA.YEAR,REA.STARTDATE,
                        CASE WHEN REA.N_MEDIDA = 'SM-O-REA-Inspector-Pago' THEN REA.N_MEDIDA || '-Junio' END AS N_MEDIDA,
                        --ALM 20181227: Tenemos que utilizar la tabla de balances porque son los datos finales del periodo.
                        --(SELECT X.V_MEDIDA FROM INYCEXT.INYC_REA_RESUMEN X
                        (SELECT X.V_MEDIDA FROM INYCEXT.INYC_BAL_REA_RESUMEN X
                            WHERE X.PARTICIPANTSEQ = REA.PARTICIPANTSEQ
                                AND X.POSITIONSEQ_PRIN = REA.POSITIONSEQ_PRIN
                                AND X.N_MEDIDA = REA.N_MEDIDA
                                AND X.YEAR = REA.YEAR
                                AND X.PERIODO LIKE 'Junio %'
                        ) AS V_MEDIDA,
                        REA.BOUSERID,REA.FIRSTNAME,REA.MIDDLENAME,REA.LASTNAME,REA.POSITIONNAME,REA.CUADRO,
                        --REA.N_CREDITO,REA.V_CREDITO,REA.PRIORITARIO,
                        REA.POS_PRIN,REA.ID_TIPO_AGENTE,REA.TIPO_AGENTE,REA.NIF,
                        --REA.ANIO_CAPTACION,REA.INSP_CAPTADOR,REA.NIF,REA.POS_CALLIDUS
                        REA.FIRSTNAME_AG,REA.LASTNAME_AG,REA.SUFFIX_AG,REA.POSITIONNAME_AG
                    FROM INYCEXT.INYC_REA_RESUMEN REA
                    WHERE REA.PERIODSEQ = v_periodRow.PERIODSEQ
                        AND REA.N_MEDIDA = 'SM-O-REA-Inspector-Pago';
                         
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga Semestre Anterior (Junio) - INYC_REA_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                    
            END IF;
                
            w_debug('Inicio Carga INYC_REA_RESUMEN. Agentes Captados.', v_contador);

            INSERT INTO INYCEXT.INYC_REA_RESUMEN 
                SELECT
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_OCASO,PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                    PAD_AG.FIRSTNAME AS FIRSTNAME_AG,PAD_AG.LASTNAME AS LASTNAME_AG,PAD_AG.SUFFIX AS SUFFIX_AG,
                    PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 23
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.YEAR = PAD_AG.POSITIONGENERICATTRIBUTE13
                    AND PAD_INS.POS_CALLIDUS = PAD_AG.POSITIONGENERICATTRIBUTE14
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_AG.PERIODSEQ = M.PERIODSEQ
                    AND PAD_AG.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_AG.PARTICIPANTSEQ = M.PAYEESEQ
                    AND (M.NAME = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalAnual'
                        OR M.NAME = 'SM-O-GEN-Agente-Prima-998-TotalAnual')
                ;
                            
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_REA_RESUMEN. Agentes Captados: '|| to_char(filas) || ' filas.', v_contador);
                
                
            w_debug('Inicio Actualizacion Indices INYC_REA_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_REA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_REA_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_REA_RESUMEN.', v_contador);
                
                
            w_debug('Inicio actualizacion del parametro INYC_REA_RESUMEN',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_REA_RESUMEN');
            
            w_debug('Fin actualizacion del parametro INYC_REA_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_REA_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_REA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_REA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_REA_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_REA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        --ALM 20170615: No necesitamos medidas de todos agentes subordinados
                        --C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICBOOLEAN1 AS PRIORITARIO,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        --PAD_AG.POSITIONGENERICATTRIBUTE13 AS ANIO_CAPTACION,PAD_AG.POSITIONGENERICATTRIBUTE14 AS INSP_CAPTADOR,PAD_INS.POS_CALLIDUS
                        NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 23.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    --ALM 20170615: No necesitamos medidas de todos agentes subordinados
                    --LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    --    AND PMCT.TENANTID = 'INYC' 
                    --LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    --LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    --LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    --    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 23
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_REA_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
                --Incluimos INSERT para cargar en Diciembre lo calculado en Junio
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                    w_debug('Inicio Carga Semestre Anterior (Junio) - INYC_LC_REA_RESUMEN.', v_contador);

                    INSERT INTO INYCEXT.INYC_LC_REA_RESUMEN 
                        SELECT REA.PARTICIPANTSEQ,REA.POSITIONSEQ_PRIN,REA.PERIODSEQ,REA.PERIODO,REA.QUARTER,REA.YEAR,REA.STARTDATE,
                            CASE WHEN REA.N_MEDIDA = 'SM-O-REA-Inspector-Pago' THEN REA.N_MEDIDA || '-Junio' END AS N_MEDIDA,
                            (SELECT X.V_MEDIDA FROM INYCEXT.INYC_BAL_REA_RESUMEN X
                                WHERE X.PARTICIPANTSEQ = REA.PARTICIPANTSEQ
                                    AND X.POSITIONSEQ_PRIN = REA.POSITIONSEQ_PRIN
                                    AND X.N_MEDIDA = REA.N_MEDIDA
                                    AND X.YEAR = REA.YEAR
                                    AND X.PERIODO LIKE 'Junio %'
                            ) AS V_MEDIDA,
                            REA.BOUSERID,REA.FIRSTNAME,REA.MIDDLENAME,REA.LASTNAME,REA.POSITIONNAME,REA.CUADRO,
                            --REA.N_CREDITO,REA.V_CREDITO,REA.PRIORITARIO,
                            REA.POS_PRIN,REA.ID_TIPO_AGENTE,REA.TIPO_AGENTE,REA.NIF,
                            --REA.ANIO_CAPTACION,REA.INSP_CAPTADOR,REA.NIF,REA.POS_CALLIDUS
                            REA.FIRSTNAME_AG,REA.LASTNAME_AG,REA.SUFFIX_AG,REA.POSITIONNAME_AG
                        FROM INYCEXT.INYC_LC_REA_RESUMEN REA
                        WHERE REA.PERIODSEQ = v_periodRow.PERIODSEQ
                            AND REA.N_MEDIDA = 'SM-O-REA-Inspector-Pago';
                         
                    filas := sql%rowcount;            
                    COMMIT;           
                    
                    w_debug('Fin Carga Semestre Anterior (Junio) - INYC_LC_REA_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                    
                END IF;
                
                w_debug('Inicio Carga INYC_LC_REA_RESUMEN. Agentes Captados.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_REA_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        PAD_AG.FIRSTNAME AS FIRSTNAME_AG,PAD_AG.LASTNAME AS LASTNAME_AG,PAD_AG.SUFFIX AS SUFFIX_AG,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 23
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.YEAR = PAD_AG.POSITIONGENERICATTRIBUTE13
                        AND PAD_INS.POS_CALLIDUS = PAD_AG.POSITIONGENERICATTRIBUTE14
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_AG.PERIODSEQ = M.PERIODSEQ
                        AND PAD_AG.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_AG.PARTICIPANTSEQ = M.PAYEESEQ
                        AND (M.NAME = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalAnual'
                            OR M.NAME = 'SM-O-GEN-Agente-Prima-998-TotalAnual')
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_REA_RESUMEN. Agentes Captados: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_REA_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_REA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_REA_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_REA_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_REA_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_REA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_REA_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_REA_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_REA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_REA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_REA_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_REA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        --ALM 20170615: No necesitamos medidas de todos agentes subordinados
                        --C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICBOOLEAN1 AS PRIORITARIO,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        --PAD_AG.POSITIONGENERICATTRIBUTE13 AS ANIO_CAPTACION,PAD_AG.POSITIONGENERICATTRIBUTE14 AS INSP_CAPTADOR,PAD_INS.POS_CALLIDUS
                        NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 23.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    --ALM 20170615: No necesitamos medidas de todos agentes subordinados
                    --LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    --    AND PMCT.TENANTID = 'INYC' 
                    --LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                    --LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                    --LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    --    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 23
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_REA_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
                --Incluimos INSERT para cargar en Diciembre lo calculado en Junio
                IF SUBSTR(v_periodo,1,9) = 'Diciembre' THEN  
                    w_debug('Inicio Carga Semestre Anterior (Junio) - INYC_BAL_REA_RESUMEN.', v_contador);

                    INSERT INTO INYCEXT.INYC_BAL_REA_RESUMEN 
                        SELECT REA.PARTICIPANTSEQ,REA.POSITIONSEQ_PRIN,REA.PERIODSEQ,REA.PERIODO,REA.QUARTER,REA.YEAR,REA.STARTDATE,
                            CASE WHEN REA.N_MEDIDA = 'SM-O-REA-Inspector-Pago' THEN REA.N_MEDIDA || '-Junio' END AS N_MEDIDA,
                            (SELECT X.V_MEDIDA FROM INYCEXT.INYC_BAL_REA_RESUMEN X
                                WHERE X.PARTICIPANTSEQ = REA.PARTICIPANTSEQ
                                    AND X.POSITIONSEQ_PRIN = REA.POSITIONSEQ_PRIN
                                    AND X.N_MEDIDA = REA.N_MEDIDA
                                    AND X.YEAR = REA.YEAR
                                    AND X.PERIODO LIKE 'Junio %'
                            ) AS V_MEDIDA,
                            REA.BOUSERID,REA.FIRSTNAME,REA.MIDDLENAME,REA.LASTNAME,REA.POSITIONNAME,REA.CUADRO,
                            --REA.N_CREDITO,REA.V_CREDITO,REA.PRIORITARIO,
                            REA.POS_PRIN,REA.ID_TIPO_AGENTE,REA.TIPO_AGENTE,REA.NIF,
                            --REA.ANIO_CAPTACION,REA.INSP_CAPTADOR,REA.NIF,REA.POS_CALLIDUS
                            REA.FIRSTNAME_AG,REA.LASTNAME_AG,REA.SUFFIX_AG,REA.POSITIONNAME_AG
                        FROM INYCEXT.INYC_BAL_REA_RESUMEN REA
                        WHERE REA.PERIODSEQ = v_periodRow.PERIODSEQ
                            AND REA.N_MEDIDA = 'SM-O-REA-Inspector-Pago';
                         
                    filas := sql%rowcount;            
                    COMMIT;           
                    
                    w_debug('Fin Carga Semestre Anterior (Junio) - INYC_BAL_REA_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                    
                END IF;
                
                w_debug('Inicio Carga INYC_BAL_REA_RESUMEN. Agentes Captados.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_REA_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        PAD_AG.FIRSTNAME AS FIRSTNAME_AG,PAD_AG.LASTNAME AS LASTNAME_AG,PAD_AG.SUFFIX AS SUFFIX_AG,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 23
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.YEAR = PAD_AG.POSITIONGENERICATTRIBUTE13
                        AND PAD_INS.POS_CALLIDUS = PAD_AG.POSITIONGENERICATTRIBUTE14
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_AG.PERIODSEQ = M.PERIODSEQ
                        AND PAD_AG.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_AG.PARTICIPANTSEQ = M.PAYEESEQ
                        AND (M.NAME = 'SM-O-GEN-Agente-NumeroPolizas-998-TotalAnual'
                            OR M.NAME = 'SM-O-GEN-Agente-Prima-998-TotalAnual')
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_REA_RESUMEN. Agentes Captados: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_REA_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_REA_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_REA_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_REA_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_REA_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_REA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_REA_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Rappel Incremento Polizas en Cartera
    IF informe = 'RIP' OR informe LIKE '%,RIP,%' OR informe LIKE '%,RIP' OR informe LIKE 'RIP,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RIP_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_RIP_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_RIP_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_RIP_RESUMEN.', v_contador);
                
            INSERT INTO INYCEXT.INYC_RIP_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 24.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 24
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                            
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_RIP_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
            w_debug('Inicio Actualizacion Indices INYC_RIP_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_RIP_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_RIP_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_RIP_RESUMEN.', v_contador);
                
                
            w_debug('Inicio actualizacion del parametro INYC_RIP_RESUMEN',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_RIP_RESUMEN');
            
            w_debug('Fin actualizacion del parametro INYC_RIP_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_RIP_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_LC_RIP_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_RIP_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_RIP_RESUMEN.', v_contador);
                
                INSERT INTO INYCEXT.INYC_LC_RIP_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 24.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 24
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_RIP_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_RIP_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_RIP_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_RIP_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_LC_RIP_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_RIP_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_RIP_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_LC_RIP_RESUMEN',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RIP_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_RIP_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RIP_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_RIP_RESUMEN.', v_contador);
                
                INSERT INTO INYCEXT.INYC_BAL_RIP_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 24.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 24
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_RIP_RESUMEN: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_RIP_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_RIP_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_RIP_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_RIP_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_RIP_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_RIP_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RIP_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla de Informe Rappel Especial por Cumplimiento de Objetivo de Anulaciones
    --ALM 20180119: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'RECOA' OR informe like '%,RECOA,%' OR informe like '%,RECOA' OR informe like 'RECOA,%' OR informe = 'ALL' THEN
    IF informe = 'RECOA' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_RECOA_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_RECOA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_RECOA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_RECOA_RESUMEN.', v_contador);

            INSERT INTO INYCEXT.INYC_RECOA_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.CUADRO_INSP_OCASO,
                    C.NAME AS N_CREDITO,C.VALUE AS V_CREDITO,C.GENERICBOOLEAN1 AS PRIORITARIO,
                    PAD_AG.FIRSTNAME,PAD_AG.LASTNAME,PAD_AG.SUFFIX,PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 26.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                LEFT OUTER JOIN TCMP.CS_PMCREDITTRACE PMCT ON M.MEASUREMENTSEQ=PMCT.MEASUREMENTSEQ
                    AND PMCT.TENANTID = 'INYC' 
                LEFT OUTER JOIN INYCEXT.INYC_CREDITOS_MES_TEMP C ON PMCT.CREDITSEQ=C.CREDITSEQ
                LEFT OUTER JOIN INYCEXT.INYC_TXN_MES_TEMP ST ON C.SALESTRANSACTIONSEQ = ST.SALESTRANSACTIONSEQ
                LEFT OUTER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON C.GENERICATTRIBUTE4 = PAD_AG.POSITIONNAME
                    AND PAD_INS.PERIODSEQ = PAD_AG.PERIODSEQ
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 26
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                            
            filas := sql%rowcount;            
