            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_RECOA_RESUMEN.', v_contador);

                DELETE INYCEXT.INYC_BAL_RECOA_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
