                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_RECOA_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_RECOA_RESUMEN.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_RECOA_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
