                update_table(mes,'INYC_BAL_RECOA_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_RECOA_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
    
    --MGC 20190322: Nuevo informe de Captacion de Agentes Grupo Eterna que se paga a partir de 2020 pero se empieza a contabilizar en 2019 
    --Carga tabla de Informe Captacion Agentes
    IF informe = 'CAP_E' OR informe LIKE '%,CAP_E,%' OR informe LIKE '%,CAP_E' OR informe LIKE 'CAP_E,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
