            COMMIT;
                
            w_debug('Fin Borrado INYC_CAP_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_CAP_E_RESUMEN. Medidas.', v_contador);

            INSERT INTO INYCEXT.INYC_CAP_E_RESUMEN 
