                w_debug('Inicio Carga INYC_LC_CAP_E_RESUMEN. Medidas.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_CAP_E_RESUMEN 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_ETERNA,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        --Dejamos campos a nulo para introducir el nombre, la position, la tipologia  y la fecha de alta de los agentes captados
                        NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG,
                        NULL AS ID_TIPO_AGENTE_AG,NULL AS TIPO_AGENTE_AG,
                        NULL AS FEC_ALTA_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        AND M.NAME LIKE 'SM-E-CAP-Inspector-%'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
