                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        --Dejamos campos a nulo para introducir el nombre, la position, la tipologia  y la fecha de alta de los agentes captados
                        NULL AS FIRSTNAME_AG,NULL AS LASTNAME_AG,NULL AS SUFFIX_AG,NULL AS POSITIONNAME_AG,
                        NULL AS ID_TIPO_AGENTE_AG,NULL AS TIPO_AGENTE_AG,
                        NULL AS FEC_ALTA_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        AND M.NAME LIKE 'SM-O-CAP-Inspector-%'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 27.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 27
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_CAP_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
                w_debug('Inicio Carga INYC_BAL_CAP_RESUMEN. Agentes Captados.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_CAP_RESUMEN 
                    SELECT
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                        PAD_INS.CUADRO_INSP_OCASO,PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF,
                        PAD_AG.FIRSTNAME AS FIRSTNAME_AG,PAD_AG.LASTNAME AS LASTNAME_AG,PAD_AG.SUFFIX AS SUFFIX_AG,
                        PAD_AG.POSITIONGENERICATTRIBUTE3 AS POSITIONNAME_AG,
                        PAD_AG.POSITIONGENERICNUMBER2 AS ID_TIPO_AGENTE_AG,PAD_AG.POSITIONGENERICATTRIBUTE2 AS TIPO_AGENTE_AG,
                        PAD_AG.POSITIONGENERICDATE1 AS FEC_ALTA_AG
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_AGENTES_MES_TEMP PAD_AG ON PAD_INS.POS_CALLIDUS = PAD_AG.POSITIONGENERICATTRIBUTE14
                        --Solo mostramos agentes captados que se hayan dado de alta hace menos de un a�o (400 dias por los dias del mes actual)
                        --No filtramos por esto para mostrar todos los agentes captados del inspector
                        --AND PAD_AG.POSITIONGENERICDATE1 + 400 > PAD_INS.STARTDATE
                        --ALM 20180307: Por peticion de David, quitamos los agentes que su alta es anterior al 13/12/2017
                        AND PAD_AG.POSITIONGENERICDATE1 >= TO_DATE('20171213','yyyymmdd')
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_AG.PERIODSEQ = M.PERIODSEQ
                        AND PAD_AG.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_AG.PARTICIPANTSEQ = M.PAYEESEQ
                        AND M.NAME LIKE 'SM-O-CAP-Agente-%'
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 27.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 27
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_CAP_RESUMEN. Agentes Captados: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_CAP_RESUMEN.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_CAP_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_CAP_RESUMEN');

                w_debug('Fin Actualizacion Indices INYC_BAL_CAP_RESUMEN.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_BAL_CAP_RESUMEN',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_CAP_RESUMEN');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_CAP_RESUMEN',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;
     
    --Carga tabla Informe Concurso de Produccion Anual
    --ALM 20200601: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'CONCURSO' OR informe like '%,CONCURSO,%' OR informe like '%,CONCURSO' OR informe like 'CONCURSO,%' OR informe = 'ALL' THEN
    IF informe = 'CONCURSO' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        --ALM 20171201: Para este informe no tenemos en cuenta ni balance ni complementaria a petici�n de Celeste
        --IF v_periodo_posteado = 0 THEN
        
        w_debug('Inicio Borrado INYC_CONCURSO.', v_contador);

        DELETE INYCEXT.INYC_CONCURSO WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
        filas := sql%rowcount;            
        COMMIT;
            
        w_debug('Fin Borrado INYC_CONCURSO: '|| to_char(filas) || ' filas borradas.', v_contador);

            
        w_debug('Inicio Carga INYC_CONCURSO.', v_contador);

        INSERT INTO INYCEXT.INYC_CONCURSO 
            SELECT 
                PAD_INS.PERIODSEQ,PD.NAME AS PERIODO, 
                M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA, 
                PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                PAD_INS.POS_PRIN,
                PAD_OF.LASTNAME AS OFICINA,
                PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
            FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
            INNER JOIN TCMP.CSA_PERIODDIMENSION PD ON PAD_INS.PERIODSEQ = PD.PERIODSEQ
                AND PD.TENANTID = 'INYC'
            INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                --AND M.VALUE <> 0
            INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                AND REG.COD_INFORME = 4.1
                AND REG.F_INICIO <= PD.STARTDATE AND REG.F_FIN > PD.STARTDATE
            LEFT OUTER JOIN INYCEXT.INYC_OFICINAS_MES_TEMP PAD_OF ON PAD_INS.PERIODSEQ = PAD_OF.PERIODSEQ
                AND PAD_OF.POSITIONNAME = SUBSTR(PAD_INS.POS_PRIN,1,4)
            INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                AND AG.COD_INFORME = 4
                AND AG.F_INICIO <= PD.STARTDATE AND  AG.F_FIN > PD.STARTDATE
            --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
            ;
                        
        filas := sql%rowcount;            
        COMMIT;           
                
        w_debug('Fin Carga INYC_CONCURSO: '|| to_char(filas) || ' filas.', v_contador);
            
            
        w_debug('Inicio Actualizacion Indices INYC_CONCURSO.', v_contador);

        --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_CONCURSO COMPUTE STATISTICS FOR ALL INDEXES';
        DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_CONCURSO');

        w_debug('Fin Actualizacion Indices INYC_CONCURSO.', v_contador);
            
            
        w_debug('Inicio actualizacion del parametro INYC_CONCURSO',v_contador);
        
        --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
        update_table(mes,'INYC_CONCURSO');
        
        w_debug('Fin actualizacion del parametro INYC_CONCURSO',v_contador);
        
            
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;           
    
    --Carga tabla Informe Incentivo Especial Anual
    --ALM 20200601: Dejamos la carga de las tablas, pero solo bajo peticion.
    --IF informe = 'INCENTIVO' OR informe like '%,INCENTIVO,%' OR informe like '%,INCENTIVO' OR informe like 'INCENTIVO,%' OR informe = 'ALL' THEN
    IF informe = 'INCENTIVO' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_INCENTIVO.', v_contador);

            DELETE INYCEXT.INYC_INCENTIVO WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
            
            filas := sql%rowcount;            
            COMMIT;
            
            w_debug('Fin Borrado INYC_INCENTIVO: '|| to_char(filas) || ' filas borradas.', v_contador);

            
            w_debug('Inicio Carga INYC_INCENTIVO.', v_contador);

            INSERT INTO INYCEXT.INYC_INCENTIVO 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 5.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 5
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                        
            filas := sql%rowcount;            
            COMMIT;           
                
            w_debug('Fin Carga INYC_INCENTIVO: '|| to_char(filas) || ' filas.', v_contador);
            
            
            w_debug('Inicio Actualizacion Indices INYC_INCENTIVO.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_INCENTIVO COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_INCENTIVO');

            w_debug('Fin Actualizacion Indices INYC_INCENTIVO.', v_contador);
            
            
            w_debug('Inicio actualizacion del parametro INYC_INCENTIVO',v_contador);
        
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_INCENTIVO');
        
            w_debug('Fin actualizacion del parametro INYC_INCENTIVO',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
            IF v_periodo_finalizado = 0 THEN
            
                w_debug('Inicio Borrado INYC_LC_INCENTIVO.', v_contador);

                DELETE INYCEXT.INYC_LC_INCENTIVO WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_LC_INCENTIVO: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_LC_INCENTIVO.', v_contador);

                INSERT INTO INYCEXT.INYC_LC_INCENTIVO 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 5.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 5
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_LC_INCENTIVO: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_LC_INCENTIVO.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_LC_INCENTIVO COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_LC_INCENTIVO');

                w_debug('Fin Actualizacion Indices INYC_LC_INCENTIVO.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_LC_INCENTIVO',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_LC_INCENTIVO');
            
                w_debug('Fin actualizacion del parametro INYC_LC_INCENTIVO',v_contador);
            
            --ALM 20171113: Si el periodo esta posteado y finalizado cargamos las tablas de balances
            ELSE
        
                w_debug('Inicio Borrado INYC_BAL_INCENTIVO.', v_contador);

                DELETE INYCEXT.INYC_BAL_INCENTIVO WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
                filas := sql%rowcount;            
                COMMIT;
                
                w_debug('Fin Borrado INYC_BAL_INCENTIVO: '|| to_char(filas) || ' filas borradas.', v_contador);

                
                w_debug('Inicio Carga INYC_BAL_INCENTIVO.', v_contador);

                INSERT INTO INYCEXT.INYC_BAL_INCENTIVO 
                    SELECT 
                        PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                        PAD_INS.PERIODSEQ,PAD_INS.YEAR,PAD_INS.STARTDATE,
                        M.NAME AS N_MEDIDA,M.VALUE AS V_MEDIDA,
                        PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,
                        PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE
                    FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                    INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                        AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                        AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                        --AND M.VALUE <> 0
                    INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                        AND REG.COD_INFORME = 5.1
                        AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                    INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                        AND AG.COD_INFORME = 5
                        AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                    --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                    ;
                            
                filas := sql%rowcount;            
                COMMIT;           
                    
                w_debug('Fin Carga INYC_BAL_INCENTIVO: '|| to_char(filas) || ' filas.', v_contador);
                
                
                w_debug('Inicio Actualizacion Indices INYC_BAL_INCENTIVO.', v_contador);

                --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_BAL_INCENTIVO COMPUTE STATISTICS FOR ALL INDEXES';
                DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_BAL_INCENTIVO');

                w_debug('Fin Actualizacion Indices INYC_BAL_INCENTIVO.', v_contador);
                
                
                w_debug('Inicio actualizacion del parametro INYC_INCENTIVO',v_contador);
            
                --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
                update_table(mes,'INYC_BAL_INCENTIVO');
            
                w_debug('Fin actualizacion del parametro INYC_BAL_INCENTIVO',v_contador);
            
            END IF;
        
        END IF;
        
        --Revisamos si se debe detener el proceso
        w_stop('Revisar si detenemos el proceso');
        IF v_stop = 0 THEN
            w_debug('CONTROL PARA NO EJECUTAR EL PROCESO. REVISAR CLASIFICACION!!!!!!!', v_contador);
            
            RETURN;
        END IF;

    END IF;           
    
    --ALM 20181107: Nuevo informe para la Campana Comercial de Eterna 
    --Carga tabla del Informe Campana Comercial Eterna 
    IF informe = 'CC_E' OR informe LIKE '%,CC_E,%' OR informe LIKE '%,CC_E' OR informe LIKE 'CC_E,%' OR informe = 'ALL' THEN
        --ALM 20170420: Comprobamos si el periodo esta cerrado y si no lo esta cargamos las tablas de cierre
        --ALM 20171113: Comprobamos si el periodo esta posteado y si no lo esta cargamos las tablas de cierre
        --IF v_periodo_finalizado = 0 THEN
        IF v_periodo_posteado = 0 THEN
        
            w_debug('Inicio Borrado INYC_CC_E_RESUMEN.', v_contador);

            DELETE INYCEXT.INYC_CC_E_RESUMEN WHERE PERIODSEQ = v_periodRow.PERIODSEQ;
                
            filas := sql%rowcount;            
            COMMIT;
                
            w_debug('Fin Borrado INYC_CC_E_RESUMEN: '|| to_char(filas) || ' filas borradas.', v_contador);

                
            w_debug('Inicio Carga INYC_CC_E_RESUMEN. Medidas.', v_contador);

            INSERT INTO INYCEXT.INYC_CC_E_RESUMEN 
                SELECT 
                    PAD_INS.PARTICIPANTSEQ,PAD_INS.POSITIONSEQ_PRIN,
                    PAD_INS.PERIODSEQ,PAD_INS.PERIODO,PAD_INS.QUARTER,PAD_INS.YEAR,PAD_INS.STARTDATE,
                    M.NAME AS N_MEDIDA, M.VALUE AS V_MEDIDA, 
                    PAD_INS.BOUSERID,PAD_INS.FIRSTNAME,PAD_INS.LASTNAME,PAD_INS.SUFFIX,PAD_INS.POSITIONNAME,
                    PAD_INS.POS_PRIN,PAD_INS.ID_TIPO_AGENTE,PAD_INS.TIPO_AGENTE,PAD_INS.NIF
                FROM INYCEXT.INYC_AGENTES_PRIN_MES_TEMP PAD_INS
                INNER JOIN INYCEXT.INYC_MEDIDAS_MES_TEMP M ON PAD_INS.PERIODSEQ = M.PERIODSEQ
                    AND PAD_INS.POSITIONSEQ = M.POSITIONSEQ
                    AND PAD_INS.PARTICIPANTSEQ = M.PAYEESEQ
                    --AND M.VALUE <> 0
                INNER JOIN INYCEXT.INYC_CONF_INF_REGLAS REG ON M.NAME = REG.REGLA
                    AND REG.COD_INFORME = 28.1
                    AND REG.F_INICIO <= PAD_INS.STARTDATE AND  REG.F_FIN > PAD_INS.STARTDATE 
                INNER JOIN INYCEXT.INYC_CONF_INF_AGENTES AG ON PAD_INS.ID_TIPO_AGENTE = AG.ID_TIPO_AGENTE
                    AND AG.COD_INFORME = 28
                    AND AG.F_INICIO <= PAD_INS.STARTDATE AND  AG.F_FIN > PAD_INS.STARTDATE
                --WHERE PAD_INS.PERIODSEQ = v_periodRow.PERIODSEQ
                ;
                            
            filas := sql%rowcount;            
            COMMIT;           
                    
            w_debug('Fin Carga INYC_CC_E_RESUMEN. Medidas: '|| to_char(filas) || ' filas.', v_contador);
                
                
            w_debug('Inicio Actualizacion Indices INYC_CC_E_RESUMEN.', v_contador);

            --EXECUTE IMMEDIATE 'ANALYZE TABLE INYCEXT.INYC_CC_E_RESUMEN COMPUTE STATISTICS FOR ALL INDEXES';
            DBMS_STATS.GATHER_TABLE_STATS('INYCEXT','INYC_CC_E_RESUMEN');

            w_debug('Fin Actualizacion Indices INYC_CC_E_RESUMEN.', v_contador);
                
                
            w_debug('Inicio actualizacion del parametro INYC_CC_E_RESUMEN',v_contador);
            
            --Actualizamos el parametro de ultima actualizacion en la tabla INYC_FECHAS_WEBI 
            update_table(mes,'INYC_CC_E_RESUMEN');
            
            w_debug('Fin actualizacion del parametro INYC_CC_E_RESUMEN',v_contador);
    
        --ALM 20170420: Si el periodo esta cerrado cargamos las tablas de balances
        ELSE
            --ALM 20171113: Si el periodo esta posteado, comprobamos si esta finalizado y si no lo esta cargamos las tablas de liquidacion complementaria
